            font-size: 2rem;
            margin-bottom: 10px;
        }

        .hero-text p {
            font-size: 1.1rem;
            opacity: 0.9;
            max-width: 600px;
        }

        .hero-stats {
            display: flex;
            gap: 30px;
        }

        .stat-box {
            text-align: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 15px 25px;
            border-radius: 8px;
            backdrop-filter: blur(5px);
        }

        .stat-number {
            font-size: 1.5rem;
            font-weight: 700;
            display: block;
        }

        .stat-label {
            font-size: 0.85rem;
            opacity: 0.8;
        }

        /* --- Courses Grid --- */
        .content-area {
            padding: 0 40px 40px 40px;
        }

        .section-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
            margin-top: 20px;
        }

        .section-title {
            font-size: 1.5rem;
            color: var(--dark-text);
        }

        .view-all {
            color: var(--secondary-blue);
            font-weight: 600;
            font-size: 0.9rem;
        }

        .courses-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 25px;
        }

        .course-card {
            background-color: var(--white);
            border-radius: 10px;
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: var(--transition);
            display: flex;
            flex-direction: column;
        }

        .course-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
        }

        .card-image {
            height: 160px;
            background-color: #ddd;
            position: relative;
        }

        /* Placeholder colors for images */
        .img-1 { background: linear-gradient(to right, #4facfe 0%, #00f2fe 100%); }
        .img-2 { background: linear-gradient(to top, #cfd9df 0%, #e2ebf0 100%); }
        .img-3 { background: linear-gradient(120deg, #f6d365 0%, #fda085 100%); }
        .img-4 { background: linear-gradient(to top, #5f72bd 0%, #9b23ea 100%); }

        .badge {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: rgba(0, 0, 0, 0.6);
            color: white;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.7rem;
            text-transform: uppercase;
        }

        .card-content {
            padding: 20px;
            flex-grow: 1;
            display: flex;
            flex-direction: column;
        }

        .category {
            color: var(--secondary-blue);
            font-size: 0.8rem;
            font-weight: 600;
            margin-bottom: 8px;
            text-transform: uppercase;
        }

        .course-title {
            font-size: 1.1rem;
            font-weight: 700;
            margin-bottom: 10px;
            color: var(--dark-text);
            line-height: 1.4;
        }

        .instructor {
            font-size: 0.85rem;
            color: var(--light-text);
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .card-footer {
            margin-top: auto;
            border-top: 1px solid #f0f0f0;
            padding-top: 15px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .rating {
            color: #ffc107;
            font-size: 0.9rem;
            font-weight: 600;
        }

        .rating span {
            color: var(--light-text);
            font-weight: 400;
            font-size: 0.8rem;
        }

        .price {
            font-weight: 700;
            color: var(--primary-blue);
            font-size: 1.1rem;
        }

        /* --- Responsive Design --- */
        @media (max-width: 992px) {
            .hero {
                flex-direction: column;
                text-align: center;
                gap: 20px;
            }
            .hero-stats {
                justify-content: center;
            }
        }

        @media (max-width: 768px) {
            .sidebar {
                transform: translateX(-100%);
            }
            .sidebar.active {
                transform: translateX(0);
            }
            .main-content {
                margin-left: 0;
            }
            .content-area {
                padding: 0 20px 20px 20px;
            }
            .hero {
                margin: 20px;
            }
            header {
                padding: 0 20px;
            }
            .search-bar {
                display: none; /* Hide search on small mobile for simplicity */
            }
        }
    </style>
