<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>LUMIÈRE | Immersive Art Gallery</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --bg-color: #050505;
            --text-color: #f0f0f0;
            --accent-color: #d4af37; /* Gold */
            --overlay-bg: rgba(0, 0, 0, 0.85);
            --transition-speed: 0.6s;
            --font-heading: 'Playfair Display', serif;
            --font-body: 'Inter', sans-serif;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: var(--font-body);
            overflow: hidden; /* Prevent scrolling, full screen app feel */
            height: 100vh;
            width: 100vw;
        }

        /* --- TYPOGRAPHY --- */
        h1, h2, h3 {
            font-family: var(--font-heading);
            font-weight: 400;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: color 0.3s ease;
        }

        a:hover {
            color: var(--accent-color);
        }

        /* --- NAVIGATION --- */
        nav {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            padding: 2rem 3rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            z-index: 100;
            mix-blend-mode: difference;
        }

        .logo {
            font-size: 1.5rem;
            letter-spacing: 0.2rem;
            font-weight: 700;
            text-transform: uppercase;
        }

        .nav-links {
            display: flex;
            gap: 2rem;
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 0.1rem;
        }

        /* --- SLIDESHOW CONTAINER --- */
        .slideshow-container {
            position: relative;
            width: 100%;
            height: 100vh;
        }

        .slide {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            opacity: 0;
            transition: opacity var(--transition-speed) ease-in-out;
            display: flex;
            align-items: center;
            justify-content: center;
            pointer-events: none; /* Let clicks pass through inactive slides */
        }

        .slide.active {
            opacity: 1;
            pointer-events: all;
            z-index: 1;
        }

        /* Background Image Handling */
        .slide-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-size: cover;
            background-position: center;
            z-index: -1;
            filter: brightness(0.6); /* Darken image for text contrast */
            transform: scale(1.05);
            transition: transform 8s ease; /* Slow zoom effect */
        }

        .slide.active .slide-bg {
            transform: scale(1);
        }

        /* --- CONTENT LAYOUT --- */
        .content-wrapper {
            display: grid;
            grid-template-columns: 1fr 1fr;
            width: 90%;
            max-width: 1400px;
            height: 80vh;
            align-items: center;
            gap: 4rem;
        }

        /* Left Side: Artwork */
        .artwork-display {
            position: relative;
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .art-frame {
            width: 100%;
            max-width: 500px;
            aspect-ratio: 3/4;
            background-color: #1a1a1a;
            box-shadow: 0 20px 50px rgba(0,0,0,0.5);
            overflow: hidden;
            position: relative;
            border: 1px solid rgba(255,255,255,0.1);
        }

        .art-frame img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .art-frame:hover img {
            transform: scale(1.05);
        }

        /* Right Side: Information */
        .info-panel {
            display: flex;
            flex-direction: column;
            justify-content: center;
            height: 100%;
            padding-right: 2rem;
        }

        .artist-name {
            font-size: 1rem;
            text-transform: uppercase;
            letter-spacing: 0.2rem;
            color: var(--accent-color);
            margin-bottom: 1rem;
        }

        .art-title {
            font-size: 4rem;
            line-height: 1.1;
            margin-bottom: 1.5rem;
            background: linear-gradient(to right, #fff, #aaa);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .art-description {
            font-size: 1.1rem;
            line-height: 1.6;
            color: #ccc;
            margin-bottom: 2.5rem;
            max-width: 500px;
            border-left: 2px solid var(--accent-color);
            padding-left: 1.5rem;
        }

        /* --- BUTTONS --- */
        .actions {
            display: flex;
            gap: 1.5rem;
        }

        .btn {
            padding: 1rem 2rem;
            border: 1px solid rgba(255,255,255,0.3);
            background: transparent;
            color: #fff;
            text-transform: uppercase;
            letter-spacing: 0.1rem;
            font-size: 0.8rem;
            cursor: pointer;
            transition: all 0.3s ease;
            position: relative;
            overflow: hidden;
        }

        .btn::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: var(--accent-color);
            transition: left 0.3s ease;
            z-index: -1;
        }

        .btn:hover::before {
            left: 0;
        }

        .btn:hover {
            border-color: var(--accent-color);
            color: #000;
        }

        .btn-primary {
            background: #fff;
            color: #000;
            border: none;
        }

        .btn-primary:hover {
            background: var(--accent-color);
        }

        /* --- NAVIGATION CONTROLS --- */
        .controls {
            position: absolute;
            bottom: 3rem;
            right: 3rem;
            display: flex;
            gap: 1rem;
            z-index: 10;
        }

        .control-btn {
            width: 50px;
            height: 50px;
            border: 1px solid rgba(255,255,255,0.2);
            border-radius: 50%;
            background: rgba(0,0,0,0.3);
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .control-btn:hover {
            background: var(--accent-color);
            border-color: var(--accent-color);
            color: #000;
        }

        /* --- PROGRESS BAR --- */
        .progress-container {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 4px;
            background: rgba(255,255,255,0.1);
            z-index: 10;
        }

        .progress-bar {
            height: 100%;
            background: var(--accent-color);
            width: 0%;
            transition: width 0.1s linear;
        }

        /* --- MODAL (Virtual View) --- */
        .modal {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.95);
            z-index: 1000;
            display: flex;
            align-items: center;
            justify-content: center;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.4s ease;
        }

        .modal.open {
            opacity: 1;
            pointer-events: all;
        }

        .modal-content {
            text-align: center;
            max-width: 600px;
        }

        .modal-title {
            font-size: 2rem;
            margin-bottom: 1rem;
            color: var(--accent-color);
        }

