    <script>
        // Data for the slider
        const slides = document.querySelectorAll('.slide');
        const menuItems = document.querySelectorAll('.menu-item');
        const captionText = document.getElementById('caption-text');
        let currentSlide = 0;

        // Function to change slide based on index
        function changeSlide(index) {
            // Remove active class from all
            slides.forEach(slide => slide.classList.remove('active'));
            menuItems.forEach(item => item.classList.remove('active'));

            // Add active class to current
            slides[index].classList.add('active');
            menuItems[index].classList.add('active');

            // Update caption text based on the clicked item's title
            const title = menuItems[index].querySelector('h3').innerText;
            captionText.innerText = title;

            currentSlide = index;
        }

        // Optional: Auto-rotate slider every 5 seconds
        setInterval(() => {
            let nextIndex = (currentSlide + 1) % slides.length;
            changeSlide(nextIndex);
        }, 5000);
    </script>
