                    <div class="service-card">
                        <span class="icon-sketch">✎</span>
                        <h3>Layout</h3>
                        <p>Editorial design and web layouts that prioritize readability and aesthetics.</p>
                    </div>
                </div>
            </div>
        </section>

        <!-- Portfolio Section -->
        <section id="portfolio" class="container">
            <div class="sketch-box">
                <div class="tape"></div>
                <h2 style="text-align: center;">Selected Works</h2>
                <div class="portfolio-grid">
                    <!-- Project 1 -->
                    <div class="project-item">
                        <!-- Using placeholder images -->
                        <img src="https://images.unsplash.com/photo-1542359649-31e03cd4d909?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=60" alt="Project 1">
                        <div class="project-overlay">
                            <h3>Brand Identity</h3>
                            <p>Coffee Shop Rebrand</p>
                        </div>
                    </div>
                    <!-- Project 2 -->
                    <div class="project-item">
                        <img src="https://images.unsplash.com/photo-1586717791821-3f44a5638d48?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=60" alt="Project 2">
