                            <h3>Editorial</h3>
                            <p>Architecture Magazine</p>
                        </div>
                    </div>
                    <!-- Project 3 -->
                    <div class="project-item">
                        <img src="https://images.unsplash.com/photo-1626785774573-4b799314346d?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=60" alt="Project 3">
                        <div class="project-overlay">
                            <h3>Packaging</h3>
                            <p>Organic Skincare</p>
                        </div>
                    </div>
                </div>
            </div>
        </section>

        <!-- Contact Section -->
        <section id="contact" class="container">
            <div class="sketch-box">
                <div class="tape"></div>
                <h2 style="text-align: center;">Get in Touch</h2>
                <div class="contact-wrapper">
                    <div class="contact-info">
                        <p>Ready to sketch out your next big idea? Drop us a line or find us on social media.</p>
