            background-image: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?q=80&w=2070&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            filter: brightness(0.7);
            transition: transform 10s ease;
        }

        .hero:hover .hero-bg {
            transform: scale(1.05);
        }

        .hero-content {
            position: relative;
            z-index: 2;
            text-align: center;
            color: #fff;
            mix-blend-mode: difference;
        }

        .hero h1 {
            font-size: 4rem;
            margin-bottom: 20px;
        }

        .hero p {
            font-size: 1.2rem;
            color: #ddd;
            max-width: 600px;
            margin: 0 auto;
        }

        /* --- GALLERY SECTION --- */
        .gallery-section {
