    <style>
        /* --- CSS Variables & Reset --- */
        :root {
            --primary-color: #008080; /* Teal */
            --primary-dark: #005f5f;
            --secondary-color: #e0f2f1; /* Light Teal Background */
            --accent-color: #4db6ac; /* Lighter Teal */
            --text-dark: #2c3e50;
            --text-light: #546e7a;
