            align-items: center;
            justify-content: center;
            margin: 0 auto 20px;
        }

        .icon-box svg {
            width: 35px;
            height: 35px;
            fill: var(--primary-color);
        }

        .service-card h3 {
            margin-bottom: 15px;
            color: var(--text-dark);
        }

        .service-card p {
            color: var(--text-light);
            font-size: 0.95rem;
        }

        /* --- About / CTA Section --- */
        .about-cta {
            padding: 100px 0;
            background-color: var(--primary-color);
            color: var(--white);
            text-align: center;
        }

        .about-cta h2 {
            font-size: 2.5rem;
            margin-bottom: 20px;
        }

        .about-cta p {
            max-width: 700px;
            margin: 0 auto 40px;
            font-size: 1.1rem;
            opacity: 0.9;
        }

        .btn-white {
            background-color: var(--white);
            color: var(--primary-color);
        }

        .btn-white:hover {
            background-color: var(--secondary-color);
        }

        /* --- Footer --- */
        footer {
            background-color: #1a252f;
            color: #bdc3c7;
            padding: 60px 0 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h4 {
            color: var(--white);
            margin-bottom: 20px;
            font-size: 1.2rem;
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a:hover {
            color: var(--accent-color);
        }

        .copyright {
            text-align: center;
            padding-top: 20px;
            border-top: 1px solid #34495e;
            font-size: 0.9rem;
        }

        /* --- Responsive Design --- */
        @media (max-width: 768px) {
            .hero-content {
                grid-template-columns: 1fr;
                text-align: center;
            }

            .hero-text h1 {
                font-size: 2.5rem;
            }

            .hero-text p {
                margin: 0 auto 30px;
            }

            .nav-links {
                display: none; /* Simple hiding for mobile demo */
            }

            .nav-container {
                justify-content: center;
            }
        }
    </style>
</head>
