        .mockup {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 20px;
            padding: 20px;
            box-shadow: 0 20px 50px rgba(0,0,0,0.5);
            transform: perspective(1000px) rotateY(-10deg) rotateX(5deg);
            transition: transform 0.5s ease;
            animation: float 6s infinite ease-in-out;
        }

        .mockup:hover {
            transform: perspective(1000px) rotateY(0deg) rotateX(0deg);
        }

        .mockup-header {
            display: flex;
            gap: 8px;
            margin-bottom: 20px;
        }
        .dot { width: 12px; height: 12px; border-radius: 50%; }
        .red { background: #ef4444; } .yellow { background: #f59e0b; } .green { background: #10b981; }

        .mockup-body {
            display: grid;
            grid-template-columns: 1fr 2fr;
            gap: 15px;
            height: 300px;
        }
        .sidebar { background: rgba(255,255,255,0.05); border-radius: 8px; }
        .main-area { display: flex; flex-direction: column; gap: 10px; }
        .skeleton { background: rgba(255,255,255,0.1); border-radius: 8px; }
        .skeleton.w-80 { width: 80%; } .skeleton.w-60 { width: 60%; } .skeleton.h-20 { height: 20px; } .skeleton.h-40 { height: 40px; }

        /* --- FEATURES SECTION --- */
        .features {
            padding: 100px 0;
            background: #0b1120;
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
