            overflow: hidden;
        }

        /* Abstract Art for Story */
        .story-img::before {
            content: '';
            position: absolute;
            width: 150%;
            height: 150%;
            background: conic-gradient(from 0deg, transparent, var(--primary), transparent);
            animation: spin 10s linear infinite;
            opacity: 0.3;
        }

        .story-content h2 {
            font-size: 2.5rem;
            margin-bottom: 1.5rem;
        }
        .story-content p {
            color: var(--gray);
            margin-bottom: 1.5rem;
            font-size: 1.1rem;
        }

        /* --- TESTIMONIALS --- */
        .testimonials {
            padding: 100px 0;
            background: #0b1120;
        }

        .testimonial-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .testimonial-card {
            background: var(--dark);
            padding: 2rem;
            border-radius: var(--radius);
            border: 1px solid rgba(255,255,255,0.05);
        }

        .stars { color: #f59e0b; margin-bottom: 1rem; }
        .quote { font-style: italic; color: var(--light); margin-bottom: 1.5rem; }
        .author { display: flex; align-items: center; gap: 1rem; }
        .avatar { width: 50px; height: 50px; border-radius: 50%; background: var(--gray); }
        .author-info h4 { font-size: 1rem; }
        .author-info span { font-size: 0.85rem; color: var(--gray); }

        /* --- PRICING --- */
        .pricing { padding: 100px 0; }

        .pricing-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
            max-width: 1000px;
            margin: 0 auto;
        }

        .price-card {
            background: rgba(255,255,255,0.03);
            padding: 3rem 2rem;
            border-radius: 20px;
            text-align: center;
            border: 1px solid rgba(255,255,255,0.05);
            transition: 0.3s;
        }

        .price-card.featured {
            background: rgba(99, 102, 241, 0.1);
            border: 1px solid var(--primary);
            transform: scale(1.05);
        }

        .price { font-size: 3rem; font-weight: 800; margin: 1.5rem 0; }
        .price span { font-size: 1rem; color: var(--gray); font-weight: 400; }

        .features-list { margin: 2rem 0; text-align: left; }
        .features-list li { margin-bottom: 0.8rem; color: var(--gray); display: flex; align-items: center; gap: 10px; }
        .check { color: var(--primary); }

        /* --- FAQ --- */
        .faq { padding: 100px 0; background: #0b1120; }

        .faq-item {
            border-bottom: 1px solid rgba(255,255,255,0.1);
            margin-bottom: 1rem;
        }

        .faq-question {
            width: 100%;
            text-align: left;
            background: none;
            border: none;
            color: var(--light);
            padding: 1.5rem 0;
            font-size: 1.1rem;
            font-weight: 600;
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .faq-answer {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease;
            color: var(--gray);
        }

        .faq-answer p { padding-bottom: 1.5rem; }

        .faq-toggle { transition: 0.3s; }
        .active .faq-toggle { transform: rotate(45deg); }
        .active .faq-answer { max-height: 200px; }

        /* --- FOOTER --- */
        footer {
            padding: 50px 0;
            border-top: 1px solid rgba(255,255,255,0.05);
            text-align: center;
            color: var(--gray);
        }

        /* --- ANIMATIONS --- */
        @keyframes float {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-20px); }
        }

        @keyframes pulse {
            0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(99, 102, 241, 0.7); }
            70% { transform: scale(1); box-shadow: 0 0 0 10px rgba(99, 102, 241, 0); }
            100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
        }

        @keyframes spin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .hero-content, .story-grid { grid-template-columns: 1fr; text-align: center; }
            .hero-text h1 { font-size: 2.5rem; }
            .mockup { transform: none; margin-top: 2rem; }
            .nav-links { display: none; } /* Simplified for single file demo */
            .price-card.featured { transform: scale(1); }
        }
    </style>
