        .sidebar {
            position: fixed;
            top: 0;
            left: 0;
            height: 100%;
            width: 250px;
            background: rgba(20, 20, 20, 0.95);
            backdrop-filter: blur(10px);
            border-right: 1px solid rgba(255, 255, 255, 0.1);
            transform: translateX(-100%); /* Hidden by default */
            transition: transform 0.4s cubic-bezier(0.77, 0, 0.175, 1);
            z-index: 100;
            display: flex;
            flex-direction: column;
            justify-content: center;
            padding-left: 40px;
        }

        /* Trigger Area: Hovering anywhere on the left 50px reveals the menu */
        .sidebar-trigger {
            position: fixed;
            top: 0;
            left: 0;
            width: 50px;
            height: 100%;
            z-index: 99;
            /* Optional: visual cue for the trigger zone */
            /* background: rgba(255,0,0,0.1); */ 
        }

        /* Hover State */
        .sidebar-trigger:hover + .sidebar {
            transform: translateX(0);
        }

        /* Navigation Links */
        .sidebar ul {
            list-style: none;
        }

        .sidebar ul li {
            margin-bottom: 25px;
            opacity: 0;
            transform: translateX(-20px);
            transition: opacity 0.3s ease, transform 0.3s ease;
        }

        /* Staggered animation for links when menu opens */
        .sidebar-trigger:hover + .sidebar ul li {
            opacity: 1;
            transform: translateX(0);
        }

        /* Delays for stagger effect */
        .sidebar-trigger:hover + .sidebar ul li:nth-child(1) { transition-delay: 0.1s; }
        .sidebar-trigger:hover + .sidebar ul li:nth-child(2) { transition-delay: 0.2s; }
        .sidebar-trigger:hover + .sidebar ul li:nth-child(3) { transition-delay: 0.3s; }
        .sidebar-trigger:hover + .sidebar ul li:nth-child(4) { transition-delay: 0.4s; }

