        /* --- MAIN CONTENT AREA --- */
        .main-content {
            margin-left: var(--sidebar-width);
            width: calc(100% - var(--sidebar-width));
            height: 100vh;
            overflow-y: auto;
            scroll-behavior: smooth;
            position: relative;
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 90vh;
            width: 100%;
            position: relative;
            display: flex;
            align-items: center;
            padding: 0 80px;
            overflow: hidden;
        }

        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            /* Abstract vibrant gradient image */
            background: 
                radial-gradient(circle at 80% 20%, var(--accent-secondary) 0%, transparent 40%),
                radial-gradient(circle at 20% 80%, var(--accent-primary) 0%, transparent 40%),
                url('https://images.unsplash.com/photo-1550684848-fac1c5b4e853?q=80&w=2070&auto=format&fit=crop') center/cover no-repeat;
            opacity: 0.6;
            filter: grayscale(40%) contrast(120%);
            z-index: 0;
        }

        .hero-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, var(--bg-dark) 0%, transparent 50%);
            z-index: 1;
        }

        .hero-text {
            position: relative;
            z-index: 2;
            max-width: 800px;
        }

        .hero-title {
            font-size: 6rem;
            line-height: 0.9;
            font-weight: 800;
            margin-bottom: 30px;
            text-transform: uppercase;
        }

        .hero-title .outline {
            -webkit-text-stroke: 2px var(--text-main);
            color: transparent;
        }

        .hero-title .filled {
            color: var(--accent-primary);
            text-shadow: 0 0 20px rgba(204, 255, 0, 0.3);
        }

        .hero-subtitle {
            font-family: var(--font-body);
            font-size: 1.1rem;
            color: var(--text-muted);
            margin-bottom: 40px;
            max-width: 500px;
        }

        .cta-btn {
            display: inline-block;
            padding: 15px 40px;
            background: var(--text-main);
            color: var(--bg-dark);
            font-weight: 700;
            text-decoration: none;
            text-transform: uppercase;
            font-size: 0.9rem;
            transition: transform 0.3s ease, background 0.3s;
        }

        .cta-btn:hover {
            transform: translateY(-5px);
            background: var(--accent-primary);
        }

        /* --- FEATURED PROJECTS (SCROLLING) --- */
        .projects-section {
            padding: 80px;
            background-color: var(--bg-dark);
            min-height: 100vh;
        }

        .section-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            margin-bottom: 60px;
            border-bottom: 1px solid #333;
            padding-bottom: 20px;
        }

        .section-title {
            font-size: 3rem;
            text-transform: uppercase;
        }

        .section-title span {
            color: var(--accent-secondary);
        }

        .project-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));
            gap: 40px;
        }

        .project-card {
            background: var(--bg-panel);
            border: 1px solid #333;
            overflow: hidden;
            transition: all 0.4s ease;
            position: relative;
            group: cursor;
        }

        .project-card:hover {
            border-color: var(--accent-primary);
            transform: translateY(-10px);
        }

        .card-image {
            height: 300px;
            width: 100%;
            overflow: hidden;
            position: relative;
        }

        .card-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.6s ease;
            filter: grayscale(100%);
        }

        .project-card:hover .card-image img {
            transform: scale(1.1);
            filter: grayscale(0%);
        }

        .card-content {
            padding: 30px;
        }

        .card-category {
            font-family: var(--font-body);
            font-size: 0.8rem;
            color: var(--accent-primary);
            text-transform: uppercase;
            margin-bottom: 10px;
            display: block;
        }

        .card-title {
            font-size: 1.5rem;
            margin-bottom: 15px;
            font-weight: 700;
        }

        .card-desc {
            font-family: var(--font-body);
            font-size: 0.9rem;
            color: var(--text-muted);
            line-height: 1.6;
        }

        /* --- MARQUEE STRIP --- */
        .marquee-container {
            width: 100%;
            background: var(--accent-primary);
            color: var(--bg-dark);
            padding: 20px 0;
            overflow: hidden;
            white-space: nowrap;
            position: relative;
            margin-top: 50px;
            transform: rotate(-2deg) scale(1.05);
        }

        .marquee-content {
            display: inline-block;
            animation: scroll 20s linear infinite;
            font-size: 2rem;
            font-weight: 900;
            text-transform: uppercase;
        }

        @keyframes scroll {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
        }

        /* --- FOOTER --- */
        footer {
            padding: 80px;
            background: #000;
            border-top: 1px solid #333;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .footer-logo {
            font-size: 1.5rem;
            font-weight: 900;
            color: var(--text-main);
        }

        .socials a {
            color: var(--text-muted);
            margin-left: 20px;
            text-decoration: none;
            font-family: var(--font-body);
            transition: color 0.3s;
        }

        .socials a:hover {
            color: var(--accent-primary);
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 1024px) {
            .hero-title { font-size: 4rem; }
            .projects-section { padding: 40px; }
        }

        @media (max-width: 768px) {
            .layout-container { flex-direction: column; }
            .sidebar {
                width: 100%;
                height: auto;
                position: relative;
                flex-direction: row;
                align-items: center;
                padding: 20px;
                border-right: none;
                border-bottom: 1px solid #333;
            }
            .nav-menu { display: none; } /* Hide nav on mobile for simplicity */
            .sidebar-footer { display: none; }
            .main-content { margin-left: 0; width: 100%; }
            .hero { padding: 0 20px; height: 70vh; }
            .hero-title { font-size: 3rem; }
            .project-grid { grid-template-columns: 1fr; }
            footer { flex-direction: column; gap: 20px; text-align: center; }
            .socials a { margin: 0 10px; }
        }
    </style>
</head>
