<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>LUMINA | Creative Agency</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --bg-color: #0a0a0a;
            --text-color: #f0f0f0;
            --accent-color: #ccff00; /* Neon Lime */
            --secondary-color: #1a1a1a;
            --font-main: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            --font-display: 'Courier New', Courier, monospace;
            --transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: var(--font-main);
            line-height: 1.6;
            overflow-x: hidden;
            cursor: none; /* Custom cursor */
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        /* --- CUSTOM CURSOR --- */
        .cursor {
            width: 20px;
            height: 20px;
            border: 1px solid var(--accent-color);
            border-radius: 50%;
            position: fixed;
            pointer-events: none;
            z-index: 9999;
            transform: translate(-50%, -50%);
            transition: width 0.3s, height 0.3s, background-color 0.3s;
            mix-blend-mode: difference;
        }

        .cursor.hovered {
            width: 50px;
            height: 50px;
            background-color: var(--accent-color);
            border-color: transparent;
            opacity: 0.8;
        }

        /* --- TYPOGRAPHY --- */
        h1, h2, h3 {
            font-weight: 700;
            line-height: 1.1;
            text-transform: uppercase;
        }

        .display-text {
            font-size: clamp(3rem, 10vw, 8rem);
            letter-spacing: -0.02em;
        }

        .section-title {
            font-size: clamp(2rem, 5vw, 4rem);
            margin-bottom: 2rem;
            border-bottom: 1px solid var(--secondary-color);
            padding-bottom: 1rem;
            display: inline-block;
        }

        .mono {
            font-family: var(--font-display);
            font-size: 0.9rem;
            color: var(--accent-color);
            margin-bottom: 1rem;
            display: block;
        }

        /* --- LAYOUT UTILITIES --- */
        .container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 0 2rem;
        }

        section {
            padding: 8rem 0;
            position: relative;
        }

        /* --- NAVIGATION --- */
        nav {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            padding: 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            z-index: 100;
            mix-blend-mode: difference;
        }

        .logo {
            font-weight: 900;
            font-size: 1.5rem;
            letter-spacing: -1px;
        }

        .nav-links {
            display: flex;
            gap: 2rem;
        }

        .nav-links a {
            font-family: var(--font-display);
            font-size: 0.9rem;
            position: relative;
        }

        .nav-links a::after {
            content: '';
            position: absolute;
            bottom: -5px;
            left: 0;
            width: 0%;
            height: 1px;
            background: var(--text-color);
            transition: var(--transition);
        }

        .nav-links a:hover::after {
            width: 100%;
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle at 50% 50%, #1a1a1a 0%, #0a0a0a 70%);
            z-index: -1;
        }

        .hero-content {
            z-index: 2;
        }

        .hero h1 {
            margin-bottom: 2rem;
            opacity: 0;
            transform: translateY(50px);
            animation: fadeUp 1s forwards 0.5s;
        }

        .hero p {
            font-size: 1.2rem;
            max-width: 600px;
            margin: 0 auto 3rem;
            color: #888;
            opacity: 0;
            transform: translateY(30px);
            animation: fadeUp 1s forwards 0.8s;
        }

        .btn {
            display: inline-block;
            padding: 1rem 2.5rem;
            border: 1px solid var(--text-color);
            border-radius: 50px;
            font-family: var(--font-display);
            font-size: 0.9rem;
            transition: var(--transition);
            opacity: 0;
            animation: fadeUp 1s forwards 1.1s;
        }

        .btn:hover {
            background: var(--accent-color);
            color: var(--bg-color);
            border-color: var(--accent-color);
        }

        /* --- MARQUEE --- */
        .marquee {
            background: var(--accent-color);
            color: var(--bg-color);
            padding: 1rem 0;
            overflow: hidden;
            white-space: nowrap;
            position: relative;
            transform: rotate(-2deg) scale(1.05);
            margin: 4rem 0;
        }

        .marquee-content {
            display: inline-block;
            animation: scroll 20s linear infinite;
        }

        .marquee-item {
            font-size: 2rem;
            font-weight: 900;
            text-transform: uppercase;
            margin-right: 4rem;
        }

        /* --- WORK GRID --- */
        .work-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 2rem;
        }

        .work-item {
            position: relative;
            height: 500px;
            overflow: hidden;
            background: var(--secondary-color);
            cursor: pointer;
        }

        .work-img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.6s ease;
            filter: grayscale(100%);
        }

        .work-item:hover .work-img {
            transform: scale(1.1);
            filter: grayscale(0%);
        }

        .work-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 2rem;
            background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
            transform: translateY(100%);
            transition: var(--transition);
        }

        .work-item:hover .work-info {
            transform: translateY(0);
        }

        .work-title {
            font-size: 1.5rem;
            margin-bottom: 0.5rem;
        }

        .work-cat {
            font-family: var(--font-display);
            color: var(--accent-color);
        }

        /* --- SERVICES --- */
        .services-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 1px;
            background: var(--secondary-color); /* Creates borders */
            border: 1px solid var(--secondary-color);
        }

        .service-card {
            background: var(--bg-color);
            padding: 4rem 2rem;
            transition: var(--transition);
        }

        .service-card:hover {
            background: #111;
        }

        .service-num {
            font-family: var(--font-display);
            color: var(--accent-color);
            font-size: 1.5rem;
            margin-bottom: 2rem;
            display: block;
        }

        .service-card h3 {
            font-size: 1.5rem;
            margin-bottom: 1.5rem;
        }

        .service-card p {
            color: #888;
            font-size: 0.95rem;
        }

        /* --- FOOTER --- */
        footer {
            padding: 6rem 0 2rem;
            border-top: 1px solid var(--secondary-color);
        }

        .footer-content {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            flex-wrap: wrap;
            gap: 4rem;
            margin-bottom: 4rem;
        }

        .footer-cta h2 {
            font-size: clamp(2rem, 4vw, 3rem);
            margin-bottom: 1rem;
        }

        .footer-links {
            display: flex;
            gap: 4rem;
        }

        .link-col h4 {
            font-family: var(--font-display);
            margin-bottom: 1.5rem;
            color: var(--accent-color);
        }

        .link-col ul li {
            margin-bottom: 0.8rem;
        }

        .link-col ul li a {
            color: #888;
            transition: 0.3s;
        }

        .link-col ul li a:hover {
            color: var(--text-color);
        }

        .copyright {
            text-align: center;
            font-family: var(--font-display);
            font-size: 0.8rem;
            color: #555;
        }

        /* --- ANIMATIONS --- */
        @keyframes fadeUp {
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes scroll {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .nav-links { display: none; }
            .services-grid { grid-template-columns: 1fr; }
            .work-grid { grid-template-columns: 1fr; }
            .footer-content { flex-direction: column; gap: 2rem; }
            .footer-links { flex-direction: column; gap: 2rem; }
            .cursor { display: none; } /* Hide custom cursor on touch */
            body { cursor: auto; }
        }
    </style>
</head>
