        header {
            position: fixed;
            top: 0;
            width: 100%;
            padding: 20px 40px;
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 1000;
            background: rgba(15, 15, 17, 0.8);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }

        .logo {
            font-family: var(--font-heading);
            font-size: 2rem;
            font-weight: 800;
            letter-spacing: -1px;
            background: var(--gradient);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            text-transform: uppercase;
        }

        /* --- UNIQUE CURVED NAVIGATION --- */
        nav {
            position: fixed;
            bottom: 40px;
            left: 50%;
            transform: translateX(-50%);
            z-index: 1000;
            background: rgba(255, 255, 255, 0.05);
            backdrop-filter: blur(15px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 50px;
            padding: 10px 30px;
            display: flex;
            gap: 30px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
            transition: all 0.4s ease;
        }

        nav:hover {
            transform: translateX(-50%) translateY(-5px);
            box-shadow: 0 15px 40px var(--accent-glow);
            border-color: var(--accent);
        }

        nav a {
            font-size: 0.9rem;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--text-muted);
            position: relative;
        }

        nav a:hover, nav a.active {
            color: #fff;
            text-shadow: 0 0 10px var(--accent);
        }

        nav a::after {
            content: '';
            position: absolute;
            bottom: -5px;
            left: 50%;
            transform: translateX(-50%) scaleX(0);
            width: 5px;
            height: 5px;
            background: var(--accent);
            border-radius: 50%;
            transition: transform 0.3s;
        }

        nav a:hover::after {
            transform: translateX(-50%) scaleX(1);
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        /* Abstract Background Shapes */
        .hero::before {
            content: '';
            position: absolute;
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, var(--accent-glow) 0%, transparent 70%);
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            z-index: -1;
            animation: pulse 6s infinite alternate;
        }

        .hero h1 {
            font-family: var(--font-heading);
            font-size: 5rem;
            line-height: 1.1;
            margin-bottom: 20px;
            background: linear-gradient(to right, #fff, #a0a0a0);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .hero p {
            font-size: 1.2rem;
            color: var(--text-muted);
            max-width: 600px;
            margin-bottom: 40px;
        }

        .scroll-indicator {
            position: absolute;
            bottom: 100px;
            animation: bounce 2s infinite;
            opacity: 0.5;
        }

        /* --- SECTIONS GENERAL --- */
        section {
            padding: 100px 10%;
            min-height: 80vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .section-title {
            font-family: var(--font-heading);
            font-size: 3rem;
            margin-bottom: 60px;
            position: relative;
            display: inline-block;
        }

        .section-title::before {
            content: '';
            position: absolute;
            left: -20px;
            top: 10px;
            width: 10px;
            height: 10px;
            background: var(--accent);
            border-radius: 50%;
        }

        /* --- CASE STUDIES (GRID) --- */
        .case-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .case-card {
            background: var(--bg-card);
            border-radius: 15px;
            overflow: hidden;
            transition: transform 0.3s;
            position: relative;
            height: 400px;
            cursor: pointer;
        }

        .case-card:hover {
            transform: translateY(-10px);
        }

        .case-img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.6;
            transition: opacity 0.3s;
        }

        .case-card:hover .case-img {
            opacity: 0.3;
        }

        .case-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 30px;
            z-index: 2;
        }

        .case-info h3 {
            font-size: 1.5rem;
            margin-bottom: 5px;
        }

        .case-info span {
            color: var(--accent);
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        /* --- TEAM BIOS --- */
        .team-container {
            display: flex;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 40px;
        }

        .team-member {
            flex: 1;
            min-width: 250px;
            text-align: center;
            padding: 40px 20px;
            border: 1px solid rgba(255,255,255,0.05);
            border-radius: 20px;
            transition: 0.3s;
        }

        .team-member:hover {
            background: rgba(255,255,255,0.03);
            border-color: var(--accent);
        }

        .avatar {
            width: 120px;
            height: 120px;
            border-radius: 50%;
            background: #333;
            margin: 0 auto 20px;
            border: 3px solid var(--accent);
            overflow: hidden;
        }

        .avatar img { width: 100%; height: 100%; object-fit: cover; }

        .team-member h3 { margin-bottom: 5px; }
        .team-member p { color: var(--text-muted); font-size: 0.9rem; }

        /* --- TESTIMONIALS --- */
        .testimonials {
            background: linear-gradient(to bottom, var(--bg-dark), #151518);
        }

        .testimonial-slider {
            display: flex;
            gap: 40px;
            overflow-x: auto;
            padding-bottom: 20px;
            scrollbar-width: none; /* Firefox */
        }
        .testimonial-slider::-webkit-scrollbar { display: none; }

        .testimonial-card {
            min-width: 400px;
            background: rgba(255,255,255,0.03);
            padding: 40px;
            border-radius: 20px;
            border-left: 4px solid var(--accent);
        }

        .quote {
            font-size: 1.2rem;
            font-style: italic;
            margin-bottom: 20px;
            color: #fff;
        }

        .client {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .client-info h4 { font-size: 1rem; }
        .client-info span { font-size: 0.8rem; color: var(--text-muted); }

        /* --- FOOTER --- */
        footer {
            background: #000;
            padding: 80px 10% 40px;
            border-top: 1px solid rgba(255,255,255,0.1);
        }

        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 60px;
        }

        .footer-col h4 {
            color: #fff;
            margin-bottom: 20px;
            font-size: 1.2rem;
        }

        .footer-col ul li { margin-bottom: 10px; }
        .footer-col ul li a { color: var(--text-muted); }
        .footer-col ul li a:hover { color: var(--accent); padding-left: 5px; }

        .social-links {
            display: flex;
            gap: 15px;
        }

        .social-btn {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: 0.3s;
        }

        .social-btn:hover {
            background: var(--accent);
            transform: scale(1.1);
        }

        .copyright {
            text-align: center;
            color: #555;
            font-size: 0.8rem;
            padding-top: 20px;
            border-top: 1px solid rgba(255,255,255,0.05);
        }

        /* --- ANIMATIONS --- */
        @keyframes pulse {
            0% { transform: translate(-50%, -50%) scale(1); opacity: 0.5; }
            100% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.8; }
        }

        @keyframes bounce {
            0%, 20%, 50%, 80%, 100% {transform: translateY(0);}
            40% {transform: translateY(-10px);}
            60% {transform: translateY(-5px);}
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .hero h1 { font-size: 3rem; }
            nav { 
                width: 90%; 
                justify-content: space-around; 
                padding: 10px;
                bottom: 20px;
            }
            nav a { font-size: 0.7rem; }
            .testimonial-card { min-width: 300px; }
        }
    </style>
</head>
