            --secondary-color: #97bc62; /* Soft Sage */
            --accent-color: #f4f9f4; /* Very Light Green/White */
            --text-dark: #333333;
            --text-light: #666666;
            --white: #ffffff;
            --border-color: #e0e0e0;
            --shadow: 0 4px 6px rgba(0,0,0,0.05);
            --font-main: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            color: var(--text-dark);
            background-color: var(--accent-color);
            line-height: 1.6;
            display: flex;
            flex-direction: column;
            min-height: 100vh;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: color 0.3s ease;
        }

        ul {
            list-style: none;
        }

        /* --- Header Section --- */
        header {
            width: 100%;
            height: 350px;
            background: linear-gradient(rgba(44, 95, 45, 0.7), rgba(44, 95, 45, 0.5)), 
                        url('https://images.unsplash.com/photo-1541339907198-e08756dedf3f?ixlib=rb-1.2.1&auto=format&fit=crop&w=1920&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: var(--white);
            padding: 20px;
        }

        header h1 {
            font-size: 3.5rem;
            font-weight: 300;
            letter-spacing: 2px;
            margin-bottom: 10px;
            text-shadow: 0 2px 4px rgba(0,0,0,0.3);
        }

        header p {
            font-size: 1.2rem;
            max-width: 600px;
            font-weight: 300;
        }

        /* --- Main Layout --- */
        .container {
            display: flex;
            max-width: 1200px;
            margin: 0 auto;
            width: 100%;
            flex: 1; /* Pushes footer down */
            padding: 40px 20px;
            gap: 40px;
        }

        /* --- Sidebar Navigation --- */
        aside {
            flex: 0 0 280px;
            background: var(--white);
            padding: 30px;
            border-radius: 8px;
            box-shadow: var(--shadow);
            height: fit-content;
        }

        .search-box {
            margin-bottom: 30px;
        }

        .search-box input {
            width: 100%;
            padding: 12px;
            border: 1px solid var(--border-color);
            border-radius: 4px;
            font-size: 0.9rem;
            outline: none;
        }

        .search-box input:focus {
            border-color: var(--primary-color);
        }

        .nav-menu h3 {
            font-size: 1.1rem;
            color: var(--primary-color);
            margin-bottom: 15px;
            text-transform: uppercase;
            letter-spacing: 1px;
            border-bottom: 2px solid var(--secondary-color);
            padding-bottom: 5px;
            display: inline-block;
        }

        .nav-menu ul li {
            margin-bottom: 10px;
        }

        .nav-menu ul li a {
            display: block;
            padding: 10px 15px;
            border-radius: 4px;
            color: var(--text-light);
            font-weight: 500;
        }

        .nav-menu ul li a:hover {
            background-color: var(--secondary-color);
            color: var(--white);
            transform: translateX(5px);
        }

        /* --- Main Content --- */
        main {
            flex: 1;
        }

        .content-card {
            background: var(--white);
            padding: 40px;
            border-radius: 8px;
            box-shadow: var(--shadow);
            margin-bottom: 30px;
        }

        .content-card h2 {
            color: var(--primary-color);
            font-size: 2rem;
            margin-bottom: 20px;
        }

        .content-card p {
            margin-bottom: 20px;
            color: var(--text-light);
            font-size: 1.05rem;
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 20px;
            margin-top: 30px;
        }

        .feature-item {
            background: var(--accent-color);
            padding: 20px;
            border-radius: 6px;
            text-align: center;
            border: 1px solid #e8f5e9;
        }

        .feature-item h4 {
            color: var(--primary-color);
            margin-bottom: 10px;
        }

        /* --- Footer --- */
        footer {
            background-color: #263238; /* Dark Slate */
            color: #cfd8dc;
            padding: 60px 20px 20px;
        }

        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-section h3 {
            color: var(--white);
            margin-bottom: 20px;
            font-size: 1.2rem;
            border-left: 4px solid var(--secondary-color);
            padding-left: 10px;
        }

        /* Testimonials */
        .testimonial {
            font-style: italic;
            margin-bottom: 15px;
            font-size: 0.95rem;
        }
        .testimonial span {
            display: block;
            margin-top: 5px;
            font-weight: bold;
            color: var(--secondary-color);
            font-style: normal;
        }

        /* Newsletter */
        .newsletter-form {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .newsletter-form input {
            padding: 10px;
            border-radius: 4px;
            border: none;
        }

        .btn {
            background-color: var(--secondary-color);
            color: var(--white);
            border: none;
            padding: 10px 20px;
            border-radius: 4px;
            cursor: pointer;
            font-weight: bold;
            transition: background 0.3s;
        }

        .btn:hover {
            background-color: var(--primary-color);
        }

        /* Calendar */
        .calendar-widget {
            background: rgba(255,255,255,0.05);
            padding: 15px;
            border-radius: 6px;
        }

        .event-item {
            display: flex;
            gap: 15px;
            margin-bottom: 15px;
            border-bottom: 1px solid rgba(255,255,255,0.1);
            padding-bottom: 10px;
        }

        .event-date {
            background: var(--primary-color);
            color: var(--white);
            padding: 5px 10px;
            border-radius: 4px;
            text-align: center;
            min-width: 50px;
            height: fit-content;
        }

        .event-date strong {
            display: block;
            font-size: 1.2rem;
        }

        .event-info small {
            display: block;
            color: var(--secondary-color);
        }

        .copyright {
            text-align: center;
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 20px;
            font-size: 0.85rem;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .container {
                flex-direction: column;
            }
            aside {
                width: 100%;
            }
            header h1 {
                font-size: 2.5rem;
            }
        }
    </style>
</head>
