<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chroma & Ink | Creative Studio</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --primary: #FF6B6B;
            --secondary: #4ECDC4;
            --accent: #FFE66D;
            --dark: #292F36;
            --light: #F7FFF7;
            --purple: #6C5CE7;
            --font-hand: 'Comic Sans MS', 'Chalkboard SE', 'Marker Felt', sans-serif;
            --font-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-body);
            background-color: var(--light);
            color: var(--dark);
            overflow-x: hidden;
            line-height: 1.6;
        }

        /* --- TYPOGRAPHY --- */
        h1, h2, h3 {
            font-family: var(--font-hand);
            font-weight: 900;
            letter-spacing: 1px;
        }

        h1 { font-size: 3.5rem; text-shadow: 3px 3px 0px var(--accent); }
        h2 { font-size: 2.5rem; margin-bottom: 1rem; color: var(--purple); }
        p { font-size: 1.1rem; margin-bottom: 1rem; }

        /* --- LAYOUT UTILITIES --- */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .btn {
            display: inline-block;
            padding: 12px 30px;
            background: var(--primary);
            color: white;
            font-family: var(--font-hand);
            font-size: 1.2rem;
            text-decoration: none;
            border-radius: 50px;
            border: 3px solid var(--dark);
            box-shadow: 4px 4px 0px var(--dark);
            transition: all 0.2s ease;
            cursor: pointer;
        }

        .btn:hover {
            transform: translate(-2px, -2px);
            box-shadow: 6px 6px 0px var(--dark);
        }

        .btn:active {
            transform: translate(2px, 2px);
            box-shadow: 1px 1px 0px var(--dark);
        }

        /* --- NAVIGATION (VERTICAL) --- */
        nav {
            position: fixed;
            left: 0;
            top: 0;
            height: 100vh;
            width: 80px;
            background: var(--dark);
            display: flex;
            flex-direction: column;
            align-items: center;
            padding-top: 2rem;
            z-index: 1000;
            border-right: 4px solid var(--dark);
        }

        nav a {
            writing-mode: vertical-rl;
            text-orientation: mixed;
            color: var(--light);
            text-decoration: none;
            font-family: var(--font-hand);
            font-size: 1.2rem;
            margin: 2rem 0;
            padding: 10px;
            transition: 0.3s;
            border-radius: 10px;
        }

        nav a:hover {
            background: var(--secondary);
            color: var(--dark);
            transform: scale(1.1);
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            background: 
                linear-gradient(rgba(255,255,255,0.8), rgba(255,255,255,0.8)),
                url('https://images.unsplash.com/photo-1513364776144-60967b0f800f?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80');
            background-size: cover;
            background-position: center;
            background-attachment: fixed;
            padding-left: 80px; /* Offset for nav */
        }

        .hero-content {
            text-align: center;
            max-width: 800px;
            animation: float 6s ease-in-out infinite;
        }

        .hero h1 {
            color: var(--dark);
            margin-bottom: 20px;
        }

        .hero p {
            font-size: 1.5rem;
            color: #555;
            font-weight: bold;
        }

        /* --- SERVICES SECTION --- */
        .services {
            padding: 5rem 0;
            background-color: var(--light);
            position: relative;
        }

        /* Decorative background blobs */
        .blob {
            position: absolute;
            z-index: -1;
            opacity: 0.1;
        }
        .blob-1 { top: 10%; left: 10%; width: 200px; height: 200px; background: var(--primary); border-radius: 40% 60% 70% 30% / 40% 50% 60% 50%; }
        .blob-2 { bottom: 10%; right: 10%; width: 300px; height: 300px; background: var(--secondary); border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }

        .services-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
            margin-top: 3rem;
        }

        .card {
            background: white;
            padding: 2rem;
            border-radius: 20px;
            border: 3px solid var(--dark);
            box-shadow: 8px 8px 0px rgba(0,0,0,0.1);
            text-align: center;
            transition: transform 0.3s;
        }

        .card:hover {
            transform: translateY(-10px);
        }

        .card-icon {
            font-size: 4rem;
            margin-bottom: 1rem;
            display: block;
        }

        .card.digital { border-color: var(--primary); }
        .card.illustration { border-color: var(--secondary); }
        .card.graphic { border-color: var(--purple); }

        /* --- PORTFOLIO SECTION --- */
        .portfolio {
            padding: 5rem 0;
            background: var(--dark);
            color: var(--light);
        }

        .portfolio h2 { color: var(--accent); text-align: center; }

        .gallery {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 15px;
            margin-top: 2rem;
        }

        .gallery-item {
            height: 250px;
            background-color: #444;
            border-radius: 10px;
            overflow: hidden;
            position: relative;
            cursor: pointer;
        }

        .gallery-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.4s;
        }

        .gallery-item:hover img {
            transform: scale(1.1);
        }

        .overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            background: rgba(255, 107, 107, 0.9);
            color: white;
            padding: 10px;
            transform: translateY(100%);
            transition: transform 0.3s;
            font-family: var(--font-hand);
            text-align: center;
        }

        .gallery-item:hover .overlay {
            transform: translateY(0);
        }

        /* --- CONTACT SECTION --- */
        .contact {
            padding: 5rem 0;
            text-align: center;
            background: var(--accent);
            position: relative;
        }

        .contact-form {
            max-width: 600px;
            margin: 2rem auto;
            background: white;
            padding: 2rem;
            border-radius: 20px;
            border: 3px solid var(--dark);
        }

        input, textarea {
            width: 100%;
            padding: 15px;
            margin-bottom: 15px;
            border: 2px solid #ddd;
            border-radius: 10px;
            font-family: var(--font-body);
            font-size: 1rem;
        }

        input:focus, textarea:focus {
            outline: none;
            border-color: var(--primary);
        }

        /* --- ANIMATED SLIDE-IN CTA --- */
        .slide-in-cta {
            position: fixed;
            bottom: -150px; /* Hidden initially */
            right: 20px;
            background: var(--purple);
            color: white;
            padding: 15px 25px;
            border-radius: 50px;
            border: 3px solid var(--dark);
            box-shadow: 0 5px 15px rgba(0,0,0,0.3);
            font-family: var(--font-hand);
            font-size: 1.2rem;
            cursor: pointer;
            z-index: 999;
            transition: bottom 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .slide-in-cta.visible {
            bottom: 30px;
        }

        .slide-in-cta:hover {
            background: var(--primary);
        }

        /* --- FOOTER --- */
        footer {
            background: var(--dark);
            color: white;
            text-align: center;
            padding: 2rem;
            font-family: var(--font-hand);
        }

        /* --- ANIMATIONS --- */
        @keyframes float {
            0% { transform: translateY(0px); }
            50% { transform: translateY(-15px); }
            100% { transform: translateY(0px); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            nav {
                width: 100%;
                height: 60px;
                flex-direction: row;
                justify-content: space-around;
                padding: 0;
                border-right: none;
                border-bottom: 4px solid var(--dark);
            }
            nav a {
                writing-mode: horizontal-tb;
                margin: 0;
                font-size: 1rem;
            }
            .hero {
                padding-left: 0;
                padding-top: 60px;
            }
            h1 { font-size: 2.5rem; }
        }
    </style>
</head>
