<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Rolling Crumb</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --color-primary: #FF6B6B; /* Vibrant Red */
            --color-secondary: #4ECDC4; /* Teal */
            --color-accent: #FFE66D; /* Mustard Yellow */
            --color-dark: #292F36;
            --color-light: #F7FFF7;
            --font-heading: 'Comic Sans MS', 'Chalkboard SE', 'Marker Felt', sans-serif;
            --font-body: 'Verdana', sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--color-light);
            background-image: radial-gradient(var(--color-secondary) 1px, transparent 1px);
            background-size: 20px 20px;
            font-family: var(--font-body);
            color: var(--color-dark);
            overflow-x: hidden;
        }

        /* --- TYPOGRAPHY --- */
        h1, h2, h3 {
            font-family: var(--font-heading);
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        /* --- NAVIGATION (Horizontal Top) --- */
        nav {
            background-color: var(--color-primary);
            padding: 1rem 2rem;
            display: flex;
            justify-content: center; /* Centered horizontally */
            align-items: center;
            box-shadow: 0 4px 0 rgba(0,0,0,0.1);
            position: sticky;
            top: 0;
            z-index: 100;
            border-bottom: 5px dashed var(--color-accent);
        }

        nav ul {
            list-style: none;
            display: flex;
            gap: 2rem;
        }

        nav a {
            text-decoration: none;
            color: var(--color-light);
            font-family: var(--font-heading);
            font-size: 1.2rem;
            font-weight: bold;
            padding: 0.5rem 1rem;
            border-radius: 20px;
            transition: all 0.3s ease;
            background: rgba(0,0,0,0.1);
        }

        nav a:hover {
            background-color: var(--color-accent);
            color: var(--color-dark);
            transform: rotate(-3deg) scale(1.1);
        }

        /* --- HERO BANNER --- */
        .hero {
            width: 100%;
            height: 60vh;
            background: linear-gradient(135deg, var(--color-secondary), var(--color-primary));
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
            overflow: hidden;
            border-bottom: 10px solid var(--color-dark);
        }

        /* Decorative background elements */
        .hero::before {
            content: '🍔';
            position: absolute;
            font-size: 15rem;
            opacity: 0.1;
            top: -50px;
            left: -50px;
            transform: rotate(20deg);
        }

        .hero::after {
            content: '🍟';
            position: absolute;
            font-size: 12rem;
            opacity: 0.1;
            bottom: -20px;
            right: -20px;
            transform: rotate(-15deg);
        }

        .logo {
            font-size: 5rem;
            color: var(--color-accent);
            text-shadow: 4px 4px 0 var(--color-dark);
            margin-bottom: 1rem;
            animation: bounce 2s infinite;
        }

        .tagline {
            font-size: 1.5rem;
            color: var(--color-light);
            background-color: var(--color-dark);
            padding: 0.5rem 1.5rem;
            transform: rotate(-2deg);
            box-shadow: 5px 5px 0 var(--color-primary);
        }

        /* --- MAIN CONTENT --- */
        .container {
            max-width: 1000px;
            margin: 3rem auto;
            padding: 0 1rem;
        }

        .section-title {
            text-align: center;
            font-size: 2.5rem;
            color: var(--color-primary);
            margin-bottom: 2rem;
            text-shadow: 2px 2px 0 var(--color-dark);
        }

        /* --- MENU GRID --- */
        .menu-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 2rem;
        }

        .menu-item {
            background: white;
            border: 3px solid var(--color-dark);
            border-radius: 15px;
            padding: 1.5rem;
            text-align: center;
            box-shadow: 8px 8px 0 var(--color-secondary);
            transition: transform 0.2s;
            position: relative;
        }

        .menu-item:hover {
            transform: translate(-4px, -4px);
            box-shadow: 12px 12px 0 var(--color-primary);
        }

        .menu-icon {
            font-size: 3rem;
            margin-bottom: 1rem;
            display: block;
        }

        .menu-title {
            font-size: 1.5rem;
            margin-bottom: 0.5rem;
            color: var(--color-dark);
        }

        .menu-desc {
            font-size: 0.9rem;
            color: #666;
            margin-bottom: 1rem;
        }

        .price {
            display: inline-block;
            background-color: var(--color-accent);
            color: var(--color-dark);
            font-weight: bold;
            padding: 0.3rem 0.8rem;
            border-radius: 50px;
            border: 2px solid var(--color-dark);
        }

        /* --- FOOTER (Bottom Right Grouping) --- */
        footer {
            background-color: var(--color-dark);
            color: var(--color-light);
            padding: 3rem 2rem;
            margin-top: 4rem;
            position: relative;
        }

        /* The specific requirement: Contact & Socials grouped in bottom right */
        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: flex-end; /* Pushes content to the right */
            align-items: flex-end;
            gap: 3rem;
        }

        .contact-info {
            text-align: right;
        }

        .contact-info h3 {
            color: var(--color-accent);
            margin-bottom: 0.5rem;
        }

        .contact-info p {
            margin-bottom: 0.3rem;
            font-size: 0.9rem;
        }

        .social-icons {
            display: flex;
            gap: 1rem;
        }

        .social-btn {
            width: 50px;
            height: 50px;
            background-color: var(--color-primary);
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 1.5rem;
            text-decoration: none;
            color: white;
            border: 2px solid var(--color-light);
            transition: transform 0.2s;
        }

        .social-btn:hover {
            transform: scale(1.2) rotate(10deg);
            background-color: var(--color-secondary);
        }

        /* --- ANIMATIONS --- */
        @keyframes bounce {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .logo { font-size: 3rem; }
            .tagline { font-size: 1rem; }
            nav ul { gap: 1rem; font-size: 0.9rem; }
            .footer-content {
                flex-direction: column-reverse; /* Stack on mobile */
                align-items: center;
                justify-content: center;
                text-align: center;
            }
            .contact-info { text-align: center; }
        }
    </style>
</head>
