        .logo span {
            color: #ff7e5f;
        }

        .nav-links {
            display: flex;
            gap: 30px;
        }

        .nav-links li a {
            color: #fff;
            font-size: 1rem;
            font-weight: 500;
            transition: color 0.3s ease;
            position: relative;
        }

        .nav-links li a::after {
            content: '';
            position: absolute;
            width: 0;
            height: 2px;
            bottom: -5px;
            left: 0;
            background-color: #ff7e5f;
            transition: width 0.3s ease;
