const AnimatedStat = ({ end, label, suffix = "" }: { end: number, label: string, suffix?: string }) => {
  const [count, setCount] = useState(0);
  const [ref, setRef] = useState<HTMLDivElement | null>(null);
  const [hasAnimated, setHasAnimated] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasAnimated) {
          setHasAnimated(true);
          let start = 0;
          const duration = 2000;
          const increment = end / (duration / 16);

          const timer = setInterval(() => {
            start += increment;
            if (start >= end) {
              setCount(end);
              clearInterval(timer);
            } else {
              setCount(Math.floor(start));
            }
          }, 16);
        }
      },
      { threshold: 0.5 }
    );

    if (ref) observer.observe(ref);
    return () => observer.disconnect();
  }, [end, hasAnimated, ref]);

  return (
    <div ref={setRef} className="text-center">
      <div className="text-5xl md:text-6xl font-extrabold text-white mb-2">
        {count}{suffix}
      </div>
      <div className="text-emerald-200 font-medium uppercase tracking-wider text-sm">{label}</div>
    </div>
  );
};

