        .hero-subtext {
            font-size: 1.2rem;
            margin-bottom: 40px;
            font-weight: 300;
            letter-spacing: 0.5px;
        }

        .btn {
            display: inline-block;
            padding: 15px 40px;
            background-color: var(--accent-gold);
