        .listing-thumb {
            width: 80px;
            height: 80px;
            object-fit: cover;
            border-radius: 2px;
        }

        .listing-info h4 {
            font-size: 1rem;
            margin-bottom: 5px;
            font-weight: 600;
        }

        .listing-info p {
            font-size: 0.85rem;
            color: var(--text-grey);
        }

        .listing-price {
            color: var(--accent-gold);
            font-weight: 700;
            font-size: 0.9rem;
            margin-top: 5px;
            display: block;
        }

        /* Neighborhood Widget */
        .neighborhood-list li {
