            margin-bottom: 5px;
        }

        .agent-role {
            font-size: 0.8rem;
            text-transform: uppercase;
            color: var(--accent-gold);
            letter-spacing: 1px;
            margin-bottom: 15px;
            display: block;
        }

        .agent-bio {
            font-size: 0.9rem;
            color: var(--text-grey);
            margin-bottom: 20px;
        }

        .btn-small {
            padding: 8px 20px;
