            background: transparent;
            color: var(--primary-dark);
            cursor: pointer;
            transition: all 0.3s;
        }

        .btn-small:hover {
            background: var(--primary-dark);
            color: #fff;
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary-dark);
            color: #fff;
            padding: 60px 20px;
            text-align: center;
        }

        .footer-logo {
            font-family: var(--font-serif);
