            margin-bottom: 30px;
        }

        .footer-links a {
            margin: 0 15px;
            font-size: 0.9rem;
            color: #aaa;
        }

        .footer-links a:hover {
            color: #fff;
        }

        .copyright {
            font-size: 0.8rem;
            color: #666;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 900px) {
            .container {
                flex-direction: column;
            }

            .sidebar {
                width: 100%;
            }

            .featured-property {
                grid-template-columns: 1fr;
            }

            .hero-tagline {
                font-size: 2.5rem;
            }
        }

        @media (max-width: 600px) {
            header {
                flex-direction: column;
                gap: 15px;
                padding: 15px;
            }

            .hero-tagline {
                font-size: 2rem;
            }
        }
    </style>
