            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: #bdc3c7;
            transition: var(--transition);
        }

        .footer-col ul li a:hover {
            color: var(--primary-color);
            padding-left: 5px;
        }

        .footer-bottom {
