        .slide {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            opacity: 0;
            transition: opacity 0.8s ease-in-out;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .slide.active { opacity: 1; }

        .slide img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.7; /* Darken image slightly for text readability */
        }

        .slide-content {
            position: absolute;
            bottom: 10%;
            left: 5%;
            color: var(--white);
            max-width: 600px;
            z-index: 2;
        }

        .slide-content h2 {
            font-size: 3rem;
            margin-bottom: 0.5rem;
            text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        }

        .slide-content p {
            font-size: 1.2rem;
            margin-bottom: 1.5rem;
            text-shadow: 0 1px 2px rgba(0,0,0,0.5);
        }

        .btn-primary {
            display: inline-block;
            background-color: var(--accent);
            color: var(--white);
            padding: 0.8rem 2rem;
            border-radius: 4px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            border: none;
            cursor: pointer;
        }

        .btn-primary:hover {
            background-color: #dc2626;
            transform: translateY(-2px);
        }

        .carousel-nav {
            position: absolute;
            bottom: 20px;
            right: 20px;
            display: flex;
            gap: 10px;
            z-index: 10;
        }

        .carousel-btn {
            background: rgba(255,255,255,0.2);
            border: 1px solid rgba(255,255,255,0.5);
            color: white;
            width: 40px;
            height: 40px;
            border-radius: 50%;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: 0.3s;
        }

        .carousel-btn:hover { background: var(--accent); border-color: var(--accent); }

        /* --- MAIN CONTENT AREA --- */
        .main-content h1 {
            font-size: 2rem;
            margin-bottom: 1.5rem;
            border-left: 5px solid var(--accent);
            padding-left: 1rem;
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 1.5rem;
            margin-bottom: 3rem;
        }

        .feature-card {
            background: var(--white);
            padding: 1.5rem;
            border-radius: 8px;
            box-shadow: var(--shadow);
            border: 1px solid var(--border);
        }

        .feature-card h3 { margin-bottom: 0.5rem; color: var(--primary); }
        .feature-card p { font-size: 0.9rem; color: var(--secondary); }

        /* --- RIGHT SIDEBAR --- */
        aside {
            display: flex;
            flex-direction: column;
            gap: 2rem;
        }

        .sidebar-widget {
            background: var(--white);
            border-radius: 8px;
            padding: 1.5rem;
            box-shadow: var(--shadow);
            border: 1px solid var(--border);
        }

        .widget-title {
            font-size: 1.1rem;
            font-weight: 700;
            margin-bottom: 1rem;
            padding-bottom: 0.5rem;
            border-bottom: 2px solid var(--light);
            color: var(--primary);
        }

        /* Inventory List */
        .inventory-item {
            display: flex;
            gap: 1rem;
            margin-bottom: 1rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid var(--border);
        }

        .inventory-item:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }

        .inv-img {
            width: 70px;
            height: 50px;
            background-color: #ddd;
            border-radius: 4px;
            object-fit: cover;
        }

        .inv-details h4 { font-size: 0.95rem; margin-bottom: 0.2rem; }
        .inv-details .price { color: var(--accent); font-weight: 700; font-size: 0.9rem; }

        /* Financing Calculator */
        .finance-form {
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
        }

        .form-group label {
            display: block;
            font-size: 0.85rem;
            margin-bottom: 0.3rem;
            color: var(--secondary);
        }

        .form-group input, .form-group select {
            width: 100%;
            padding: 0.6rem;
            border: 1px solid var(--border);
            border-radius: 4px;
            font-family: inherit;
        }

        .finance-result {
            background-color: var(--light);
            padding: 1rem;
            border-radius: 4px;
            text-align: center;
            margin-top: 0.5rem;
        }

        .finance-result span {
            display: block;
            font-size: 1.5rem;
            font-weight: 800;
            color: var(--primary);
        }

        .finance-result small { font-size: 0.8rem; color: var(--secondary); }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary);
            color: var(--white);
            padding: 3rem 2rem;
            margin-top: 3rem;
        }

        .footer-content {
            max-width: 1400px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 2rem;
        }

        .footer-col h4 { margin-bottom: 1rem; color: var(--accent); }
        .footer-col ul li { margin-bottom: 0.5rem; font-size: 0.9rem; color: #94a3b8; }
        .footer-col ul li:hover { color: var(--white); cursor: pointer; }

        .copyright {
            text-align: center;
            margin-top: 3rem;
            padding-top: 1rem;
            border-top: 1px solid #334155;
            font-size: 0.85rem;
            color: #64748b;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 900px) {
            .container { grid-template-columns: 1fr; }
            .hero-section { grid-column: 1; }
            .carousel { height: 350px; }
            .slide-content h2 { font-size: 2rem; }
            nav { display: none; } /* Simplified for mobile demo */
        }
    </style>
</head>
