<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Wanderlust Travel Agency</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --primary: #ff6b6b;
            --secondary: #4ecdc4;
            --dark: #2d3436;
            --light: #f7f9fc;
            --white: #ffffff;
            --shadow: 0 10px 30px rgba(0,0,0,0.1);
            --font-main: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: var(--font-main);
            color: var(--dark);
            background-color: var(--light);
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: 0.3s;
        }

        ul {
            list-style: none;
        }

        /* --- HEADER & NAV --- */
        header {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 1000;
            padding: 20px 50px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            font-size: 28px;
            font-weight: 800;
            color: var(--white);
            text-transform: uppercase;
            letter-spacing: 2px;
        }

        .logo span {
            color: var(--secondary);
        }

        nav ul {
            display: flex;
            gap: 30px;
        }

        nav a {
            color: var(--white);
            font-weight: 600;
            font-size: 16px;
            position: relative;
        }

        nav a::after {
            content: '';
            position: absolute;
            width: 0;
            height: 2px;
            bottom: -5px;
            left: 0;
            background-color: var(--secondary);
            transition: width 0.3s;
        }

        nav a:hover::after {
            width: 100%;
        }

        .btn-nav {
            padding: 10px 25px;
            background-color: var(--primary);
            color: var(--white);
            border-radius: 50px;
            font-weight: bold;
        }

        .btn-nav:hover {
            background-color: #ff4757;
            transform: translateY(-2px);
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            background: linear-gradient(rgba(0,0,0,0.3), rgba(0,0,0,0.5)), url('https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?ixlib=rb-4.0.3&auto=format&fit=crop&w=2070&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: var(--white);
            padding: 0 20px;
        }

        .hero h1 {
            font-size: 4rem;
            margin-bottom: 20px;
            text-shadow: 2px 2px 10px rgba(0,0,0,0.5);
            animation: fadeInDown 1s ease;
        }

        .hero p {
            font-size: 1.5rem;
            margin-bottom: 40px;
            max-width: 700px;
            animation: fadeInUp 1s ease 0.3s forwards;
            opacity: 0;
        }

        .cta-button {
            padding: 15px 40px;
            background-color: var(--secondary);
            color: var(--white);
            font-size: 1.2rem;
            border-radius: 50px;
            font-weight: bold;
            box-shadow: 0 5px 15px rgba(78, 205, 196, 0.4);
            animation: fadeInUp 1s ease 0.6s forwards;
            opacity: 0;
        }

        .cta-button:hover {
            background-color: #3dbdb4;
            transform: scale(1.05);
        }

        /* --- DESTINATIONS GRID --- */
        .destinations {
            padding: 80px 50px;
            background-color: var(--white);
        }

        .section-title {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-title h2 {
            font-size: 2.5rem;
            color: var(--dark);
            margin-bottom: 10px;
        }

        .section-title span {
            display: block;
            width: 80px;
            height: 4px;
            background: var(--primary);
            margin: 0 auto;
        }

        .grid-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .dest-card {
            position: relative;
            height: 400px;
            border-radius: 20px;
            overflow: hidden;
            cursor: pointer;
            box-shadow: var(--shadow);
        }

        .dest-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s;
        }

        .dest-card:hover img {
            transform: scale(1.1);
        }

        .dest-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 30px;
            background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
            color: var(--white);
        }

        .dest-info h3 {
            font-size: 1.8rem;
            margin-bottom: 5px;
        }

        .dest-info p {
            font-size: 1rem;
            opacity: 0.9;
        }

        /* --- PACKAGES SECTION --- */
        .packages {
            padding: 80px 50px;
            background-color: var(--light);
        }

        .package-card {
            background: var(--white);
            border-radius: 20px;
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: transform 0.3s;
            display: flex;
            flex-direction: column;
        }

        .package-card:hover {
            transform: translateY(-10px);
        }

        .pkg-img {
            height: 200px;
            width: 100%;
            object-fit: cover;
        }

        .pkg-content {
            padding: 25px;
            flex-grow: 1;
            display: flex;
            flex-direction: column;
        }

        .pkg-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 15px;
        }

        .pkg-price {
            color: var(--primary);
            font-weight: 800;
            font-size: 1.2rem;
        }

        .pkg-details {
            color: #636e72;
            margin-bottom: 20px;
            font-size: 0.95rem;
        }

        .pkg-btn {
            margin-top: auto;
            display: block;
            text-align: center;
            padding: 12px;
            background-color: var(--dark);
            color: var(--white);
            border-radius: 10px;
            font-weight: 600;
        }

        .pkg-btn:hover {
            background-color: var(--primary);
        }

        /* --- REVIEWS SECTION --- */
        .reviews {
            padding: 80px 50px;
            background-color: var(--white);
            text-align: center;
        }

        .review-container {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 40px;
            margin-top: 40px;
        }

        .review-card {
            background: var(--light);
            padding: 40px;
            border-radius: 20px;
            max-width: 350px;
            position: relative;
        }

        .review-card::before {
            content: '"';
            font-size: 80px;
            color: var(--secondary);
            position: absolute;
            top: 10px;
            left: 20px;
            opacity: 0.3;
            font-family: serif;
        }

        .review-text {
            font-style: italic;
            color: #555;
            margin-bottom: 20px;
            position: relative;
            z-index: 1;
        }

        .reviewer {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 15px;
        }

        .reviewer img {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            object-fit: cover;
        }

        .reviewer-info h4 {
            font-size: 1rem;
            color: var(--dark);
        }

        .reviewer-info span {
            font-size: 0.85rem;
            color: var(--primary);
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--dark);
            color: var(--white);
            padding: 60px 50px 20px;
        }

        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h3 {
            font-size: 1.5rem;
            margin-bottom: 20px;
            color: var(--secondary);
        }

        .footer-col p {
            color: #b2bec3;
            margin-bottom: 10px;
        }

        .social-links {
            display: flex;
            gap: 15px;
            margin-top: 20px;
        }

        .social-icon {
            width: 40px;
            height: 40px;
            background: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            transition: 0.3s;
        }

        .social-icon:hover {
            background: var(--primary);
        }

        .footer-bottom {
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 20px;
            text-align: center;
            color: #636e72;
            font-size: 0.9rem;
        }

        /* --- ANIMATIONS --- */
        @keyframes fadeInDown {
            from { opacity: 0; transform: translateY(-30px); }
            to { opacity: 1; transform: translateY(0); }
        }

        @keyframes fadeInUp {
            from { opacity: 0; transform: translateY(30px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            header {
                padding: 20px;
                flex-direction: column;
                gap: 15px;
            }

            nav ul {
                gap: 15px;
                font-size: 14px;
            }

            .hero h1 {
                font-size: 2.5rem;
            }

            .hero p {
                font-size: 1.1rem;
            }

            .destinations, .packages, .reviews {
                padding: 60px 20px;
            }
        }
    </style>
</head>
