            box-shadow: 0 10px 30px rgba(0,0,0,0.2);
            flex-wrap: wrap;
        }

        .search-field {
            flex: 1;
            min-width: 150px;
        }

        .search-field label {
            display: block;
            font-size: 0.8rem;
            color: var(--text-gray);
            margin-bottom: 5px;
            font-weight: 600;
        }

        .search-field select, .search-field input {
            width: 100%;
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-family: inherit;
        }

        .search-btn {
