        }

        .features span {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        /* --- SERVICES --- */
        .services-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
            text-align: center;
        }

        .service-card {
            padding: 40px 20px;
            border: 1px solid #eee;
            border-radius: 10px;
            transition: var(--transition);
        }

        .service-card:hover {
            border-color: var(--secondary);
            box-shadow: var(--shadow);
