<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Daily Chronicle | Global News & Media</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --primary-color: #1a252f;
            --accent-color: #c0392b;
            --text-dark: #333;
            --text-light: #7f8c8d;
            --bg-light: #f4f6f7;
            --white: #ffffff;
            --border-color: #e0e0e0;
            --sidebar-width: 300px;
            --header-height: 60px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-light);
            color: var(--text-dark);
            line-height: 1.6;
        }

        a { text-decoration: none; color: inherit; transition: 0.3s; }
        ul { list-style: none; }
        img { max-width: 100%; display: block; }

        /* --- HEADER --- */
        header {
            background-color: var(--primary-color);
            color: var(--white);
            height: var(--header-height);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 20px;
            position: sticky;
            top: 0;
            z-index: 1000;
            box-shadow: 0 2px 5px rgba(0,0,0,0.2);
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            letter-spacing: 1px;
        }
        .logo span { color: var(--accent-color); }

        .header-search {
            display: flex;
            align-items: center;
        }

        .header-search input {
            padding: 8px 12px;
            border-radius: 4px;
            border: none;
            outline: none;
        }

        /* --- LAYOUT GRID --- */
        .container {
            display: grid;
            grid-template-columns: 220px 1fr 300px; /* Left Menu | Main | Sidebar */
            gap: 20px;
            max-width: 1400px;
            margin: 0 auto;
            padding: 20px;
            min-height: calc(100vh - var(--header-height) - 200px);
        }

        /* --- LEFT VERTICAL MENU --- */
        .left-menu {
            background: var(--white);
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.05);
            height: fit-content;
        }

        .left-menu h3 {
            font-size: 0.9rem;
            text-transform: uppercase;
            color: var(--text-light);
            margin-bottom: 15px;
            border-bottom: 2px solid var(--accent-color);
            padding-bottom: 5px;
            display: inline-block;
        }

        .left-menu ul li {
            margin-bottom: 10px;
        }

        .left-menu ul li a {
            display: block;
            padding: 10px;
            border-radius: 4px;
            font-weight: 500;
        }

        .left-menu ul li a:hover, .left-menu ul li a.active {
            background-color: var(--primary-color);
            color: var(--white);
        }

        /* --- MAIN CONTENT AREA --- */
        .main-content {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        /* Full Width Banner */
        .hero-banner {
            position: relative;
            height: 400px;
            border-radius: 8px;
            overflow: hidden;
            background-color: #000;
        }

        .hero-banner img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.7;
        }

        .hero-content {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 40px;
            background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
            color: var(--white);
        }

        .hero-tag {
            background-color: var(--accent-color);
            padding: 5px 10px;
            font-size: 0.8rem;
            font-weight: bold;
            text-transform: uppercase;
            border-radius: 3px;
            margin-bottom: 10px;
            display: inline-block;
        }

        .hero-content h1 {
            font-size: 2.5rem;
            margin-bottom: 10px;
            line-height: 1.2;
        }

        /* Article Cards Grid */
        .articles-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 20px;
        }

        .card {
            background: var(--white);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 2px 5px rgba(0,0,0,0.05);
            transition: transform 0.2s;
            display: flex;
            flex-direction: column;
        }

        .card:hover {
            transform: translateY(-5px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.1);
        }

        .card-img {
            height: 180px;
            background-color: #ddd;
            overflow: hidden;
        }

        .card-img img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .card-body {
            padding: 20px;
            flex-grow: 1;
            display: flex;
            flex-direction: column;
        }

        .card-category {
            color: var(--accent-color);
            font-size: 0.8rem;
            font-weight: 700;
            text-transform: uppercase;
            margin-bottom: 8px;
        }

        .card-title {
            font-size: 1.2rem;
            margin-bottom: 10px;
            font-weight: 700;
        }

        .card-excerpt {
            font-size: 0.9rem;
            color: var(--text-light);
            margin-bottom: 15px;
            flex-grow: 1;
        }

        .card-meta {
            font-size: 0.8rem;
            color: #999;
            border-top: 1px solid #eee;
            padding-top: 10px;
            display: flex;
            justify-content: space-between;
        }

        /* --- STICKY SIDEBAR --- */
        .sidebar {
            position: relative;
        }

        .sticky-wrapper {
            position: sticky;
            top: 80px; /* Offset for header */
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .widget {
            background: var(--white);
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.05);
        }

        .widget-title {
            font-size: 1.1rem;
            margin-bottom: 15px;
            padding-bottom: 10px;
            border-bottom: 1px solid var(--border-color);
        }

        /* Social Feed Simulation */
        .social-feed-item {
            display: flex;
            gap: 10px;
            margin-bottom: 15px;
            font-size: 0.9rem;
        }
        .social-icon {
            width: 30px;
            height: 30px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: bold;
            flex-shrink: 0;
        }
        .fb { background: #3b5998; }
        .tw { background: #1da1f2; }
        .ig { background: #c13584; }

        /* Live Chat Simulation */
        .chat-box {
            height: 300px;
            display: flex;
            flex-direction: column;
        }

        .chat-messages {
            flex-grow: 1;
            overflow-y: auto;
            margin-bottom: 10px;
            border: 1px solid #eee;
            padding: 10px;
            border-radius: 4px;
            background: #fafafa;
        }

        .message {
            margin-bottom: 8px;
            padding: 5px 8px;
            border-radius: 4px;
            font-size: 0.85rem;
        }
        .msg-in { background: #e1f5fe; align-self: flex-start; }
        .msg-out { background: #e8f5e9; text-align: right; }

        .chat-input-area {
            display: flex;
            gap: 5px;
        }

        .chat-input-area input {
            flex-grow: 1;
            padding: 8px;
            border: 1px solid #ddd;
            border-radius: 4px;
        }

        .chat-input-area button {
            padding: 8px 12px;
            background: var(--primary-color);
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 40px 20px;
            margin-top: 40px;
        }

        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
            align-items: center;
            gap: 30px;
        }

        .footer-logo h2 {
            font-size: 1.8rem;
            margin-bottom: 10px;
        }
        .footer-logo p {
            color: #bdc3c7;
            font-size: 0.9rem;
        }

        .newsletter-form {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
        }

        .newsletter-form input {
            padding: 12px;
            border-radius: 4px;
            border: none;
            width: 250px;
        }

        .newsletter-form button {
            padding: 12px 24px;
            background-color: var(--accent-color);
            color: white;
            border: none;
            border-radius: 4px;
            font-weight: bold;
            cursor: pointer;
            transition: background 0.3s;
        }

        .newsletter-form button:hover {
            background-color: #a93226;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 1024px) {
            .container {
                grid-template-columns: 1fr 300px;
            }
            .left-menu {
                display: none; /* Hide left menu on tablet */
            }
        }

        @media (max-width: 768px) {
            .container {
                grid-template-columns: 1fr;
            }
            .sidebar {
                order: 2; /* Move sidebar below content on mobile */
            }
            .hero-banner {
                height: 250px;
            }
            .hero-content h1 {
                font-size: 1.5rem;
            }
            .footer-content {
                flex-direction: column;
                text-align: center;
            }
            .newsletter-form {
                flex-direction: column;
                width: 100%;
            }
            .newsletter-form input {
                width: 100%;
            }
        }
    </style>
</head>
