            width: 40px;
            height: 40px;
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.2rem;
        }

        .icon-blue { background-color: var(--light-blue); color: var(--primary-blue); }
        .icon-green { background-color: var(--light-green); color: var(--primary-green); }

        .stat-value {
