            color: var(--text-dark);
            margin-bottom: 2px;
        }

        .appt-details p {
            font-size: 0.8rem;
            color: var(--text-light);
        }

        /* Utility */
        .btn {
            display: inline-block;
            padding: 10px 20px;
            background-color: var(--primary-blue);
