            margin-bottom: 10px;
            color: var(--dark-bg);
        }

        .card-body p {
            color: #666;
            font-size: 0.95rem;
            margin-bottom: 15px;
        }

        .card-link {
            color: var(--primary-color);
            font-weight: bold;
            text-transform: uppercase;
            font-size: 0.9rem;
        }

        /* --- TRAVEL TIPS SECTION --- */
        .tips-section {
            background-color: var(--dark-bg);
            color: var(--white);
            padding: 60px 20px;
            margin-top: 40px;
        }

        .tips-container {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 40px;
        }

        .tip-item h3 {
            color: var(--secondary-color);
            margin-bottom: 15px;
        }

        /* --- TESTIMONIALS --- */
        .testimonials {
            padding: 60px 20px;
            background-color: var(--white);
            text-align: center;
        }

        .testimonial-grid {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 30px;
            max-width: 1200px;
            margin: 0 auto;
        }

        .testimonial-card {
            background: var(--light-bg);
            padding: 30px;
            border-radius: 10px;
            max-width: 350px;
            position: relative;
        }

        .testimonial-card::before {
            content: "“";
            font-size: 5rem;
            color: #ddd;
            position: absolute;
            top: -10px;
            left: 20px;
            font-family: serif;
        }

        .client-name {
            margin-top: 15px;
            font-weight: bold;
            color: var(--primary-color);
        }

        /* --- FOOTER --- */
        footer {
            background-color: #1a1a1a;
            color: #ccc;
            padding: 60px 20px 20px;
        }

        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
