        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            display: flex;
            align-items: center;
            padding: 0 5%;
            position: relative;
            overflow: hidden;
        }

        .hero-content {
            width: 50%;
            z-index: 2;
        }

        .hero h1 {
            font-size: 5rem;
            line-height: 1.1;
            margin-bottom: 1.5rem;
        }

        .hero p {
            font-size: 1.2rem;
            color: var(--text-light);
            margin-bottom: 2rem;
            max-width: 400px;
        }

        .btn {
            display: inline-block;
            padding: 1rem 2.5rem;
            background-color: var(--text-main);
            color: #fff;
            border-radius: 50px;
            font-size: 0.9rem;
            letter-spacing: 1px;
        }

        .btn:hover {
            background-color: var(--accent-lavender);
            color: var(--text-main);
            transform: translateY(-3px);
        }

        /* Abstract Hero Shapes */
        .hero-visual {
            position: absolute;
            right: -5%;
            top: 10%;
            width: 50%;
            height: 80%;
            z-index: 1;
        }

        .blob {
            position: absolute;
            border-radius: 50%;
            filter: blur(40px);
            opacity: 0.8;
            animation: float 10s infinite ease-in-out;
        }

        .blob-1 {
            width: 400px;
            height: 400px;
            background: var(--accent-pink);
            top: 0;
            right: 20%;
        }

        .blob-2 {
            width: 300px;
            height: 300px;
            background: var(--accent-mint);
            bottom: 10%;
            right: 0;
            animation-delay: 2s;
        }

        .blob-3 {
            width: 200px;
            height: 200px;
            background: var(--accent-peach);
            top: 40%;
            right: 40%;
            animation-delay: 4s;
        }

        @keyframes float {
            0% { transform: translate(0, 0); }
            50% { transform: translate(20px, -20px); }
            100% { transform: translate(0, 0); }
        }

        /* --- SERVICES (Asymmetrical Grid) --- */
        .services {
            padding: 8rem 5%;
        }

        .services-grid {
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            gap: 2rem;
            margin-top: 3rem;
        }

        .service-card {
            background: #fff;
            padding: 3rem;
            border-radius: 20px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.03);
            transition: 0.3s;
        }

        .service-card:hover {
            transform: translateY(-10px);
            box-shadow: 0 20px 40px rgba(0,0,0,0.06);
        }

        .s-1 { grid-column: span 5; background-color: var(--accent-lavender); }
        .s-2 { grid-column: span 4; grid-row: span 2; background-color: var(--accent-peach); }
        .s-3 { grid-column: span 3; background-color: #fff; }
        .s-4 { grid-column: span 6; background-color: var(--accent-mint); }
        .s-5 { grid-column: span 3; background-color: #fff; }

        .service-card h3 {
            font-size: 1.5rem;
            margin-bottom: 1rem;
        }

        /* --- TEAM (ZigZag Layout) --- */
        .team {
            padding: 8rem 5%;
            background-color: #F4F1EA;
            position: relative;
        }

        /* The ZigZag Line */
        .zigzag-line {
            position: absolute;
            top: 0;
            left: 50%;
            width: 2px;
            height: 100%;
            background: repeating-linear-gradient(
                to bottom,
                var(--text-main),
                var(--text-main) 10px,
                transparent 10px,
                transparent 20px
            );
            transform: translateX(-50%);
            z-index: 0;
        }

        .team-member {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 6rem;
            position: relative;
            z-index: 1;
        }

        .team-member:nth-child(even) {
            flex-direction: row-reverse;
        }

        .member-img {
            width: 40%;
            height: 400px;
            background-color: #ddd;
            border-radius: 150px 150px 0 0; /* Arch shape */
            overflow: hidden;
            position: relative;
        }

        .member-img img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: grayscale(100%);
            transition: 0.5s;
        }

        .team-member:hover .member-img img {
            filter: grayscale(0%);
        }

        /* Colored blobs behind images */
        .member-img::after {
            content: '';
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            background: linear-gradient(to bottom, transparent, rgba(0,0,0,0.1));
        }

        .member-info {
            width: 40%;
            padding: 2rem;
        }

        .member-info h3 {
            font-size: 2.5rem;
            margin-bottom: 0.5rem;
        }

        .member-info span {
            display: block;
            font-size: 1rem;
            color: var(--text-light);
            margin-bottom: 1.5rem;
            font-style: italic;
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--text-main);
            color: #fff;
            padding: 5rem 5% 2rem;
            position: relative;
        }

        /* Wavy top border for footer */
        footer::before {
            content: "";
            display: block;
            height: 50px;
            background: var(--text-main);
            position: absolute;
            top: -50px;
            left: 0;
            width: 100%;
            clip-path: polygon(0 100%, 100% 100%, 100% 0, 95% 50%, 90% 100%, 85% 50%, 80% 100%, 75% 50%, 70% 100%, 65% 50%, 60% 100%, 55% 50%, 50% 100%, 45% 50%, 40% 100%, 35% 50%, 30% 100%, 25% 50%, 20% 100%, 15% 50%, 10% 100%, 5% 50%, 0 100%);
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 4rem;
            margin-bottom: 4rem;
        }

        .footer-col h4 {
            font-family: var(--font-heading);
            font-size: 1.5rem;
            margin-bottom: 1.5rem;
            color: var(--accent-pink);
        }

        .testimonial {
            font-style: italic;
            opacity: 0.8;
            margin-bottom: 1rem;
            border-left: 2px solid var(--accent-mint);
            padding-left: 1rem;
        }

        .client-name {
            display: block;
            margin-top: 0.5rem;
            font-size: 0.8rem;
            font-weight: bold;
            color: var(--accent-lavender);
        }

        /* Contact Form */
        .contact-form input, .contact-form textarea {
            width: 100%;
            padding: 1rem;
            margin-bottom: 1rem;
            background: rgba(255,255,255,0.1);
            border: none;
            color: #fff;
            font-family: var(--font-body);
        }

        .contact-form input:focus, .contact-form textarea:focus {
            outline: 1px solid var(--accent-mint);
            background: rgba(255,255,255,0.2);
        }

        .social-links {
            display: flex;
            gap: 1rem;
            margin-top: 1rem;
        }

        .social-circle {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: 0.3s;
        }

        .social-circle:hover {
            background: var(--accent-pink);
            color: var(--text-main);
        }

        .copyright {
            text-align: center;
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 2rem;
            font-size: 0.8rem;
            opacity: 0.5;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 900px) {
            .hero { flex-direction: column; justify-content: center; text-align: center; height: auto; padding-top: 100px; }
            .hero-content { width: 100%; }
            .hero-visual { display: none; }
            .hero h1 { font-size: 3rem; }

            .services-grid { grid-template-columns: 1fr; }
            .s-1, .s-2, .s-3, .s-4, .s-5 { grid-column: span 1; grid-row: auto; }

            .team-member { flex-direction: column !important; text-align: center; }
            .member-img { width: 80%; height: 300px; margin-bottom: 2rem; }
            .member-info { width: 100%; }
            .zigzag-line { display: none; }

            .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
        }
    </style>
</head>
