        .hero {
            position: relative;
            height: 100vh;
            width: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
            overflow: hidden;
        }

        .hero-video {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.6;
            z-index: 1;
        }

        .hero-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle, transparent 20%, var(--c-bg) 120%);
            z-index: 2;
        }

        .hero-content {
            position: relative;
            z-index: 3;
            text-align: center;
            mix-blend-mode: exclusion;
        }

        .hero-logo {
            font-size: 15vw;
            color: white;
            letter-spacing: -10px;
            animation: pulse 4s infinite ease-in-out;
        }

        .hero-sub {
            font-family: var(--font-body);
            font-size: 1.5rem;
            margin-top: 20px;
            letter-spacing: 5px;
            color: var(--c-accent-2);
        }

        /* --- IRREGULAR SECTIONS --- */
        .irregular-section {
            position: relative;
            padding: 100px 5vw;
            margin: 50px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 10;
        }

        /* The Magic Shape */
        .shape-container {
            position: relative;
            width: 100%;
            max-width: 1200px;
            height: 600px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .blob {
            position: absolute;
            width: 100%;
            height: 100%;
            background-color: var(--c-accent-1);
            z-index: 1;
            transition: all 0.5s ease;
        }

        /* Using clip-path to create irregular shapes */
        .blob-1 {
            clip-path: polygon(20% 0%, 80% 0%, 100% 20%, 100% 80%, 80% 100%, 20% 100%, 0% 80%, 0% 20%);
            background: var(--c-accent-1);
        }

        .blob-2 {
            clip-path: polygon(10% 10%, 90% 5%, 95% 90%, 5% 95%);
            background: var(--c-accent-2);
            transform: rotate(15deg) scale(0.9);
            z-index: 2;
        }

        .blob-3 {
            clip-path: polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%);
            background: var(--c-accent-3);
            transform: rotate(-10deg) scale(0.8);
            z-index: 3;
        }

        /* Content inside the shape */
        .content-card {
            position: relative;
            z-index: 4;
            background: rgba(0,0,0,0.8);
            backdrop-filter: blur(10px);
            padding: 40px;
            border: 2px solid white;
            max-width: 500px;
            color: white;
            box-shadow: 10px 10px 0px rgba(255,255,255,0.2);
        }

        /* --- GRID SECTION --- */
        .grid-section {
            padding: 100px 5vw;
            background: var(--c-accent-4);
            clip-path: polygon(0 10%, 100% 0, 100% 90%, 0 100%);
            margin: 100px 0;
        }

        .gallery {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
            margin-top: 50px;
        }

        .gallery-item {
            height: 300px;
            background-color: #000;
            position: relative;
            overflow: hidden;
            transition: transform 0.3s;
        }

        .gallery-item:hover {
            transform: scale(0.98);
        }

        .gallery-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.7;
            transition: opacity 0.3s;
        }

        .gallery-item:hover img {
            opacity: 1;
        }

        .gallery-caption {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 20px;
            background: linear-gradient(to top, black, transparent);
            font-weight: bold;
            text-transform: uppercase;
        }

        /* --- FOOTER --- */
        footer {
            padding: 100px 5vw;
            background: var(--c-bg);
            text-align: center;
            border-top: 1px solid #333;
        }

        .cta-btn {
            display: inline-block;
            margin-top: 30px;
            padding: 20px 50px;
            background: var(--c-accent-3);
            color: black;
            font-weight: bold;
            text-decoration: none;
            text-transform: uppercase;
            font-size: 1.5rem;
            border: none;
            cursor: pointer;
            transition: transform 0.2s;
        }

        .cta-btn:hover {
            transform: translate(-5px, -5px);
            box-shadow: 5px 5px 0 var(--c-accent-1);
        }

        /* --- ANIMATIONS --- */
        @keyframes pulse {
            0% { transform: scale(1); }
            50% { transform: scale(1.05); }
            100% { transform: scale(1); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            h1 { font-size: 18vw; }
            .hero-logo { font-size: 25vw; }
            .shape-container { height: 400px; }
            .grid-section { clip-path: none; }
        }
    </style>
</head>
