        .filter-title {
            font-size: 1.1rem;
            font-weight: 700;
            margin-bottom: 15px;
            border-bottom: 2px solid var(--bg-light);
            padding-bottom: 10px;
        }

        .category-list li {
            margin-bottom: 10px;
        }

        .category-list a {
            color: var(--text-light);
            display: flex;
            justify-content: space-between;
        }

        .category-list a:hover {
            color: var(--primary-color);
        }

        .price-range {
            width: 100%;
            margin-top: 10px;
        }

        /* --- Product Grid --- */
        .products-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .products-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
            gap: 20px;
        }

        .product-card {
            background: var(--white);
            border-radius: var(--radius);
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: transform 0.2s, box-shadow 0.2s;
            position: relative;
        }

        .product-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
        }

        .product-image {
            height: 200px;
            background-color: #e2e8f0;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #94a3b8;
            position: relative;
        }

        .badge {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: var(--secondary-color);
            color: white;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.75rem;
            font-weight: bold;
        }

        .product-info {
            padding: 15px;
        }

        .product-category {
            font-size: 0.8rem;
            color: var(--text-light);
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .product-title {
            font-size: 1rem;
            font-weight: 600;
            margin: 5px 0;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .product-rating {
            color: #fbbf24;
            font-size: 0.9rem;
            margin-bottom: 10px;
        }

        .product-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 10px;
        }

        .price {
            font-size: 1.1rem;
            font-weight: 700;
            color: var(--text-dark);
        }

        .add-btn {
            background-color: var(--bg-light);
            color: var(--text-dark);
            border: none;
            width: 32px;
            height: 32px;
            border-radius: 50%;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s;
        }

        .add-btn:hover {
            background-color: var(--primary-color);
            color: white;
        }

        /* --- Deals Section --- */
        .deals-section {
            background-color: var(--white);
            padding: 40px 0;
            margin-bottom: 60px;
        }

        .section-title {
            font-size: 1.8rem;
            margin-bottom: 30px;
            text-align: center;
        }

        .deals-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
        }

        .deal-card {
            background: var(--bg-light);
            border-radius: var(--radius);
            padding: 20px;
            display: flex;
            align-items: center;
            gap: 20px;
            border: 1px solid var(--border-color);
        }

        .deal-img {
            width: 100px;
            height: 100px;
            background-color: #cbd5e1;
            border-radius: var(--radius);
            flex-shrink: 0;
        }

        .deal-info h3 {
            margin-bottom: 5px;
        }

        .deal-price {
            color: var(--secondary-color);
            font-weight: 700;
            font-size: 1.2rem;
        }

        .old-price {
            text-decoration: line-through;
            color: var(--text-light);
            font-size: 0.9rem;
            margin-left: 10px;
        }

        /* --- Footer --- */
        footer {
            background-color: #111827;
            color: #d1d5db;
            padding: 60px 0 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h4 {
            color: var(--white);
            margin-bottom: 20px;
            font-size: 1.1rem;
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a:hover {
            color: var(--primary-color);
        }

        .policy-text {
            font-size: 0.9rem;
            line-height: 1.8;
        }

        .footer-bottom {
            border-top: 1px solid #374151;
            padding-top: 20px;
            text-align: center;
            font-size: 0.9rem;
        }

        /* --- Responsive --- */
        @media (max-width: 768px) {
            .header-top {
                flex-direction: column;
                gap: 15px;
            }

            .search-container {
                width: 100%;
                margin: 0;
            }

            .hero-content {
                flex-direction: column;
                text-align: center;
            }

            .hero-text {
                max-width: 100%;
                margin-bottom: 30px;
            }

            .hero-image {
                width: 100%;
            }

            .main-layout {
                grid-template-columns: 1fr;
            }

            .sidebar {
                display: none; /* Hidden on mobile for simplicity */
            }
        }
    </style>
