                linear-gradient(-45deg, var(--text-main) 25%, transparent 25%), 
                linear-gradient(45deg, transparent 75%, var(--text-main) 75%), 
                linear-gradient(-45deg, transparent 75%, var(--text-main) 75%);
            background-size: calc(var(--pixel-size) * 4) calc(var(--pixel-size) * 4);
            background-position: 0 0, 0 calc(var(--pixel-size) * 2), calc(var(--pixel-size) * 2) calc(var(--pixel-size) * 2), calc(var(--pixel-size) * 2) 0;
