            color: var(--accent-primary);
        }

        /* Dropdown Submenus */
        .submenu {
            position: absolute;
            top: 100%;
            left: 0;
            background: var(--bg-card);
            min-width: 200px;
            border: 1px solid rgba(255, 255, 255, 0.1);
