    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --primary: #ff6b35; /* Appetizing Orange */
            --secondary: #2ec4b6; /* Fresh Teal */
            --dark: #1a1a1a;
            --light: #f7f7f7;
            --overlay: rgba(0, 0, 0, 0.6);
            --font-heading: 'Georgia', serif;
            --font-body: 'Helvetica Neue', sans-serif;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-body);
            background-color: var(--dark);
            color: var(--light);
            overflow-x: hidden;
        }

        /* --- PROMOTION BANNER --- */
        .promo-banner {
            background-color: var(--primary);
            color: white;
            text-align: center;
            padding: 10px;
            font-weight: bold;
            font-size: 0.9rem;
            letter-spacing: 1px;
            position: relative;
            z-index: 1001;
        }

        .promo-banner span {
            text-transform: uppercase;
            animation: pulse 2s infinite;
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            width: 100%;
            background-image: url('https://images.unsplash.com/photo-1504674900247-0877df9cc836?q=80&w=2070&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            background-attachment: fixed; /* Parallax effect */
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            position: relative;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to bottom, rgba(0,0,0,0.3), rgba(0,0,0,0.8));
        }

        .hero-content {
            position: relative;
            z-index: 2;
            text-align: center;
            animation: fadeIn 1.5s ease-out;
        }

        .logo {
            font-family: var(--font-heading);
            font-size: 5rem;
            color: var(--primary);
            text-shadow: 2px 2px 10px rgba(0,0,0,0.5);
            margin-bottom: 10px;
            letter-spacing: -2px;
        }

        .tagline {
            font-size: 1.5rem;
            font-weight: 300;
            letter-spacing: 3px;
            text-transform: uppercase;
            margin-bottom: 40px;
        }

        .scroll-indicator {
            position: absolute;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            z-index: 2;
            animation: bounce 2s infinite;
            cursor: pointer;
        }

        .scroll-indicator svg {
            width: 40px;
            height: 40px;
            fill: var(--light);
        }

        /* --- CIRCULAR MENU SECTION --- */
        .menu-section {
            min-height: 100vh;
            background: radial-gradient(circle at center, #2a2a2a 0%, #1a1a1a 100%);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 50px 20px;
            position: relative;
            overflow: hidden;
        }

        .section-title {
            font-family: var(--font-heading);
            font-size: 3rem;
            color: var(--light);
            margin-bottom: 60px;
            text-align: center;
        }

        .section-title span {
            color: var(--primary);
        }

        /* The Circular Container */
        .menu-orbit {
            position: relative;
            width: 600px;
            height: 600px;
            border: 1px dashed rgba(255, 255, 255, 0.1);
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            transition: transform 0.5s ease;
        }

        /* Center Hub */
        .orbit-center {
            position: absolute;
            width: 150px;
            height: 150px;
            background: var(--primary);
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 10;
            box-shadow: 0 0 30px rgba(255, 107, 53, 0.4);
            cursor: pointer;
            transition: transform 0.3s;
        }

        .orbit-center:hover {
            transform: scale(1.1);
        }

        .orbit-center h3 {
            font-family: var(--font-heading);
            font-size: 1.5rem;
            color: white;
            text-align: center;
        }

        /* Menu Items */
        .menu-item {
            position: absolute;
            width: 140px;
            height: 140px;
            background: white;
            border-radius: 50%;
            overflow: hidden;
            box-shadow: 0 10px 20px rgba(0,0,0,0.5);
            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            cursor: pointer;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
        }

        .menu-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.4s;
        }

        .menu-item:hover {
            transform: scale(1.2) !important; /* Override inline positioning on hover */
            z-index: 20;
            box-shadow: 0 0 25px var(--primary);
        }

        .menu-item:hover img {
            transform: scale(1.1);
        }

        .item-info {
            position: absolute;
            bottom: 0;
            width: 100%;
            background: rgba(0,0,0,0.7);
            color: white;
            padding: 5px 0;
            font-size: 0.8rem;
            font-weight: bold;
            opacity: 0;
            transition: opacity 0.3s;
        }

        .menu-item:hover .item-info {
            opacity: 1;
        }

        /* --- DISCOVERY / SCROLL JOURNEY --- */
        .discovery-section {
            padding: 100px 20px;
            background-color: var(--light);
            color: var(--dark);
        }

        .dish-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 40px;
            max-width: 1200px;
            margin: 0 auto;
        }

        .dish-card {
            background: white;
            border-radius: 15px;
            overflow: hidden;
            box-shadow: 0 5px 15px rgba(0,0,0,0.1);
            transition: transform 0.3s;
        }

        .dish-card:hover {
            transform: translateY(-10px);
        }

        .dish-img {
            height: 250px;
            width: 100%;
            object-fit: cover;
        }

        .dish-details {
            padding: 25px;
        }

        .dish-details h3 {
            font-family: var(--font-heading);
            font-size: 1.5rem;
            margin-bottom: 10px;
            color: var(--dark);
        }

        .dish-details p {
            color: #666;
            line-height: 1.6;
            margin-bottom: 20px;
        }

        .btn-order {
            display: inline-block;
            padding: 10px 25px;
            background-color: var(--primary);
            color: white;
            text-decoration: none;
            border-radius: 25px;
            font-weight: bold;
            transition: background 0.3s;
        }

        .btn-order:hover {
            background-color: #e55a2b;
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--dark);
            color: #888;
            text-align: center;
            padding: 40px 20px;
            border-top: 1px solid #333;
        }

        footer p {
            margin-bottom: 10px;
        }

        /* --- ANIMATIONS --- */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        @keyframes pulse {
            0% { opacity: 1; }
            50% { opacity: 0.7; }
            100% { opacity: 1; }
        }

        @keyframes bounce {
            0%, 20%, 50%, 80%, 100% { transform: translateY(0) translateX(-50%); }
            40% { transform: translateY(-10px) translateX(-50%); }
            60% { transform: translateY(-5px) translateX(-50%); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .logo { font-size: 3rem; }
            .menu-orbit {
                width: 320px;
                height: 320px;
            }
            .orbit-center {
                width: 100px;
                height: 100px;
            }
            .orbit-center h3 { font-size: 1rem; }
            .menu-item {
                width: 90px;
                height: 90px;
            }
            .item-info { display: none; } /* Hide text on small screens to avoid clutter */
        }
    </style>
</head>
