<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ARCHON | Architecture Firm</title>
    <style>
        /* --- Reset & Base Styles --- */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --bg-color: #f4f4f4;
            --text-color: #1a1a1a;
            --accent-color: #333333;
            --white: #ffffff;
            --font-main: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            --font-serif: 'Georgia', serif;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--bg-color);
            color: var(--text-color);
            line-height: 1.6;
            overflow-x: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: opacity 0.3s ease;
        }

        a:hover {
            opacity: 0.6;
        }

        ul {
            list-style: none;
        }

        /* --- Navigation --- */
        nav {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            padding: 2rem 4rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            z-index: 1000;
            background: rgba(244, 244, 244, 0.95);
            backdrop-filter: blur(5px);
        }

        .nav-links {
            display: flex;
            gap: 3rem;
        }

        .nav-links li a {
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 2px;
            font-weight: 500;
        }

        /* --- Hero Section & Logo Mask --- */
        .hero {
            height: 100vh;
            width: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
            position: relative;
            overflow: hidden;
        }

        /* The Background Image */
        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            /* Placeholder architectural image */
            background-image: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?q=80&w=2070&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            z-index: 1;
        }

        /* The Mask Container */
        .logo-mask {
            position: relative;
            z-index: 2;
            width: 400px;
            height: 400px;
            display: flex;
            justify-content: center;
            align-items: center;
            /* This creates the mask effect */
            background-color: var(--bg-color);
            /* Using clip-path to create a geometric architectural shape (Hexagon) */
            clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
            transition: transform 0.5s ease;
        }

        .logo-mask:hover {
            transform: scale(1.02);
        }

        /* The Icon inside the mask */
        .logo-icon {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            /* The icon image */
            background-image: url('https://images.unsplash.com/photo-1503387762-592deb58ef4e?q=80&w=1931&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            /* This ensures the icon is clipped by the parent's clip-path */
            clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
        }

        /* --- Portfolio Section --- */
        .section-header {
            padding: 6rem 4rem 2rem;
            text-align: left;
        }

        .section-title {
            font-family: var(--font-serif);
            font-size: 3rem;
            font-weight: 400;
            margin-bottom: 1rem;
        }

        .section-subtitle {
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: #666;
        }

        .portfolio-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 2rem;
            padding: 0 4rem 6rem;
        }

        .project-card {
            position: relative;
            height: 450px;
            overflow: hidden;
            cursor: pointer;
        }

        .project-img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.6s ease;
            filter: grayscale(20%);
        }

        .project-card:hover .project-img {
            transform: scale(1.05);
            filter: grayscale(0%);
        }

        .project-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 2rem;
            background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
            color: var(--white);
            opacity: 0;
            transform: translateY(20px);
            transition: all 0.4s ease;
        }

        .project-card:hover .project-info {
            opacity: 1;
            transform: translateY(0);
        }

        .project-title {
            font-family: var(--font-serif);
            font-size: 1.5rem;
            margin-bottom: 0.5rem;
        }

        .project-cat {
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        /* --- Testimonials Section --- */
        .testimonials {
            background-color: var(--white);
            padding: 6rem 4rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
        }

        .testimonial-slider {
            max-width: 800px;
            margin-top: 3rem;
        }

        .quote {
            font-family: var(--font-serif);
            font-size: 1.8rem;
            line-height: 1.4;
            margin-bottom: 2rem;
            color: #333;
        }

        .client-name {
            font-size: 0.9rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .client-role {
            font-size: 0.8rem;
            color: #888;
            margin-top: 0.5rem;
        }

        /* --- Footer --- */
        footer {
            background-color: #111;
            color: #fff;
            padding: 4rem;
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
        }

        .footer-logo {
            font-family: var(--font-serif);
            font-size: 1.5rem;
            letter-spacing: 2px;
        }

        .footer-links {
            display: flex;
            gap: 2rem;
        }

        .footer-links a {
            font-size: 0.8rem;
            color: #888;
        }

        .footer-links a:hover {
            color: #fff;
            opacity: 1;
        }

        /* --- Responsive --- */
        @media (max-width: 768px) {
            nav {
                padding: 1.5rem 2rem;
            }
            .nav-links {
                display: none; /* Simple hide for mobile for this demo */
            }
            .logo-mask {
                width: 250px;
                height: 250px;
            }
            .section-header, .portfolio-grid, .testimonials, footer {
                padding-left: 2rem;
                padding-right: 2rem;
            }
            .section-title {
                font-size: 2rem;
            }
            .quote {
                font-size: 1.4rem;
            }
        }
    </style>
</head>
<body>

