<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Roots & Reach | Non-Profit Organization</title>
    <style>
        /* --- CSS Reset & Variables --- */
        :root {
            --color-primary: #5D4037; /* Dark Earth Brown */
            --color-secondary: #8D6E63; /* Medium Brown */
            --color-accent: #D84315; /* Burnt Orange */
            --color-sage: #8F9E7B; /* Muted Sage Green */
            --color-cream: #F5F5DC; /* Beige/Cream */
            --color-white: #FFFFFF;
            --color-text: #3E2723;
            --color-light-text: #795548;
            --font-heading: 'Georgia', serif;
            --font-body: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            --spacing-unit: 1rem;
            --max-width: 1200px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-body);
            color: var(--color-text);
            background-color: var(--color-cream);
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: color 0.3s ease;
        }

        ul {
            list-style: none;
        }

        img {
            max-width: 100%;
            display: block;
        }

        /* --- Utility Classes --- */
        .container {
            max-width: var(--max-width);
            margin: 0 auto;
            padding: 0 var(--spacing-unit);
        }

        .btn {
            display: inline-block;
            padding: 12px 24px;
            border-radius: 4px;
            font-weight: bold;
            text-transform: uppercase;
            letter-spacing: 1px;
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }

        .btn-primary {
            background-color: var(--color-accent);
            color: var(--color-white);
        }

        .btn-primary:hover {
            background-color: #BF360C;
            transform: translateY(-2px);
            box-shadow: 0 4px 8px rgba(0,0,0,0.2);
        }

        .section-title {
            font-family: var(--font-heading);
