            margin-bottom: 1rem;
            font-size: 0.9rem;
        }

        /* --- Content Area --- */
        .content-area {
            /* Grid column 2 is implicit */
        }

        .mission-section {
            margin-bottom: 3rem;
        }

        .mission-text {
            font-size: 1.1rem;
            color: var(--color-light-text);
            margin-bottom: 2rem;
        }

        /* --- Large Donate Section --- */
        .donate-section {
            background-color: var(--color-primary);
            color: var(--color-white);
            padding: 3rem;
            border-radius: 12px;
            text-align: center;
            margin-bottom: 3rem;
            position: relative;
            overflow: hidden;
        }

        .donate-section::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 70%);
            transform: rotate(30deg);
        }

        .donate-section h2 {
            font-family: var(--font-heading);
            font-size: 2.5rem;
            margin-bottom: 1rem;
            position: relative;
        }

        .donate-section p {
            margin-bottom: 2rem;
            font-size: 1.2rem;
            opacity: 0.9;
            position: relative;
        }

        .donate-btn-large {
            background-color: var(--color-accent);
            color: var(--color-white);
            font-size: 1.5rem;
            padding: 20px 50px;
            border-radius: 50px;
            border: none;
            cursor: pointer;
            box-shadow: 0 6px 15px rgba(0,0,0,0.3);
            transition: transform 0.2s, box-shadow 0.2s;
            position: relative;
            animation: pulse 2s infinite;
        }

        .donate-btn-large:hover {
            transform: scale(1.05);
            box-shadow: 0 8px 20px rgba(0,0,0,0.4);
            background-color: #BF360C;
        }

        @keyframes pulse {
            0% { box-shadow: 0 0 0 0 rgba(216, 67, 21, 0.7); }
            70% { box-shadow: 0 0 0 15px rgba(216, 67, 21, 0); }
            100% { box-shadow: 0 0 0 0 rgba(216, 67, 21, 0); }
        }

        /* --- Testimonials Section --- */
        .testimonials-section {
            margin-bottom: 3rem;
        }

        .testimonials-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .testimonial-card {
            background-color: var(--color-white);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
            border-top: 4px solid var(--color-sage);
        }

        .testimonial-photo {
            width: 80px;
            height: 80px;
            border-radius: 50%;
            object-fit: cover;
            margin-bottom: 1rem;
            border: 3px solid var(--color-cream);
        }

        .testimonial-quote {
            font-style: italic;
            color: var(--color-light-text);
            margin-bottom: 1rem;
            font-size: 1.05rem;
        }

        .testimonial-author {
            font-weight: bold;
            color: var(--color-primary);
        }

        .testimonial-role {
            font-size: 0.85rem;
            color: var(--color-sage);
        }

        /* --- Footer --- */
        footer {
            background-color: var(--color-primary);
            color: var(--color-cream);
            padding: 3rem 0;
            margin-top: auto;
        }

        .footer-content {
            display: flex;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 2rem;
        }

        .footer-col h4 {
            font-family: var(--font-heading);
            margin-bottom: 1rem;
            color: var(--color-white);
        }

        .footer-col ul li {
            margin-bottom: 0.5rem;
        }

        .footer-col a {
            color: var(--color-sage);
        }

        .footer-col a:hover {
            color: var(--color-white);
        }

        .copyright {
            text-align: center;
            margin-top: 2rem;
            padding-top: 1rem;
            border-top: 1px solid rgba(255,255,255,0.1);
            font-size: 0.9rem;
            color: var(--color-sage);
        }

        /* --- Responsive Design --- */
        @media (max-width: 768px) {
            .main-layout {
                grid-template-columns: 1fr;
            }

            .sidebar {
                order: 2; /* Move sidebar below content on mobile */
            }

            .hero-content h1 {
                font-size: 2.5rem;
            }

            .nav-container {
                flex-direction: column;
                height: auto;
                padding: 1rem 0;
            }

            nav ul {
                margin-top: 1rem;
