        .social-icon:hover {
            background: var(--accent-color);
            border-color: var(--accent-color);
            color: #fff;
        }

        .copyright {
            text-align: center;
            padding-top: 2rem;
            border-top: 1px solid #222;
            color: #555;
            font-size: 0.8rem;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .hero-content h1 {
                font-size: 3rem;
            }

            nav {
                padding: 1rem;
            }

            .nav-links {
                display: none; /* Simple hiding for single file demo */
            }

            .nav-links.mobile-active {
                display: flex;
                flex-direction: column;
                position: absolute;
                top: 70px;
                right: 0;
                background: #000;
                width: 100%;
                padding: 2rem;
                text-align: center;
            }

            .mobile-toggle {
                display: block;
                font-size: 1.5rem;
                cursor: pointer;
            }
        }

        @media (min-width: 769px) {
            .mobile-toggle {
                display: none;
            }
        }
    </style>
</head>
