        const line1 = document.getElementById('line1');
        const line2 = document.getElementById('line2');
        const line3 = document.getElementById('line3');
        let isMenuOpen = false;

        menuBtn.addEventListener('click', () => {
            isMenuOpen = !isMenuOpen;

            if (isMenuOpen) {
                // Show Menu
                navOverlay.classList.remove('nav-hidden');
                navOverlay.classList.add('nav-visible');

                // Animate Hamburger to X
                line1.classList.add('rotate-45', 'translate-y-2');
                line2.classList.add('opacity-0');
                line3.classList.add('-rotate-45', '-translate-y-1.5', 'w-6');
            } else {
                // Hide Menu
                navOverlay.classList.remove('nav-visible');
                navOverlay.classList.add('nav-hidden');

                // Reset Hamburger
                line1.classList.remove('rotate-45', 'translate-y-2');
                line2.classList.remove('opacity-0');
                line3.classList.remove('-rotate-45', '-translate-y-1.5', 'w-6');
            }
        });
    </script>
