<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>FunZone Entertainment</title>
    <style>
        /* Reset & Base Styles */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f4f4f9;
            color: #333;
            overflow-x: hidden;
        }

        /* Header Container */
        header {
            position: relative;
            width: 100%;
            height: 600px;
            /* Multi-colored gradient background */
            background: linear-gradient(135deg, #FF00CC, #3333FF, #00CCFF, #FFCC00);
            background-size: 400% 400%;
            animation: gradientShift 15s ease infinite;
            display: flex;
            flex-direction: column;
            justify-content: flex-end; /* Pushes logo to bottom */
            align-items: center;
            padding-bottom: 40px;
            overflow: hidden;
        }

        @keyframes gradientShift {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }

        /* Semi-transparent Navigation Overlay */
        nav {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            padding: 20px 50px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            background-color: rgba(255, 255, 255, 0.15); /* Semi-transparent */
            backdrop-filter: blur(5px);
            border-bottom: 1px solid rgba(255, 255, 255, 0.2);
            z-index: 100;
        }

        .nav-logo-text {
            font-size: 1.5rem;
            font-weight: 800;
            color: white;
            text-transform: uppercase;
            letter-spacing: 2px;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.2);
        }

        .nav-links {
            list-style: none;
            display: flex;
            gap: 30px;
        }

        .nav-links a {
            text-decoration: none;
            color: white;
            font-weight: 600;
            font-size: 1.1rem;
            transition: color 0.3s ease, transform 0.2s;
        }

        .nav-links a:hover {
            color: #FFCC00;
            transform: translateY(-2px);
        }

        /* Mascot Character Design (CSS Art) */
        .mascot-container {
            position: absolute;
            bottom: 120px; /* Positioned above the logo */
            right: 10%;
            width: 300px;
            height: 300px;
            z-index: 10;
            animation: float 4s ease-in-out infinite;
        }

        @keyframes float {
            0% { transform: translateY(0px); }
            50% { transform: translateY(-20px); }
            100% { transform: translateY(0px); }
        }

        /* The Character Body */
        .mascot-body {
            width: 200px;
            height: 200px;
            background-color: #FFCC00;
            border-radius: 50%;
            position: absolute;
            bottom: 0;
            left: 50px;
            box-shadow: inset -10px -10px 20px rgba(0,0,0,0.1), 10px 10px 30px rgba(0,0,0,0.2);
            border: 5px solid #fff;
        }

        /* The Character Eyes */
        .mascot-eyes {
            position: absolute;
            top: 60px;
            left: 50px;
            width: 100px;
            display: flex;
            justify-content: space-between;
        }

        .eye {
            width: 40px;
            height: 50px;
            background-color: white;
            border-radius: 50%;
            position: relative;
            overflow: hidden;
        }

        .pupil {
            width: 15px;
            height: 15px;
            background-color: #333;
            border-radius: 50%;
            position: absolute;
            top: 15px;
            left: 12px;
            animation: lookAround 5s infinite;
        }

        @keyframes lookAround {
            0%, 100% { transform: translate(0, 0); }
            25% { transform: translate(5px, 0); }
            50% { transform: translate(-5px, 5px); }
            75% { transform: translate(0, -5px); }
        }

        /* The Character Mouth */
        .mascot-mouth {
            position: absolute;
            bottom: 40px;
            left: 75px;
            width: 50px;
            height: 25px;
            background-color: #FF5555;
            border-radius: 0 0 25px 25px;
            border: 3px solid #333;
            border-top: none;
        }

        /* Mascot Accessories (Headphones) */
        .headphones {
            position: absolute;
            top: 40px;
            left: 30px;
            width: 240px;
            height: 120px;
            border: 15px solid #333;
            border-bottom: none;
            border-radius: 100px 100px 0 0;
            z-index: 11;
        }

        .ear-cup {
            position: absolute;
            top: 80px;
            width: 40px;
            height: 60px;
            background-color: #333;
            border-radius: 10px;
        }

        .ear-cup.left { left: 20px; }
        .ear-cup.right { right: 20px; }

        /* Bottom Logo Area */
        .brand-logo {
            position: relative;
            z-index: 20;
            background-color: white;
            padding: 15px 40px;
            border-radius: 50px;
            box-shadow: 0 10px 25px rgba(0,0,0,0.2);
            text-align: center;
            transform: translateY(20px); /* Slight overlap with mascot */
        }

        .brand-logo h1 {
            font-size: 2.5rem;
            font-weight: 900;
            background: -webkit-linear-gradient(#FF00CC, #3333FF);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            text-transform: uppercase;
            letter-spacing: 3px;
        }

        .brand-logo span {
            display: block;
            font-size: 0.8rem;
            color: #666;
            letter-spacing: 1px;
            margin-top: -5px;
        }

        /* Main Content Area */
        main {
            max-width: 1200px;
            margin: 0 auto;
            padding: 60px 20px;
        }

        .hero-text {
            text-align: center;
            margin-bottom: 60px;
        }

        .hero-text h2 {
            font-size: 2.5rem;
            color: #333;
            margin-bottom: 15px;
        }

        .hero-text p {
            font-size: 1.2rem;
            color: #666;
            max-width: 600px;
            margin: 0 auto;
        }

        /* Grid Layout for Content */
        .content-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .card {
            background: white;
            border-radius: 20px;
            padding: 30px;
            box-shadow: 0 10px 20px rgba(0,0,0,0.05);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
            border-top: 5px solid transparent;
        }

        .card:hover {
            transform: translateY(-10px);
            box-shadow: 0 15px 30px rgba(0,0,0,0.1);
        }

        .card:nth-child(1) { border-color: #FF00CC; }
        .card:nth-child(2) { border-color: #3333FF; }
        .card:nth-child(3) { border-color: #00CCFF; }

        .card h3 {
            font-size: 1.5rem;
            margin-bottom: 15px;
            color: #333;
        }

        .card p {
            color: #666;
            line-height: 1.6;
        }

        .btn {
            display: inline-block;
            margin-top: 20px;
            padding: 10px 25px;
            background-color: #333;
            color: white;
            text-decoration: none;
            border-radius: 25px;
            font-weight: bold;
            transition: background 0.3s;
        }

        .btn:hover {
            background-color: #555;
        }

        /* Decorative Background Elements */
        .blob {
            position: absolute;
            border-radius: 50%;
            filter: blur(40px);
            z-index: 1;
            opacity: 0.6;
        }
        .blob-1 { top: 10%; left: 10%; width: 200px; height: 200px; background: #FF00CC; }
        .blob-2 { bottom: 20%; left: 30%; width: 150px; height: 150px; background: #00CCFF; }

    </style>
</head>
