            background: var(--bg-body);
            border: 1px solid var(--border);
            border-radius: 20px;
            padding: 0.5rem 1rem;
            width: 300px;
            outline: none;
            transition: border-color 0.2s;
        }

        .search-bar:focus {
            border-color: var(--primary);
        }

        .user-menu {
            display: flex;
            align-items: center;
            gap: 1rem;
        }

        .avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            object-fit: cover;
            border: 2px solid var(--border);
            cursor: pointer;
        }

        .btn-icon {
            background: none;
            border: none;
            cursor: pointer;
            color: var(--text-muted);
            font-size: 1.2rem;
            padding: 0.5rem;
            border-radius: 50%;
            transition: background 0.2s;
        }

        .btn-icon:hover {
            background: var(--bg-body);
            color: var(--primary);
        }

        /* --- Sidebar Left --- */
        .sidebar-nav {
            position: sticky;
            top: 100px;
        }

        .nav-item {
            display: flex;
            align-items: center;
            gap: 1rem;
            padding: 0.75rem 1rem;
            color: var(--text-main);
            text-decoration: none;
            border-radius: var(--radius);
            font-weight: 500;
            transition: background 0.2s;
            margin-bottom: 0.25rem;
        }

        .nav-item:hover, .nav-item.active {
            background: #e0e7ff;
            color: var(--primary);
        }

        .nav-item svg {
            width: 24px;
            height: 24px;
        }

        /* --- Main Feed --- */
        .create-post {
            background: var(--bg-card);
            border-radius: var(--radius);
            padding: 1.5rem;
            box-shadow: var(--shadow);
            margin-bottom: 1.5rem;
        }

        .create-post-top {
            display: flex;
            gap: 1rem;
            margin-bottom: 1rem;
        }

        .create-input {
            flex: 1;
            border: none;
            background: var(--bg-body);
            border-radius: 20px;
            padding: 0.75rem 1rem;
            font-size: 1rem;
            outline: none;
            resize: none;
            height: 50px;
            transition: height 0.2s;
        }

        .create-input:focus {
            height: 100px;
        }

        .create-actions {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-top: 1px solid var(--border);
            padding-top: 1rem;
        }

        .action-group {
            display: flex;
            gap: 0.5rem;
        }

        .action-btn {
            background: none;
            border: none;
            color: var(--text-muted);
            cursor: pointer;
            padding: 0.5rem;
            border-radius: 8px;
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-size: 0.9rem;
            font-weight: 500;
        }

        .action-btn:hover {
            background: var(--bg-body);
            color: var(--primary);
        }

        .btn-primary {
            background: var(--primary);
            color: white;
            border: none;
            padding: 0.5rem 1.5rem;
            border-radius: 20px;
            font-weight: 600;
            cursor: pointer;
            transition: background 0.2s;
        }

        .btn-primary:hover {
            background: var(--primary-hover);
        }

        /* --- Post Card --- */
        .post-card {
            background: var(--bg-card);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            margin-bottom: 1.5rem;
            animation: fadeIn 0.3s ease-out;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .post-header {
            padding: 1rem 1.5rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .post-author {
            display: flex;
            gap: 0.75rem;
            align-items: center;
        }

        .author-info h4 {
            font-size: 0.95rem;
            margin-bottom: 0.1rem;
        }

        .author-info span {
            font-size: 0.8rem;
            color: var(--text-muted);
        }

        .post-content {
            padding: 0 1.5rem 1rem;
            font-size: 0.95rem;
        }

        .post-image {
            width: 100%;
            height: auto;
            display: block;
            border-top: 1px solid var(--border);
            border-bottom: 1px solid var(--border);
        }

        .post-stats {
            padding: 0.75rem 1.5rem;
            display: flex;
            justify-content: space-between;
            color: var(--text-muted);
            font-size: 0.85rem;
            border-bottom: 1px solid var(--border);
        }

        .post-actions {
            padding: 0.5rem 1.5rem;
            display: flex;
            justify-content: space-around;
        }

        .post-action-btn {
            flex: 1;
            background: none;
            border: none;
            padding: 0.5rem;
            border-radius: 8px;
            cursor: pointer;
            color: var(--text-muted);
            font-weight: 500;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
            transition: all 0.2s;
        }

        .post-action-btn:hover {
            background: var(--bg-body);
        }

        .post-action-btn.liked {
            color: var(--danger);
        }

        /* --- Sidebar Right --- */
        .widget {
            background: var(--bg-card);
