    <style>
        /* Reset & Base Styles */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            background-color: #0a0a0a;
            color: #ffffff;
            overflow: hidden; /* Prevents scrollbars for the landing page feel */
            height: 100vh;
            width: 100vw;
        }

        /* Typography Utilities */
        h1, h2, h3 {
            font-weight: 300;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        p {
            font-weight: 300;
            line-height: 1.6;
            color: #cccccc;
        }

        /* Main Container */
        .hero-container {
            position: relative;
            height: 100%;
            width: 100%;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
        }

        /* Background Image */
        .bg-image {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            /* High quality architectural image from Unsplash */
            background-image: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?q=80&w=2070&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            z-index: 1;
            filter: grayscale(100%) contrast(110%) brightness(60%);
            transition: filter 0.5s ease;
        }

        /* Subtle overlay for text readability */
        .overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to bottom, rgba(0,0,0,0.3) 0%, rgba(0,0,0,0.1) 50%, rgba(0,0,0,0.8) 100%);
            z-index: 2;
        }

        /* Centered Logo Section */
        .logo-section {
            position: relative;
            z-index: 3;
            text-align: center;
            margin-bottom: auto; /* Pushes content up slightly to balance visual weight */
            padding-top: 10vh;
            animation: fadeIn 1.5s ease-out;
        }

        .logo-symbol {
            width: 60px;
            height: 60px;
            border: 2px solid #fff;
            margin: 0 auto 20px auto;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
        }

        /* Geometric accent inside logo */
        .logo-symbol::after {
            content: '';
            width: 20px;
            height: 20px;
            background-color: #fff;
        }

        .brand-name {
            font-size: 3rem;
            letter-spacing: 0.3em;
            margin-bottom: 10px;
            color: #fff;
        }

        .brand-tagline {
            font-size: 0.8rem;
            letter-spacing: 0.2em;
            color: #aaa;
            text-transform: uppercase;
        }

        /* Bottom Navigation Bar */
        .bottom-nav {
            position: relative;
            z-index: 3;
            width: 100%;
            background: rgba(10, 10, 10, 0.85);
            backdrop-filter: blur(10px);
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            padding: 20px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: auto; /* Pushes to bottom */
        }

        .nav-links {
            display: flex;
            gap: 40px;
            list-style: none;
        }

        .nav-links li a {
            text-decoration: none;
            color: #888;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.15em;
            transition: color 0.3s ease;
            position: relative;
        }

        .nav-links li a:hover {
            color: #fff;
        }

        /* Underline animation on hover */
        .nav-links li a::after {
            content: '';
            position: absolute;
            width: 0;
            height: 1px;
            bottom: -5px;
            left: 0;
            background-color: #fff;
            transition: width 0.3s ease;
        }

        .nav-links li a:hover::after {
            width: 100%;
        }

        .nav-contact {
            font-size: 0.75rem;
            color: #666;
            letter-spacing: 0.1em;
        }

        /* Animations */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Responsive Adjustments */
        @media (max-width: 768px) {
            .brand-name {
                font-size: 2rem;
            }

            .bottom-nav {
                flex-direction: column;
                gap: 20px;
                padding: 20px;
            }

            .nav-links {
                gap: 20px;
                flex-wrap: wrap;
                justify-content: center;
            }

            .nav-contact {
                display: none; /* Hide contact info on very small screens to save space */
            }
        }
    </style>
</head>
