                    <li class="nav-item active" onclick="setTheme('dark')">Dark Mode</li>
                    <li class="nav-item" onclick="setTheme('light')">Light Mode</li>
                    <li class="nav-item" onclick="setTheme('blue')">Cyber Blue</li>
                    <li class="nav-item" onclick="setTheme('purple')">Neon Purple</li>
                    <li class="nav-item" onclick="setTheme('green')">Eco Green</li>
                </ul>
            </div>
            <div class="interaction-hint">
                Click nav items to change background
            </div>
        </nav>

        <!-- Main Content -->
        <main class="main-content">

            <!-- Large Centered Header Image Area -->
            <div class="hero-image-container">
                <!-- CSS Generated Device Image -->
                <div class="device-mockup">
                    <div class="device-screen">NEXUS OS v2.0</div>
                </div>

                <!-- Floating UI Elements -->
                <div class="floating-ui ui-1">Processing...</div>
                <div class="floating-ui ui-2">Sync Complete</div>
            </div>

            <!-- Text Content -->
            <div class="text-content">
                <h1>The Future is Minimal.</h1>
                <p>Experience the next generation of electronic design. Seamless integration, powerful performance, and a design that adapts to your environment.</p>

                <!-- Interactive Controls -->
                <div class="color-controls">
                    <button class="btn" onclick="setTheme('dark')">Default</button>
                    <button class="btn" onclick="setTheme('blue')">Blue</button>
                    <button class="btn" onclick="setTheme('purple')">Purple</button>
                </div>
            </div>

        </main>
    </div>

    <script>
        // Theme Configuration
        const themes = {
            dark: {
                bg: '#1a1a1a',
                text: '#ffffff',
                border: 'rgba(255, 255, 255, 0.1)',
                btnBorder: 'rgba(255, 255, 255, 0.3)'
            },
            light: {
                bg: '#f4f4f4',
                text: '#1a1a1a',
                border: 'rgba(0, 0, 0, 0.1)',
                btnBorder: 'rgba(0, 0, 0, 0.3)'
            },
            blue: {
                bg: '#0f172a',
                text: '#e2e8f0',
                border: 'rgba(56, 189, 248, 0.2)',
                btnBorder: 'rgba(56, 189, 248, 0.5)'
            },
            purple: {
                bg: '#2e1065',
                text: '#f3e8ff',
                border: 'rgba(192, 132, 252, 0.2)',
                btnBorder: 'rgba(192, 132, 252, 0.5)'
            },
            green: {
                bg: '#052e16',
                text: '#dcfce7',
                border: 'rgba(74, 222, 128, 0.2)',
                btnBorder: 'rgba(74, 222, 128, 0.5)'
            }
        };

        function setTheme(themeName) {
            const theme = themes[themeName];
            const body = document.body;
            const sidebar = document.querySelector('.sidebar');
            const navItems = document.querySelectorAll('.nav-item');
            const buttons = document.querySelectorAll('.btn');

            // Update Background
            body.style.backgroundColor = theme.bg;

            // Update Text Color
            body.style.color = theme.text;

            // Update Sidebar Glass Effect
            sidebar.style.backgroundColor = themeName === 'light' ? 'rgba(255, 255, 255, 0.6)' : 'rgba(0, 0, 0, 0.2)';
            sidebar.style.borderRight = `1px solid ${theme.border}`;

            // Update Buttons
            buttons.forEach(btn => {
                btn.style.borderColor = theme.btnBorder;
                btn.style.color = theme.text;
            });

            // Update Active State in Sidebar
            navItems.forEach(item => {
                item.classList.remove('active');
                // Simple check to match text content to theme name
                if(item.innerText.toLowerCase().includes(themeName)) {
                    item.classList.add('active');
                }
            });
        }

        // Initialize default theme
        setTheme('dark');
    </script>
</body>
</html>
