        .trend-1 { background: linear-gradient(to top, #000, transparent), url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100"><rect fill="%23333" width="100" height="100"/><circle cx="50" cy="50" r="40" fill="%23444"/></svg>'); }
        .trend-2 { background: linear-gradient(to top, #000, transparent), url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100"><rect fill="%23222" width="100" height="100"/><rect x="20" y="20" width="60" height="60" fill="%23555"/></svg>'); }
        .trend-3 { background: linear-gradient(to top, #000, transparent), url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100"><rect fill="%23111" width="100" height="100"/><line x1="0" y1="0" x2="100" y2="100" stroke="%23666" stroke-width="5"/></svg>'); }
        .trend-4 { background: linear-gradient(to top, #000, transparent), url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100"><rect fill="%23333" width="100" height="100"/><polygon points="50,10 90,90 10,90" fill="%23444"/></svg>'); }

        .trend-overlay {
