<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>NEXUS | Gaming Studio</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --bg-dark: #050505;
            --bg-panel: #121212;
            --primary: #00f3ff; /* Cyan */
            --secondary: #bc13fe; /* Neon Purple */
            --accent: #ff0055; /* Neon Red */
            --text-main: #ffffff;
            --text-muted: #888888;
            --font-display: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            --font-body: 'Courier New', Courier, monospace;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-dark);
            color: var(--text-main);
            font-family: var(--font-display);
            overflow-x: hidden;
            min-height: 100vh;
        }

        /* --- BACKGROUND ANIMATION --- */
        .bg-grid {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-image: 
                linear-gradient(rgba(0, 243, 255, 0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 243, 255, 0.03) 1px, transparent 1px);
            background-size: 50px 50px;
            z-index: -1;
            perspective: 1000px;
            transform-style: preserve-3d;
            animation: gridMove 20s linear infinite;
        }

        @keyframes gridMove {
            0% { transform: translateY(0); }
            100% { transform: translateY(50px); }
        }

        /* --- NAVIGATION --- */
        nav {
            position: fixed;
            top: 0;
            width: 100%;
            height: 80px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 40px;
            background: rgba(5, 5, 5, 0.8);
            backdrop-filter: blur(10px);
            z-index: 1000;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .logo {
            font-size: 2rem;
            font-weight: 900;
            letter-spacing: 2px;
            color: var(--text-main);
            text-transform: uppercase;
            cursor: pointer;
            position: relative;
            text-shadow: 0 0 10px var(--primary);
        }

        .logo span {
            color: var(--primary);
        }

        /* Hamburger Menu */
        .menu-toggle {
            width: 40px;
            height: 30px;
            cursor: pointer;
            position: relative;
            z-index: 1002;
        }

        .menu-toggle span {
            display: block;
            width: 100%;
            height: 3px;
            background: var(--text-main);
            position: absolute;
            transition: 0.4s cubic-bezier(0.68, -0.55, 0.27, 1.55);
            box-shadow: 0 0 5px var(--primary);
        }

        .menu-toggle span:nth-child(1) { top: 0; }
        .menu-toggle span:nth-child(2) { top: 13px; }
        .menu-toggle span:nth-child(3) { top: 26px; }

        /* Active State for Hamburger */
        .menu-toggle.active span:nth-child(1) {
            transform: rotate(45deg);
            top: 13px;
            background: var(--accent);
        }
        .menu-toggle.active span:nth-child(2) {
            opacity: 0;
            transform: translateX(-20px);
        }
        .menu-toggle.active span:nth-child(3) {
            transform: rotate(-45deg);
            top: 13px;
            background: var(--accent);
        }

        /* Expandable Menu Overlay */
        .nav-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100vh;
            background: rgba(0, 0, 0, 0.95);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            transform: translateY(-100%);
            transition: transform 0.5s cubic-bezier(0.77, 0, 0.175, 1);
            z-index: 1001;
        }

        .nav-overlay.open {
            transform: translateY(0);
        }

        .nav-links {
            list-style: none;
            text-align: center;
        }

        .nav-links li {
            margin: 20px 0;
            opacity: 0;
            transform: translateY(20px);
            transition: 0.5s ease;
        }

        .nav-overlay.open .nav-links li {
            opacity: 1;
            transform: translateY(0);
        }

        /* Staggered animation for links */
        .nav-overlay.open li:nth-child(1) { transition-delay: 0.1s; }
        .nav-overlay.open li:nth-child(2) { transition-delay: 0.2s; }
        .nav-overlay.open li:nth-child(3) { transition-delay: 0.3s; }
        .nav-overlay.open li:nth-child(4) { transition-delay: 0.4s; }

        .nav-links a {
            font-size: 3rem;
            color: var(--text-main);
            text-decoration: none;
            font-weight: bold;
            text-transform: uppercase;
            position: relative;
            transition: 0.3s;
        }

        .nav-links a:hover {
            color: var(--primary);
            text-shadow: 0 0 20px var(--primary);
        }

        .nav-links a::after {
            content: '';
            position: absolute;
            bottom: -5px;
            left: 0;
            width: 0%;
            height: 3px;
            background: var(--secondary);
            transition: 0.3s;
        }

        .nav-links a:hover::after {
            width: 100%;
        }

        /* --- HERO SECTION --- */
        header {
            height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero-content {
            z-index: 2;
            padding: 20px;
        }

        h1 {
            font-size: 5rem;
            line-height: 1;
            margin-bottom: 20px;
            text-transform: uppercase;
            background: linear-gradient(90deg, var(--primary), #ffffff, var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            animation: glow 3s infinite alternate;
        }

        @keyframes glow {
            from { filter: drop-shadow(0 0 10px rgba(0, 243, 255, 0.5)); }
            to { filter: drop-shadow(0 0 20px rgba(188, 19, 254, 0.8)); }
        }

        .hero-subtitle {
            font-family: var(--font-body);
            font-size: 1.2rem;
            color: var(--text-muted);
            margin-bottom: 40px;
            letter-spacing: 2px;
        }

        .cta-btn {
            padding: 15px 40px;
            background: transparent;
            border: 2px solid var(--primary);
            color: var(--primary);
            font-size: 1rem;
            font-weight: bold;
            text-transform: uppercase;
            cursor: pointer;
            transition: 0.3s;
            position: relative;
            overflow: hidden;
        }

        .cta-btn:hover {
            background: var(--primary);
            color: var(--bg-dark);
            box-shadow: 0 0 30px var(--primary);
        }

        /* --- GAMES SECTION --- */
        .section-title {
            text-align: center;
            font-size: 3rem;
            margin: 80px 0 40px;
            text-transform: uppercase;
            color: var(--text-main);
        }

        .section-title span {
            border-bottom: 3px solid var(--secondary);
        }

        .games-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 40px;
            padding: 0 5%;
            max-width: 1400px;
            margin: 0 auto;
        }

        .game-card {
            background: var(--bg-panel);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 10px;
            overflow: hidden;
            transition: 0.4s;
            position: relative;
        }

        .game-card:hover {
            transform: translateY(-10px);
            border-color: var(--secondary);
            box-shadow: 0 10px 30px rgba(188, 19, 254, 0.2);
        }

        .video-container {
            position: relative;
            width: 100%;
            padding-top: 56.25%; /* 16:9 Aspect Ratio */
            background: #000;
        }

        .video-container iframe {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            border: none;
        }

        .card-content {
            padding: 20px;
        }

        .game-title {
            font-size: 1.5rem;
            margin-bottom: 10px;
            color: var(--primary);
        }

        .game-desc {
            font-size: 0.9rem;
            color: var(--text-muted);
            line-height: 1.6;
            margin-bottom: 20px;
        }

        .play-btn {
            display: inline-block;
            padding: 8px 20px;
            background: var(--secondary);
            color: white;
            text-decoration: none;
            font-size: 0.8rem;
            border-radius: 4px;
            transition: 0.3s;
        }

        .play-btn:hover {
            background: #d54aff;
            box-shadow: 0 0 15px var(--secondary);
        }

        /* --- FOOTER --- */
        footer {
            margin-top: 100px;
            padding: 50px 20px;
            background: #000;
            text-align: center;
            border-top: 1px solid rgba(255, 255, 255, 0.1);
        }

        .footer-logo {
            font-size: 1.5rem;
            font-weight: bold;
            color: var(--text-main);
            margin-bottom: 20px;
            display: inline-block;
        }

        .socials a {
            color: var(--text-muted);
            margin: 0 10px;
            text-decoration: none;
            font-size: 1.2rem;
            transition: 0.3s;
        }

        .socials a:hover {
            color: var(--primary);
        }

        .copyright {
            margin-top: 20px;
            font-size: 0.8rem;
            color: #444;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            h1 { font-size: 3rem; }
            .nav-links a { font-size: 2rem; }
            .games-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
