            height: 100vh;
            width: 100%;
            background-image: linear-gradient(rgba(0, 51, 102, 0.6), rgba(0, 51, 102, 0.4)), url('https://images.unsplash.com/photo-1523050854058-8df90110c9f1?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: var(--text-light);
            padding: 0 20px;
        }

        .hero h1 {
            font-family: var(--font-heading);
            font-size: 3.5rem;
            margin-bottom: 1rem;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            max-width: 800px;
        }

        .hero p {
            font-size: 1.25rem;
            margin-bottom: 2.5rem;
            max-width: 600px;
            opacity: 0.9;
        }

        /* --- SECTIONS GENERAL --- */
        .section {
            padding: 5rem 10%;
        }

        .section-header {
            text-align: center;
            margin-bottom: 3rem;
        }

        .section-header h2 {
            font-family: var(--font-heading);
            font-size: 2.5rem;
            color: var(--primary-color);
            margin-bottom: 1rem;
        }

        .section-header .divider {
            width: 80px;
            height: 4px;
            background-color: var(--secondary-color);
            margin: 0 auto;
        }

        /* --- ACADEMIC OFFERINGS --- */
        .programs-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .program-card {
            background: #fff;
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 5px 15px rgba(0,0,0,0.1);
            transition: var(--transition);
            border-bottom: 4px solid transparent;
        }

        .program-card:hover {
            transform: translateY(-10px);
            border-bottom: 4px solid var(--secondary-color);
        }

        .program-img {
            height: 200px;
            width: 100%;
            object-fit: cover;
        }

        .program-content {
            padding: 1.5rem;
        }

        .program-content h3 {
            color: var(--primary-color);
            margin-bottom: 0.5rem;
            font-family: var(--font-heading);
        }

        .program-content p {
            font-size: 0.95rem;
            color: #666;
            margin-bottom: 1rem;
        }

        .program-link {
            color: var(--primary-color);
            font-weight: 700;
            font-size: 0.9rem;
            display: inline-flex;
            align-items: center;
        }

        .program-link::after {
            content: '→';
            margin-left: 5px;
            transition: var(--transition);
        }

        .program-link:hover::after {
            margin-left: 10px;
        }

        /* --- FACULTY SECTION --- */
        .faculty-section {
            background-color: var(--accent-color);
        }

        .faculty-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 2rem;
        }

        .faculty-card {
            background: #fff;
            padding: 2rem;
            text-align: center;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            transition: var(--transition);
        }

        .faculty-card:hover {
            box-shadow: 0 10px 20px rgba(0,0,0,0.1);
        }

        .faculty-img {
            width: 120px;
            height: 120px;
            border-radius: 50%;
            object-fit: cover;
            margin-bottom: 1rem;
            border: 3px solid var(--secondary-color);
        }

        .faculty-card h3 {
            color: var(--primary-color);
            margin-bottom: 0.2rem;
        }

        .faculty-card .role {
            color: var(--secondary-color);
            font-weight: 600;
            font-size: 0.9rem;
            margin-bottom: 1rem;
            display: block;
        }

        .faculty-card p {
            font-size: 0.9rem;
            color: #555;
        }

        /* --- RESOURCES SECTION --- */
        .resources-container {
            display: flex;
            flex-wrap: wrap;
            gap: 2rem;
            justify-content: center;
        }

        .resource-item {
            flex: 1 1 300px;
            background: var(--primary-color);
            color: var(--text-light);
            padding: 2rem;
            border-radius: 8px;
            display: flex;
            align-items: center;
            gap: 1.5rem;
            transition: var(--transition);
        }

        .resource-item:hover {
            background: #002244;
        }

        .resource-icon {
            font-size: 2.5rem;
            color: var(--secondary-color);
        }

        .resource-text h3 {
            font-family: var(--font-heading);
            margin-bottom: 0.5rem;
        }

        .resource-text a {
            text-decoration: underline;
            color: var(--secondary-color);
            font-size: 0.9rem;
        }

        /* --- FOOTER --- */
        footer {
            background-color: #1a1a1a;
            color: #ccc;
            padding: 4rem 10% 2rem;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 3rem;
            margin-bottom: 3rem;
        }

        .footer-col h4 {
            color: var(--text-light);
            margin-bottom: 1.5rem;
            font-family: var(--font-heading);
        }

        .footer-col ul li {
            margin-bottom: 0.8rem;
        }

        .footer-col ul li a:hover {
            color: var(--secondary-color);
        }

        .footer-bottom {
            border-top: 1px solid #333;
            padding-top: 2rem;
            text-align: center;
            font-size: 0.9rem;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .navbar {
                flex-direction: column;
                padding: 1rem;
            }

            .nav-links {
                margin-top: 1rem;
                flex-wrap: wrap;
                justify-content: center;
                gap: 1rem;
            }

            .hero h1 {
                font-size: 2.5rem;
            }

            .section {
                padding: 3rem 5%;
            }
        }
    </style>
</head>
