            font-size: 0.9rem;
            margin-bottom: 5px;
        }

        .float-info span {
            font-weight: bold;
            color: var(--accent-color);
        }

        /* Positioning specific items */
        .pos-1 { top: 20%; left: 15%; }
        .pos-2 { top: 60%; left: 75%; }
        .pos-3 { top: 25%; left: 80%; }

        /* --- CATEGORIES SECTION --- */
        .categories-section {
            padding: 80px 40px;
            background-color: var(--secondary-color);
        }

        .section-header {
            text-align: center;
            margin-bottom: 50px;
        }

        .section-header h2 {
            font-family: var(--font-heading);
            font-size: 2.5rem;
            color: var(--primary-color);
            margin-bottom: 10px;
        }

        .section-header .divider {
            width: 60px;
            height: 3px;
            background-color: var(--accent-color);
            margin: 0 auto;
        }

        .categories-grid {
            display: flex;
            justify-content: center;
            gap: 30px;
            flex-wrap: wrap;
        }

        .category-card {
            background: var(--white);
            width: 220px;
            height: 280px;
            position: relative;
            overflow: hidden;
            cursor: pointer;
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
        }

        .category-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .category-card:hover img {
            transform: scale(1.1);
        }

        .category-overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 20px;
            background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
            color: var(--white);
            text-align: center;
        }

        .category-overlay h3 {
            font-family: var(--font-heading);
            font-size: 1.4rem;
            margin-bottom: 5px;
        }

        .category-overlay span {
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            border-bottom: 1px solid var(--white);
            padding-bottom: 2px;
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 60px 40px;
            text-align: center;
        }

        .footer-logo {
            font-family: var(--font-heading);
            font-size: 2rem;
            margin-bottom: 20px;
        }

        .footer-links {
            display: flex;
            justify-content: center;
            gap: 30px;
            margin-bottom: 30px;
        }

        .footer-links a {
            font-size: 0.9rem;
            opacity: 0.7;
            transition: var(--transition);
        }

        .footer-links a:hover {
            opacity: 1;
        }

        .copyright {
            font-size: 0.8rem;
            opacity: 0.5;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .navbar {
                padding: 0 20px;
            }

            .nav-links {
                display: none; /* Hidden for simplicity in this demo */
            }

            .hero-content h1 {
                font-size: 2.5rem;
            }

            .float-item {
                display: none; /* Hide floating items on mobile for cleaner look */
            }

            .categories-grid {
                flex-direction: column;
                align-items: center;
            }
        }
    </style>
</head>
