            font-size: 2.5rem;
            color: var(--primary-color);
            margin-bottom: 15px;
        }

        .intro p {
            color: var(--text-light);
            max-width: 600px;
            margin: 0 auto;
        }

        /* Three Column Grid */
        .grid-layout {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 40px;
        }

        /* --- Column Styling --- */
        .column {
            background: var(--white);
            padding: 40px;
            border-radius: 4px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.03);
            transition: transform 0.3s ease;
            border-top: 4px solid var(--secondary-color);
        }

        .column:hover {
            transform: translateY(-5px);
        }

        .column h3 {
            font-family: var(--font-heading);
            font-size: 1.8rem;
            color: var(--primary-color);
            margin-bottom: 20px;
            text-align: center;
        }

        /* --- Services Specifics --- */
        .service-item {
            margin-bottom: 25px;
            text-align: center;
        }

        .service-icon {
            font-size: 2rem;
            color: var(--accent-color);
