        .portfolio-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
        }

        .portfolio-img {
            width: 100%;
            height: 120px;
            object-fit: cover;
            border-radius: 2px;
            transition: opacity 0.3s;
        }

        .portfolio-img:hover {
            opacity: 0.8;
        }

        .portfolio-caption {
            font-size: 0.8rem;
            text-align: center;
            margin-top: 5px;
            color: var(--text-light);
            font-style: italic;
        }

        /* --- Testimonials Specifics --- */
        .testimonial {
            margin-bottom: 30px;
            text-align: center;
        }

        .quote {
            font-family: var(--font-heading);
            font-size: 1.1rem;
            color: var(--text-dark);
            margin-bottom: 15px;
            position: relative;
        }

        .quote::before {
            content: '"';
            font-size: 3rem;
            color: var(--secondary-color);
            position: absolute;
            top: -20px;
            left: 50%;
            transform: translateX(-50%);
            opacity: 0.5;
        }

        .client-name {
            font-weight: bold;
            font-size: 0.9rem;
            color: var(--primary-color);
        }

        /* --- Footer --- */
        footer {
            background-color: var(--primary-color);
            color: var(--white);
            text-align: center;
            padding: 40px 20px;
            margin-top: 60px;
        }

        footer p {
            font-size: 0.9rem;
            opacity: 0.8;
        }

        /* --- Responsive Design --- */
        @media (max-width: 900px) {
            .grid-layout {
                grid-template-columns: 1fr;
            }

            header {
                height: 60vh;
                justify-content: center;
            }

            .logo-container {
                margin: 0;
            }
        }
    </style>
</head>
