        }

        .search-input {
            flex: 2;
            padding: 0.8rem 1rem;
            border: 1px solid var(--border);
            border-radius: 4px;
            font-size: 1rem;
            min-width: 200px;
        }

        .filter-select {
            flex: 1;
            padding: 0.8rem 1rem;
            border: 1px solid var(--border);
            border-radius: 4px;
            font-size: 1rem;
            background: var(--white);
            min-width: 150px;
            cursor: pointer;
        }

        .btn-filter {
            padding: 0.8rem 1.5rem;
            background: var(--primary);
