            margin-bottom: 0.5rem;
            color: var(--text-dark);
        }

        .card-address {
            color: var(--text-light);
            font-size: 0.9rem;
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .card-features {
            display: flex;
            gap: 1.5rem;
            font-size: 0.9rem;
            color: var(--text-dark);
            border-top: 1px solid var(--border);
            padding-top: 1rem;
        }

        .feature {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .feature span { font-weight: 600; }

        /* --- Footer --- */
        footer {
            background: var(--primary);
            color: var(--white);
            padding: 4rem 5% 2rem;
            margin-top: 4rem;
        }

        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 3rem;
            max-width: 1400px;
            margin: 0 auto;
            border-bottom: 1px solid rgba(255,255,255,0.1);
            padding-bottom: 3rem;
        }

        .footer-col h3 {
            font-size: 1.2rem;
