        .footer-col p {
            color: #aaa;
            margin-bottom: 0.5rem;
            font-size: 0.9rem;
        }

        .footer-links li {
            margin-bottom: 0.8rem;
        }

        .footer-links a {
            color: #ccc;
            font-size: 0.9rem;
        }

        .footer-links a:hover {
            color: var(--accent);
            padding-left: 5px;
        }

        .copyright {
            text-align: center;
            padding-top: 2rem;
            color: #666;
            font-size: 0.8rem;
        }

        /* --- Responsive --- */
        @media (max-width: 768px) {
