        .hero {
            position: relative;
            height: 600px;
            background-image: linear-gradient(rgba(0, 86, 179, 0.7), rgba(0, 86, 179, 0.5)), url('https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80');
