        .service-card:hover {
            transform: translateY(-5px);
        }

        .service-icon {
            font-size: 3rem;
            margin-bottom: 20px;
            display: inline-block;
        }

        .service-card h3 {
            margin-bottom: 15px;
            color: var(--primary-color);
        }

        /* --- Doctors Section --- */
        .doctors-section {
            background-color: var(--accent-color);
        }

        .doctors-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 30px;
        }

        .doctor-card {
            background: var(--white);
            border-radius: 10px;
            overflow: hidden;
            box-shadow: var(--shadow);
            text-align: center;
        }

        .doctor-img {
            height: 250px;
            width: 100%;
            object-fit: cover;
            background-color: #ddd;
        }

        .doctor-info {
            padding: 25px;
        }

        .doctor-info h3 {
            color: var(--text-dark);
            margin-bottom: 5px;
        }

        .doctor-info .specialty {
            color: var(--secondary-color);
            font-weight: 600;
            margin-bottom: 15px;
            display: block;
        }

        .doctor-info p {
            font-size: 0.9rem;
            color: var(--text-light);
        }

        /* --- Testimonials Section --- */
        .testimonials-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .testimonial-card {
            background: var(--white);
            padding: 30px;
            border-radius: 10px;
            box-shadow: var(--shadow);
            position: relative;
        }

        .testimonial-card::before {
            content: "“";
            font-size: 5rem;
            color: var(--accent-color);
            position: absolute;
            top: -10px;
            left: 20px;
            font-family: serif;
        }

        .testimonial-text {
            font-style: italic;
            color: var(--text-light);
            margin-bottom: 20px;
            position: relative;
            z-index: 1;
        }

        .patient-info {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .patient-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background-color: #ccc;
            object-fit: cover;
        }

        .patient-name {
            font-weight: 700;
            color: var(--text-dark);
        }

        /* --- Footer --- */
        footer {
            background-color: var(--text-dark);
