<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>NEON MARKET | High Contrast E-Commerce</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --bg-color: #050505;
            --card-bg: #121212;
            --text-main: #ffffff;
            --text-muted: #a0a0a0;
            --accent-primary: #ccff00; /* Neon Lime */
            --accent-secondary: #00f0ff; /* Cyan */
            --accent-danger: #ff003c; /* Hot Pink */
            --border-width: 2px;
            --font-main: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-main);
            font-family: var(--font-main);
            overflow-x: hidden;
        }

        a { text-decoration: none; color: inherit; }
        ul { list-style: none; }

        /* --- UTILITIES --- */
        .container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .btn {
            display: inline-block;
            padding: 12px 24px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            border: var(--border-width) solid var(--text-main);
            background: transparent;
            color: var(--text-main);
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .btn-primary {
            background-color: var(--accent-primary);
            color: var(--bg-color);
            border-color: var(--accent-primary);
        }

        .btn-primary:hover {
            background-color: transparent;
            color: var(--accent-primary);
            box-shadow: 0 0 15px var(--accent-primary);
        }

        .btn-outline:hover {
            background-color: var(--text-main);
            color: var(--bg-color);
        }

        /* --- HEADER --- */
        header {
            position: sticky;
            top: 0;
            z-index: 1000;
            background-color: rgba(5, 5, 5, 0.95);
            border-bottom: 1px solid #333;
            padding: 20px 0;
        }

        .nav-wrapper {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            font-size: 2rem;
            font-weight: 900;
            letter-spacing: -2px;
            color: var(--text-main);
            text-transform: uppercase;
        }

        .logo span {
            color: var(--accent-primary);
        }

        nav ul {
            display: flex;
            gap: 30px;
        }

        nav a {
            font-weight: 600;
            font-size: 0.9rem;
            text-transform: uppercase;
            transition: color 0.2s;
        }

        nav a:hover {
            color: var(--accent-primary);
        }

        .cart-icon {
            position: relative;
            cursor: pointer;
        }

        .cart-count {
            position: absolute;
            top: -8px;
            right: -10px;
            background-color: var(--accent-danger);
            color: white;
            font-size: 0.7rem;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 60vh;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            background: radial-gradient(circle at center, #1a1a1a 0%, #050505 100%);
            border-bottom: var(--border-width) solid var(--accent-primary);
            position: relative;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background-image: linear-gradient(45deg, #111 25%, transparent 25%, transparent 75%, #111 75%, #111), 
                              linear-gradient(45deg, #111 25%, transparent 25%, transparent 75%, #111 75%, #111);
            background-size: 40px 40px;
            background-position: 0 0, 20px 20px;
            opacity: 0.3;
            z-index: 0;
        }

        .hero-content {
            z-index: 1;
            max-width: 800px;
        }

        .hero h1 {
            font-size: 4rem;
            line-height: 1;
            margin-bottom: 20px;
            text-transform: uppercase;
            font-weight: 900;
        }

        .hero h1 span {
            color: transparent;
            -webkit-text-stroke: 2px var(--accent-primary);
        }

        .hero p {
            font-size: 1.2rem;
            color: var(--text-muted);
            margin-bottom: 30px;
        }

        /* --- CAROUSEL SECTION --- */
        .carousel-section {
            padding: 60px 0;
            background-color: var(--bg-color);
        }

