            text-transform: uppercase;
            font-weight: 800;
            border-left: 5px solid var(--accent-primary);
            padding-left: 15px;
        }

        .carousel-controls {
            display: flex;
            gap: 10px;
        }

        .control-btn {
            width: 50px;
            height: 50px;
            background: var(--card-bg);
            border: 1px solid #333;
            color: var(--text-main);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.5rem;
            transition: 0.2s;
        }

        .control-btn:hover {
            background: var(--accent-primary);
            color: var(--bg-color);
            border-color: var(--accent-primary);
        }

        .carousel-wrapper {
            position: relative;
            overflow: hidden;
            padding: 20px 0;
        }

        .carousel-track {
            display: flex;
            gap: 20px;
            overflow-x: auto;
            scroll-behavior: smooth;
            padding: 10px 20px;
            scrollbar-width: none; /* Firefox */
        }

        .carousel-track::-webkit-scrollbar {
            display: none; /* Chrome/Safari */
        }

        /* --- PRODUCT CARD --- */
        .product-card {
            min-width: 300px;
            background-color: var(--card-bg);
            border: 1px solid #333;
            position: relative;
            transition: transform 0.3s ease, border-color 0.3s ease;
            display: flex;
            flex-direction: column;
        }

        .product-card:hover {
            transform: translateY(-5px);
            border-color: var(--accent-primary);
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        .badge {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: var(--accent-danger);
            color: white;
            padding: 5px 10px;
            font-size: 0.75rem;
            font-weight: bold;
            text-transform: uppercase;
            z-index: 2;
        }

        .card-image {
            height: 300px;
            width: 100%;
            background-color: #1a1a1a;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
            position: relative;
        }

        .card-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
            filter: grayscale(100%);
        }

        .product-card:hover .card-image img {
            transform: scale(1.1);
            filter: grayscale(0%);
        }

        .card-details {
            padding: 20px;
            flex-grow: 1;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        .product-category {
            color: var(--accent-secondary);
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 5px;
        }

        .product-title {
            font-size: 1.2rem;
            font-weight: 700;
            margin-bottom: 10px;
            color: var(--text-main);
        }

        .product-price {
            font-size: 1.5rem;
            font-weight: 300;
            color: var(--text-main);
            margin-bottom: 15px;
        }

        .product-price span {
            text-decoration: line-through;
            color: #555;
            font-size: 1rem;
            margin-left: 10px;
        }

        .add-btn {
            width: 100%;
            padding: 10px;
            background: transparent;
            border: 1px solid #444;
            color: var(--text-main);
            text-transform: uppercase;
            font-weight: bold;
            cursor: pointer;
            transition: 0.2s;
        }

        .add-btn:hover {
            background: var(--text-main);
            color: var(--bg-color);
        }

        /* --- FOOTER --- */
        footer {
            background-color: #000;
            border-top: 1px solid #333;
            padding: 60px 0 20px;
            margin-top: 60px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h4 {
            color: var(--accent-primary);
            margin-bottom: 20px;
            text-transform: uppercase;
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: var(--text-muted);
            transition: color 0.2s;
        }

        .footer-col ul li a:hover {
            color: var(--text-main);
        }

        .copyright {
            text-align: center;
            color: #444;
            font-size: 0.8rem;
            padding-top: 20px;
            border-top: 1px solid #111;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .hero h1 { font-size: 2.5rem; }
            .nav-wrapper { flex-direction: column; gap: 15px; }
            nav ul { gap: 15px; }
            .section-header { flex-direction: column; align-items: flex-start; gap: 15px; }
        }
    </style>
</head>
