        /* --- ABOUT SECTION --- */
        .about {
            padding: 6rem 0;
            background-color: var(--bg-color);
        }

        .about-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 4rem;
            align-items: center;
        }

