    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const slides = document.querySelectorAll('.slide');
            const nextBtn = document.getElementById('nextBtn');
            const prevBtn = document.getElementById('prevBtn');
            const progressBar = document.getElementById('progressBar');

            let currentSlide = 0;
            const slideIntervalTime = 6000; // 6 seconds per slide
            let slideInterval;
            let progressInterval;

            function showSlide(index) {
                // Remove active class from current slide
                slides[currentSlide].classList.remove('active');

                // Calculate new index
                currentSlide = (index + slides.length) % slides.length;

                // Add active class to new slide
                slides[currentSlide].classList.add('active');

                // Reset animation
                resetProgress();
            }

            function nextSlide() {
                showSlide(currentSlide + 1);
            }

            function prevSlide() {
                showSlide(currentSlide - 1);
            }

            function resetProgress() {
                clearInterval(slideInterval);
                clearInterval(progressInterval);

                let width = 0;
                const intervalStep = 50; // Update every 50ms
                const increment = (intervalStep / slideIntervalTime) * 100;

                progressBar.style.width = '0%';

                // Progress bar animation
                progressInterval = setInterval(() => {
                    width += increment;
                    progressBar.style.width = width + '%';
                    if (width >= 100) clearInterval(progressInterval);
                }, intervalStep);

                // Slide transition
                slideInterval = setInterval(nextSlide, slideIntervalTime);
            }

            // Event Listeners
            nextBtn.addEventListener('click', () => {
                nextSlide();
            });

            prevBtn.addEventListener('click', () => {
                prevSlide();
            });

            // Pause on hover (optional UX improvement)
            const container = document.querySelector('.slideshow-container');
            container.addEventListener('mouseenter', () => {
                clearInterval(slideInterval);
                clearInterval(progressInterval);
            });

            container.addEventListener('mouseleave', () => {
                resetProgress();
            });

            // Initialize
            resetProgress();
        });
    </script>
</body>
</html>
