    <!-- Background Canvas -->
    <canvas id="wave-canvas"></canvas>

    <!-- Circular Navigation -->
    <div class="nav-wrapper">
        <div class="menu-btn" id="menuBtn">
            <span></span>
        </div>
        <div class="circular-menu" id="circularMenu">
            <a href="#" class="menu-item" style="--i:1">🏠</a>
            <a href="#" class="menu-item" style="--i:2">🔍</a>
            <a href="#" class="menu-item" style="--i:3">📚</a>
            <a href="#" class="menu-item" style="--i:4">👤</a>
            <a href="#" class="menu-item" style="--i:5">⚙️</a>
        </div>
    </div>

    <!-- Main Content -->
    <div class="container">
        <div class="hero-content">
            <h1>FEEL THE<br>MUSIC</h1>
            <p class="subtitle">Immersive audio streaming with high-fidelity sound and a visual experience like no other.</p>
            <a href="#" class="cta-button">Sign Up for Free</a>
        </div>
    </div>

    <!-- Footer -->
    <footer>
        <div class="footer-content">
            <div class="footer-title">Trending Now</div>
            <div class="tags-container">
                <a href="#" class="tag">Lo-Fi Beats</a>
                <a href="#" class="tag">The Weeknd</a>
                <a href="#" class="tag">Deep House</a>
                <a href="#" class="tag">Taylor Swift</a>
                <a href="#" class="tag">Synthwave</a>
                <a href="#" class="tag">Drake</a>
                <a href="#" class="tag">Jazz Classics</a>
                <a href="#" class="tag">Indie Rock</a>
                <a href="#" class="tag">Billie Eilish</a>
                <a href="#" class="tag">Techno</a>
            </div>
        </div>
    </footer>

    <script>
        // --- Waveform Animation ---
        const canvas = document.getElementById('wave-canvas');
        const ctx = canvas.getContext('2d');

        let width, height;
        let waves = [];

        function resize() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
        }

        window.addEventListener('resize', resize);
        resize();

        class Wave {
            constructor(y, amplitude, frequency, speed, color) {
                this.y = y;
                this.amplitude = amplitude;
                this.frequency = frequency;
                this.speed = speed;
                this.color = color;
                this.offset = Math.random() * 100;
            }

            draw(time) {
                ctx.beginPath();
                ctx.moveTo(0, height); // Start bottom left

                for (let x = 0; x <= width; x += 5) {
                    // Combine sine waves for organic feel
                    const y = this.y + 
                              Math.sin(x * this.frequency + time * this.speed + this.offset) * this.amplitude +
                              Math.sin(x * this.frequency * 0.5 + time * this.speed * 0.5) * (this.amplitude * 0.5);
                    ctx.lineTo(x, y);
                }

                ctx.lineTo(width, height); // Bottom right
                ctx.closePath();

                // Gradient fill
                const gradient = ctx.createLinearGradient(0, this.y - this.amplitude, 0, height);
                gradient.addColorStop(0, this.color);
                gradient.addColorStop(1, 'rgba(0,0,0,0)');

                ctx.fillStyle = gradient;
                ctx.fill();
            }
        }

        // Initialize waves
        waves.push(new Wave(height * 0.6, 50, 0.003, 0.002, 'rgba(0, 242, 234, 0.15)')); // Cyan
        waves.push(new Wave(height * 0.7, 70, 0.002, 0.003, 'rgba(255, 0, 80, 0.1)'));   // Pink
        waves.push(new Wave(height * 0.8, 100, 0.001, 0.001, 'rgba(100, 0, 255, 0.1)')); // Purple

        let time = 0;

        function animate() {
            ctx.clearRect(0, 0, width, height);
            time += 1;

            waves.forEach(wave => wave.draw(time));

            requestAnimationFrame(animate);
        }

        animate();

        // --- Circular Menu Logic ---
        const menuBtn = document.getElementById('menuBtn');
        const circularMenu = document.getElementById('circularMenu');
        const menuItems = document.querySelectorAll('.menu-item');
        let isOpen = false;

        menuBtn.addEventListener('click', () => {
            isOpen = !isOpen;

            if (isOpen) {
                menuBtn.classList.add('active');
                circularMenu.classList.add('open');

                // Animate items out
                menuItems.forEach((item, index) => {
                    const angle = (index / menuItems.length) * 2 * Math.PI;
                    const radius = 100; // Distance from center

                    // Calculate position relative to center of button
                    // We use CSS transforms to move them out
                    const x = Math.cos(angle) * radius;
                    const y = Math.sin(angle) * radius;

                    item.style.transitionDelay = `${index * 0.05}s`;
                    item.style.transform = `translate(${x}px, ${y}px) scale(1)`;
                    item.style.opacity = '1';
                });
            } else {
                menuBtn.classList.remove('active');
                circularMenu.classList.remove('open');

                // Animate items back in
                menuItems.forEach((item, index) => {
                    item.style.transitionDelay = `${(menuItems.length - index) * 0.05}s`;
                    item.style.transform = `translate(0, 0) scale(0.5)`;
                    item.style.opacity = '0';
                });
            }
        });
    </script>
</body>
</html>
