        }

        .header-content {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 10px;
            text-decoration: none;
        }

        .logo-icon {
            width: 40px;
            height: 40px;
            background-color: var(--primary-blue);
            clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
        }

        .logo-text {
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--primary-blue);
            letter-spacing: -0.5px;
        }

        .logo-text span {
            color: var(--secondary-blue);
        }

        nav ul {
            list-style: none;
            display: flex;
            gap: 30px;
        }

        nav a {
            text-decoration: none;
            color: var(--text-dark);
            font-weight: 500;
            font-size: 0.95rem;
            transition: color 0.3s ease;
        }

        nav a:hover {
            color: var(--secondary-blue);
        }

        .btn-contact {
            background-color: var(--primary-blue);
            color: var(--white);
            padding: 10px 20px;
            border-radius: 4px;
            text-decoration: none;
            font-weight: 600;
            transition: background 0.3s;
        }

        .btn-contact:hover {
            background-color: var(--secondary-blue);
        }

        /* --- HERO SECTION --- */
        .hero {
            background: linear-gradient(135deg, var(--primary-blue) 0%, var(--secondary-blue) 100%);
            color: var(--white);
            padding: 80px 0;
            text-align: center;
        }

        .hero h1 {
            font-size: 3rem;
            margin-bottom: 20px;
            font-weight: 300;
        }

        .hero h1 strong {
            font-weight: 700;
        }

        .hero p {
            font-size: 1.2rem;
            max-width: 700px;
            margin: 0 auto 30px auto;
            opacity: 0.9;
        }

        /* --- MAIN CONTENT (LEFT & RIGHT) --- */
        .main-content {
            padding: 60px 0;
            background-color: var(--white);
            flex: 1;
        }

        .section-title {
            color: var(--primary-blue);
            font-size: 1.8rem;
            margin-bottom: 20px;
            position: relative;
            padding-bottom: 10px;
        }

        .section-title::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: 0;
            width: 50px;
            height: 3px;
            background-color: var(--secondary-blue);
        }

        /* Left Column: About & Philosophy */
        .about-text {
            color: var(--text-light);
            margin-bottom: 30px;
            font-size: 1.05rem;
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
            margin-top: 30px;
        }

        .stat-card {
            background-color: var(--light-bg);
            padding: 20px;
            border-left: 4px solid var(--primary-blue);
        }

        .stat-number {
            display: block;
            font-size: 2rem;
            font-weight: 700;
            color: var(--primary-blue);
        }

        .stat-label {
            font-size: 0.9rem;
            color: var(--text-light);
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        /* Right Column: Services */
        .service-list {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .service-item {
            display: flex;
            align-items: flex-start;
            gap: 15px;
            padding: 20px;
            border: 1px solid var(--border-color);
            border-radius: 6px;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .service-item:hover {
            transform: translateY(-3px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
            border-color: var(--accent-blue);
        }

        .service-icon {
            background-color: rgba(0, 51, 102, 0.1);
            color: var(--primary-blue);
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            flex-shrink: 0;
        }

        .service-content h3 {
            font-size: 1.1rem;
            margin-bottom: 5px;
            color: var(--text-dark);
        }

        .service-content p {
            font-size: 0.9rem;
            color: var(--text-light);
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary-blue);
            color: var(--white);
            padding: 40px 0;
            margin-top: auto;
        }

        .footer-content {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 20px;
        }

        .footer-logo {
            font-weight: 700;
            font-size: 1.2rem;
        }

        .footer-links a {
            color: rgba(255,255,255,0.7);
            text-decoration: none;
            margin-left: 20px;
            font-size: 0.9rem;
        }

        .footer-links a:hover {
            color: var(--white);
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .header-content {
                flex-direction: column;
                gap: 20px;
            }

            nav ul {
                flex-direction: column;
                align-items: center;
                gap: 15px;
            }

            .row {
                flex-direction: column;
            }

            .hero h1 {
                font-size: 2rem;
            }
        }
    </style>
