<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Apex Financial | Secure Wealth Management</title>
    <style>
        /* --- Reset & Variables --- */
        :root {
            --primary-color: #0f172a; /* Deep Navy */
            --secondary-color: #334155; /* Slate */
            --accent-color: #0ea5e9; /* Sky Blue */
            --cta-color: #f59e0b; /* Amber/Gold */
            --bg-light: #f8fafc;
            --text-dark: #1e293b;
            --text-light: #94a3b8;
            --white: #ffffff;
            --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: var(--text-dark);
            background-color: var(--bg-light);
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: 0.3s;
        }

        ul {
            list-style: none;
        }

        /* --- Header & Navigation --- */
        header {
            background-color: var(--white);
            box-shadow: var(--shadow);
            position: sticky;
            top: 0;
            z-index: 1000;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        nav {
            display: flex;
            justify-content: space-between;
            align-items: center;
            height: 80px;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--primary-color);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .logo span {
            color: var(--accent-color);
        }

        .nav-links {
            display: flex;
            gap: 30px;
        }

        .nav-links a {
            font-weight: 500;
            color: var(--secondary-color);
        }

        .nav-links a:hover {
            color: var(--accent-color);
        }

        .login-btn {
            border: 2px solid var(--primary-color);
            padding: 8px 20px;
            border-radius: 5px;
            font-weight: 600;
            color: var(--primary-color);
        }

        .login-btn:hover {
            background-color: var(--primary-color);
            color: var(--white);
        }

        /* --- Hero Section --- */
        .hero {
            background: linear-gradient(135deg, var(--primary-color) 0%, #1e293b 100%);
            color: var(--white);
            padding: 100px 0;
            position: relative;
            overflow: hidden;
        }

        .hero-content {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 50px;
        }

        .hero-text {
            flex: 1;
        }

        .hero-text h1 {
            font-size: 3rem;
            margin-bottom: 20px;
            line-height: 1.2;
        }

        .hero-text p {
            font-size: 1.1rem;
            color: var(--text-light);
            margin-bottom: 30px;
            max-width: 500px;
        }

        .cta-button {
            display: inline-block;
            background-color: var(--cta-color);
            color: var(--primary-color);
            padding: 15px 35px;
            border-radius: 5px;
            font-weight: 700;
            font-size: 1.1rem;
            box-shadow: 0 4px 15px rgba(245, 158, 11, 0.4);
        }

        .cta-button:hover {
            background-color: #d97706;
            transform: translateY(-2px);
        }

        /* --- Login Form Card --- */
        .login-card {
            background-color: var(--white);
            padding: 40px;
            border-radius: 10px;
            width: 100%;
            max-width: 400px;
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.2);
        }

        .login-card h3 {
            color: var(--primary-color);
            margin-bottom: 20px;
            text-align: center;
        }

        .form-group {
            margin-bottom: 15px;
        }

        .form-group label {
            display: block;
            margin-bottom: 5px;
            font-size: 0.9rem;
            color: var(--secondary-color);
        }

        .form-group input {
            width: 100%;
            padding: 12px;
            border: 1px solid #cbd5e1;
            border-radius: 5px;
            font-size: 1rem;
        }

        .form-group input:focus {
            outline: none;
            border-color: var(--accent-color);
        }

        .submit-btn {
            width: 100%;
            padding: 12px;
            background-color: var(--primary-color);
            color: var(--white);
            border: none;
            border-radius: 5px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            margin-top: 10px;
        }

        .submit-btn:hover {
            background-color: #1e293b;
        }

        .forgot-pass {
            display: block;
            text-align: center;
            margin-top: 15px;
            font-size: 0.85rem;
            color: var(--accent-color);
        }

        /* --- Services Section --- */
        .services {
            padding: 80px 0;
            background-color: var(--white);
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-header h2 {
            font-size: 2.2rem;
            color: var(--primary-color);
            margin-bottom: 10px;
        }

        .section-header p {
            color: var(--secondary-color);
        }

        .services-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .service-card {
            background-color: var(--bg-light);
            padding: 30px;
            border-radius: 8px;
            border: 1px solid #e2e8f0;
            transition: 0.3s;
        }

        .service-card:hover {
            transform: translateY(-5px);
            box-shadow: var(--shadow);
            border-color: var(--accent-color);
        }

        .icon-box {
            width: 50px;
            height: 50px;
            background-color: rgba(14, 165, 233, 0.1);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
            color: var(--accent-color);
            font-size: 1.5rem;
        }

        .service-card h3 {
            margin-bottom: 15px;
            color: var(--primary-color);
        }

        .service-card p {
            color: var(--secondary-color);
            font-size: 0.95rem;
        }

        /* --- Testimonials --- */
        .testimonials {
            padding: 80px 0;
            background-color: var(--bg-light);
        }

        .testimonial-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .testimonial-card {
            background-color: var(--white);
            padding: 30px;
            border-radius: 8px;
            box-shadow: var(--shadow);
        }

        .quote {
            font-style: italic;
            color: var(--secondary-color);
            margin-bottom: 20px;
            position: relative;
        }

        .quote::before {
            content: "“";
            font-size: 3rem;
            color: var(--accent-color);
            opacity: 0.3;
            position: absolute;
            top: -20px;
            left: -10px;
        }

        .client-info {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .client-avatar {
            width: 50px;
            height: 50px;
            background-color: #cbd5e1;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            color: var(--primary-color);
        }

        .client-details h4 {
            font-size: 1rem;
            color: var(--primary-color);
        }

        .client-details span {
            font-size: 0.85rem;
            color: var(--text-light);
        }

        /* --- Footer --- */
        footer {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 60px 0 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h4 {
            margin-bottom: 20px;
            color: var(--accent-color);
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: #cbd5e1;
        }

        .footer-col ul li a:hover {
            color: var(--white);
        }

        .contact-info p {
            margin-bottom: 10px;
            color: #cbd5e1;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .copyright {
            text-align: center;
            padding-top: 20px;
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            color: #64748b;
            font-size: 0.9rem;
        }

        /* --- Responsive --- */
        @media (max-width: 768px) {
            .hero-content {
                flex-direction: column;
                text-align: center;
            }

            .hero-text p {
                margin: 0 auto 30px;
            }

            .nav-links {
                display: none; /* Simple hiding for mobile demo */
            }
        }
    </style>
</head>
