<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Prism Creative Agency</title>
    <style>
        :root {
            --primary: #FF0055;
            --secondary: #00E5FF;
            --accent: #FFD500;
            --dark: #121212;
            --light: #F4F4F9;
            --text-dark: #1a1a1a;
            --text-light: #ffffff;
            --font-main: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--light);
            color: var(--text-dark);
            overflow-x: hidden;
        }

        /* --- Header --- */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1.5rem 5%;
            background: rgba(255, 255, 255, 0.9);
            backdrop-filter: blur(10px);
            position: sticky;
            top: 0;
            z-index: 1000;
            border-bottom: 3px solid var(--primary);
        }

        .logo {
            font-size: 1.8rem;
            font-weight: 900;
            text-transform: uppercase;
            letter-spacing: -1px;
            color: var(--dark);
        }

        .logo span {
            color: var(--primary);
        }

        nav ul {
            display: flex;
            list-style: none;
            gap: 2rem;
        }

        nav a {
            text-decoration: none;
            color: var(--dark);
            font-weight: 700;
            font-size: 1rem;
            transition: color 0.3s;
        }

        nav a:hover {
            color: var(--primary);
        }

        /* --- Hero Section --- */
        .hero {
            text-align: center;
            padding: 4rem 1rem;
            background: var(--dark);
            color: var(--text-light);
            position: relative;
            overflow: hidden;
        }

        .hero h1 {
            font-size: 3.5rem;
            margin-bottom: 1rem;
            line-height: 1.1;
        }

        .hero h1 span {
            color: var(--secondary);
            display: inline-block;
            animation: bounce 2s infinite;
        }

        .hero p {
            font-size: 1.2rem;
            color: #ccc;
            max-width: 600px;
            margin: 0 auto;
        }

        /* --- Main Layout --- */
        .container {
            display: grid;
            grid-template-columns: 1fr 350px;
            gap: 2rem;
            max-width: 1400px;
            margin: 0 auto;
            padding: 3rem 2rem;
        }

        /* --- Carousel Section --- */
        .carousel-section {
            background: white;
            padding: 2rem;
            border-radius: 20px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.05);
            position: relative;
        }

        .section-title {
            font-size: 2rem;
            margin-bottom: 1.5rem;
            color: var(--dark);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .section-title::before {
            content: '';
            width: 10px;
            height: 10px;
            background: var(--accent);
            border-radius: 50%;
            display: block;
        }

        .carousel-wrapper {
            position: relative;
            height: 400px;
            perspective: 1000px;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .carousel-track {
            position: relative;
            width: 100%;
            height: 100%;
            transform-style: preserve-3d;
            transition: transform 0.5s ease-out;
        }

        .project-card {
            position: absolute;
            width: 300px;
            height: 350px;
            left: 50%;
            top: 50%;
            margin-left: -150px;
            margin-top: -175px;
            background-size: cover;
            background-position: center;
            border-radius: 15px;
            box-shadow: 0 15px 35px rgba(0,0,0,0.2);
            transition: all 0.5s ease;
            cursor: pointer;
            overflow: hidden;
            border: 4px solid white;
        }

        .project-card:hover {
            box-shadow: 0 25px 50px rgba(0,0,0,0.3);
            z-index: 10 !important;
        }

        .project-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 1rem;
            background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
            color: white;
            opacity: 0;
            transition: opacity 0.3s;
        }

        .project-card:hover .project-info {
            opacity: 1;
        }

        .carousel-controls {
            display: flex;
            justify-content: center;
            gap: 1rem;
            margin-top: 2rem;
        }

        .btn {
            padding: 10px 25px;
            border: none;
            border-radius: 50px;
            font-weight: bold;
            cursor: pointer;
            transition: transform 0.2s, background 0.2s;
        }

        .btn-primary {
            background: var(--primary);
            color: white;
        }

        .btn-primary:hover {
            background: #d60047;
            transform: scale(1.05);
        }

        .btn-outline {
            background: transparent;
            border: 2px solid var(--dark);
            color: var(--dark);
        }

        .btn-outline:hover {
            background: var(--dark);
            color: white;
        }

        /* --- Sidebar (Testimonials) --- */
        .sidebar {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
        }

        .testimonial-card {
            background: white;
            padding: 1.5rem;
            border-radius: 15px;
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
            border-left: 5px solid var(--secondary);
            transition: transform 0.3s;
        }

        .testimonial-card:hover {
            transform: translateY(-5px);
        }

        .quote {
            font-style: italic;
            color: #555;
            margin-bottom: 1rem;
            line-height: 1.5;
        }

        .client {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .client-avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background-color: var(--accent);
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            color: var(--dark);
        }

        .client-info h4 {
            font-size: 0.9rem;
            margin-bottom: 2px;
        }

        .client-info span {
            font-size: 0.8rem;
            color: #888;
        }

        /* --- Footer --- */
        footer {
            background: var(--dark);
            color: white;
            text-align: center;
            padding: 3rem;
            margin-top: 3rem;
        }

        footer p {
            opacity: 0.6;
            font-size: 0.9rem;
        }

        /* --- Animations --- */
        @keyframes bounce {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
        }

        /* --- Responsive --- */
        @media (max-width: 900px) {
            .container {
                grid-template-columns: 1fr;
            }

            .hero h1 {
                font-size: 2.5rem;
            }
        }
    </style>
</head>
