        document.addEventListener('DOMContentLoaded', () => {
            const track = document.getElementById('track');
            const cards = Array.from(document.querySelectorAll('.project-card'));
            const nextBtn = document.getElementById('nextBtn');
            const prevBtn = document.getElementById('prevBtn');

            let currentIndex = 0;
            const totalCards = cards.length;
            const rotateAngle = 360 / totalCards;
            const radius = 350; // Distance from center

            function updateCarousel() {
                cards.forEach((card, index) => {
                    // Calculate rotation for the whole track
                    const rotation = -currentIndex * rotateAngle;

                    // Calculate individual card position
                    // We rotate the card slightly to face the center
                    const cardRotation = index * rotateAngle;

                    // Apply transforms
                    // 1. Rotate the whole track
                    // 2. Push the card out by radius
                    // 3. Rotate the card back so it faces forward (optional, but looks better in 3D)

                    // Actually, let's do a simpler "Carousel" logic:
                    // Rotate the container, translate Z, rotate the item back.

                    const angle = (index - currentIndex) * rotateAngle;

                    card.style.transform = `
                        rotateY(${angle}deg) 
                        translateZ(${radius}px) 
                        rotateY(${-angle}deg)
                    `;

                    // Adjust opacity based on distance from center (0 index)
                    // Normalize angle to -180 to 180
                    let normalizedAngle = angle % 360;
                    if (normalizedAngle > 180) normalizedAngle -= 360;
                    if (normalizedAngle < -180) normalizedAngle += 360;

                    const opacity = Math.max(0.3, 1 - (Math.abs(normalizedAngle) / 180));
                    const scale = Math.max(0.8, 1 - (Math.abs(normalizedAngle) / 400));

                    card.style.opacity = opacity;
                    card.style.zIndex = Math.round(scale * 10);
                    card.style.filter = `brightness(${opacity})`;
                });
            }

            nextBtn.addEventListener('click', () => {
                currentIndex = (currentIndex + 1) % totalCards;
                updateCarousel();
            });

            prevBtn.addEventListener('click', () => {
                currentIndex = (currentIndex - 1 + totalCards) % totalCards;
                updateCarousel();
            });

            // Initialize
            updateCarousel();
        });
    </script>
