      <h2 class="text-3xl text-center mb-6">Customer Reviews</h2>
      <!-- Add your customer reviews here -->
    </section>
  </div>

  <script>
    const toggleButton = document.getElementById('theme-toggle');
    const body = document.body;
    const overlay = document.getElementById('bg-overlay');
    const links = document.querySelectorAll('nav a');
    const buttons = document.querySelectorAll('button');
    const headings = document.querySelectorAll('h2');

    let isDark = false;

    toggleButton.addEventListener('click', () => {
      isDark = !isDark;

      if (isDark) {
        // Dark Mode Styles
        body.classList.remove('text-gray-900');
        body.classList.add('text-gray-100');

        // Adjust overlay to be lighter so text is readable on dark bg
        overlay.classList.remove('opacity-50');
        overlay.classList.add('opacity-30');

        // Change button style
        toggleButton.classList.remove('bg-white', 'text-gray-900');
        toggleButton.classList.add('bg-gray-800', 'text-white', 'border', 'border-gray-600');

        // Change link colors if needed (though white is usually fine on dark bg)
        links.forEach(link => {
            link.classList.remove('text-white');
            link.classList.add('text-gray-200');
        });

        headings.forEach(h => {
            h.classList.remove('text-gray-900');
            h.classList.add('text-gray-100');
        });

      } else {
        // Light Mode Styles
        body.classList.remove('text-gray-100');
        body.classList.add('text-gray-900');

        // Adjust overlay to be darker
        overlay.classList.remove('opacity-30');
        overlay.classList.add('opacity-50');

        // Change button style back
        toggleButton.classList.remove('bg-gray-800', 'text-white', 'border', 'border-gray-600');
        toggleButton.classList.add('bg-white', 'text-gray-900');

        // Change link colors back
        links.forEach(link => {
            link.classList.remove('text-gray-200');
            link.classList.add('text-white');
        });

        headings.forEach(h => {
            h.classList.remove('text-gray-100');
            h.classList.add('text-gray-900');
        });
      }
    });
  </script>
</body>
</html>
