<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ARCH | Minimalist Architecture</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --bg-color: #ffffff;
            --text-color: #1a1a1a;
            --accent-color: #555555;
            --overlay-color: rgba(0, 0, 0, 0.9);
            --font-main: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            --spacing-unit: 2rem;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--bg-color);
            color: var(--text-color);
            line-height: 1.6;
            overflow-x: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: opacity 0.3s ease;
        }

        a:hover {
            opacity: 0.6;
        }

        ul {
            list-style: none;
        }

        /* --- NAVIGATION --- */
        nav {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            padding: 2rem 3rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            z-index: 100;
            mix-blend-mode: difference; /* Ensures visibility on light/dark backgrounds */
            color: #fff;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .nav-links {
            display: flex;
            gap: 2rem;
        }

        .nav-links li a {
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            position: relative;
        }

        .nav-links li a::after {
            content: '';
            position: absolute;
            width: 0;
            height: 1px;
            bottom: -5px;
            left: 0;
            background-color: #fff;
            transition: width 0.3s ease;
        }

        .nav-links li a:hover::after {
            width: 100%;
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            width: 100%;
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
            overflow: hidden;
        }

        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: brightness(0.8);
            z-index: -1;
        }

        .hero-content {
            text-align: center;
            color: #fff;
            z-index: 1;
            padding: 0 1rem;
        }

        .hero-title {
            font-size: 4rem;
            font-weight: 300;
            letter-spacing: 5px;
            margin-bottom: 1rem;
            text-transform: uppercase;
        }

        .hero-subtitle {
            font-size: 1rem;
            letter-spacing: 3px;
            text-transform: uppercase;
            opacity: 0.8;
        }

        /* --- PORTFOLIO GRID --- */
        .portfolio {
            padding: 6rem 3rem;
            max-width: 1600px;
            margin: 0 auto;
        }

        .section-header {
            margin-bottom: 4rem;
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            border-bottom: 1px solid #eee;
            padding-bottom: 1rem;
        }

        .section-title {
            font-size: 2rem;
            font-weight: 400;
            letter-spacing: 1px;
        }

        .grid-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
            gap: 2rem;
        }

        .project-card {
            position: relative;
            overflow: hidden;
            cursor: pointer;
            aspect-ratio: 4/3;
        }

        .project-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
        }

        .project-card:hover img {
            transform: scale(1.05);
        }

        .project-info {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 1.5rem;
            background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
            color: #fff;
            opacity: 0;
            transform: translateY(10px);
            transition: all 0.4s ease;
        }

        .project-card:hover .project-info {
            opacity: 1;
            transform: translateY(0);
        }

        .project-name {
            font-size: 1.2rem;
            font-weight: 500;
            margin-bottom: 0.2rem;
        }

        .project-cat {
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            opacity: 0.8;
        }

        /* --- FOOTER --- */
        footer {
            background-color: #f4f4f4;
            padding: 4rem 3rem;
            margin-top: 4rem;
        }

        .footer-content {
            max-width: 1600px;
            margin: 0 auto;
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
            gap: 3rem;
        }

        .footer-brand h2 {
            font-size: 1.5rem;
            margin-bottom: 1rem;
            letter-spacing: 2px;
        }

        .footer-brand p {
            color: var(--accent-color);
            max-width: 300px;
            font-size: 0.9rem;
        }

        .footer-links h3 {
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 1.5rem;
        }

        .footer-links ul li {
            margin-bottom: 0.8rem;
        }

        .footer-links ul li a {
            color: var(--accent-color);
            font-size: 0.9rem;
        }

        .copyright {
            width: 100%;
            text-align: center;
            margin-top: 4rem;
            padding-top: 2rem;
            border-top: 1px solid #ddd;
            font-size: 0.8rem;
            color: var(--accent-color);
        }

        /* --- LIGHTBOX --- */
        .lightbox {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: var(--overlay-color);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 1000;
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.3s ease, visibility 0.3s ease;
            cursor: zoom-out;
        }

        .lightbox.active {
            opacity: 1;
            visibility: visible;
        }

        .lightbox-content {
            max-width: 90%;
            max-height: 90%;
            position: relative;
        }

        .lightbox-img {
            max-width: 100%;
            max-height: 85vh;
            object-fit: contain;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        .lightbox-caption {
            position: absolute;
            bottom: -40px;
            left: 0;
            color: #fff;
            font-size: 0.9rem;
            letter-spacing: 1px;
        }

        .close-btn {
            position: absolute;
            top: 2rem;
            right: 2rem;
            color: #fff;
            font-size: 2rem;
            cursor: pointer;
            line-height: 1;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            nav {
                padding: 1.5rem;
            }

            .nav-links {
                display: none; /* Simple hiding for mobile for this demo */
            }

            .hero-title {
                font-size: 2.5rem;
            }

            .portfolio {
                padding: 3rem 1.5rem;
            }

            .grid-container {
                grid-template-columns: 1fr;
            }

            .section-header {
                flex-direction: column;
                align-items: flex-start;
                gap: 1rem;
            }
        }
    </style>
</head>
