            color: #e67e22;
        }

        .dish-desc {
            font-size: 0.95rem;
            color: #777;
        }

        /* Right Column: Images */
        .image-column {
            position: relative;
        }

        .image-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 15px;
        }

        .food-card {
            border-radius: 12px;
            overflow: hidden;
            box-shadow: 0 4px 15px rgba(0,0,0,0.1);
            transition: transform 0.3s ease;
            background: #fff;
        }

