            color: #fff;
            text-align: center;
            padding: 40px 0;
            margin-top: 60px;
        }

        .footer-content p {
            opacity: 0.8;
            margin-bottom: 10px;
        }

        /* Responsive Design */
        @media (max-width: 900px) {
            .main-layout {
                grid-template-columns: 1fr;
            }

            .content-column {
                padding-right: 0;
                margin-bottom: 40px;
            }

            .image-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 600px) {
            .image-grid {
                grid-template-columns: 1fr;
            }

            .food-card.large {
                grid-column: span 1;
            }

            h1 {
                font-size: 2rem;
            }
        }
    </style>
