        .feature-card {
            text-align: center;
            padding: 40px 20px;
            border-radius: 10px;
            transition: var(--transition);
            border: 1px solid #eee;
        }

        .feature-card:hover {
            box-shadow: var(--shadow);
            transform: translateY(-5px);
            border-color: transparent;
        }

        .icon-box {
            width: 70px;
            height: 70px;
            background-color: rgba(0, 86, 179, 0.1);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 20px;
            color: var(--primary);
            font-size: 1.5rem;
        }

        .feature-card h3 {
            margin-bottom: 15px;
            color: var(--text-dark);
        }

        /* --- SERVICES --- */
        .services {
            padding: 80px 0;
            background-color: var(--bg-light);
        }

        .services-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 30px;
        }

        .service-card {
            background: var(--white);
            border-radius: 10px;
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: var(--transition);
        }

        .service-card:hover {
            transform: translateY(-5px);
        }

        .service-img {
            height: 200px;
            background-color: #ddd;
            background-size: cover;
            background-position: center;
        }

        .service-content {
            padding: 25px;
        }

        .service-content h3 {
            color: var(--primary);
            margin-bottom: 10px;
        }

        .service-content p {
            color: var(--text-light);
            font-size: 0.95rem;
            margin-bottom: 20px;
        }

        .read-more {
            color: var(--secondary);
            font-weight: 600;
            font-size: 0.9rem;
        }

        /* --- STATS --- */
        .stats {
            background-color: var(--primary);
            color: var(--white);
            padding: 60px 0;
        }

        .stats-grid {
            display: flex;
            justify-content: space-around;
            flex-wrap: wrap;
            text-align: center;
            gap: 30px;
        }

        .stat-item h3 {
            font-size: 3rem;
            margin-bottom: 5px;
        }

        .stat-item p {
            font-size: 1.1rem;
            opacity: 0.8;
        }

        /* --- TESTIMONIALS --- */
        .testimonials {
            padding: 80px 0;
        }

        .testimonial-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .testimonial-card {
            background: var(--bg-light);
            padding: 30px;
            border-radius: 10px;
            position: relative;
        }

        .quote-icon {
            font-size: 2rem;
            color: var(--secondary);
            opacity: 0.3;
            position: absolute;
            top: 20px;
            left: 20px;
        }

        .testimonial-text {
            margin: 20px 0;
            font-style: italic;
            color: var(--text-light);
        }

        .user-info {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .user-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background-color: #ccc;
            background-size: cover;
        }

        .user-details h4 {
            font-size: 1rem;
            color: var(--text-dark);
        }

        .user-details span {
            font-size: 0.85rem;
            color: var(--text-light);
        }

        /* --- CONTACT --- */
        .contact {
            padding: 80px 0;
            background-color: var(--bg-light);
        }

        .contact-container {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 50px;
            background: var(--white);
            padding: 50px;
            border-radius: 20px;
            box-shadow: var(--shadow);
        }

        .contact-info h3 {
            color: var(--primary);
            margin-bottom: 20px;
        }

        .info-item {
            display: flex;
            align-items: center;
            gap: 15px;
            margin-bottom: 20px;
        }

        .info-icon {
            width: 40px;
            height: 40px;
            background-color: rgba(0, 86, 179, 0.1);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--primary);
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
        }

        .form-group input,
        .form-group textarea {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            border-radius: 5px;
            font-family: inherit;
        }

        .form-group input:focus,
        .form-group textarea:focus {
            outline: none;
            border-color: var(--primary);
        }

        /* --- FOOTER --- */
        footer {
            background-color: #1a1a1a;
            color: #fff;
            padding: 60px 0 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h4 {
            font-size: 1.2rem;
            margin-bottom: 20px;
            color: var(--secondary);
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: #aaa;
            transition: var(--transition);
        }

        .footer-col ul li a:hover {
            color: var(--white);
        }

        .footer-bottom {
            border-top: 1px solid #333;
            padding-top: 20px;
            text-align: center;
            color: #777;
            font-size: 0.9rem;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .nav-links {
                display: none;
                position: absolute;
                top: 80px;
                left: 0;
                width: 100%;
                background-color: var(--white);
                flex-direction: column;
                padding: 20px;
                box-shadow: 0 4px 6px rgba(0,0,0,0.1);
                text-align: center;
            }

            .nav-links.active {
                display: flex;
            }

            .hamburger {
                display: block;
            }

            .nav-cta {
                display: none;
            }

            .hero h1 {
                font-size: 2.5rem;
            }

            .contact-container {
                grid-template-columns: 1fr;
                padding: 30px;
            }
        }
    </style>
