<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>LuxeLiving Real Estate</title>
    <style>
        /* --- Reset & Variables --- */
        :root {
            --primary-color: #1a252f; /* Dark Navy */
            --accent-color: #c0a32b; /* Muted Gold */
            --text-color: #333333;
            --light-bg: #f4f7f6;
            --white: #ffffff;
            --border-color: #e0e0e0;
            --shadow: 0 4px 6px rgba(0,0,0,0.1);
            --transition: all 0.3s ease;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            color: var(--text-color);
            line-height: 1.6;
            background-color: var(--light-bg);
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        img {
            max-width: 100%;
            display: block;
        }

        /* --- Header --- */
        header {
            background-color: var(--white);
            box-shadow: var(--shadow);
            position: sticky;
            top: 0;
            z-index: 1000;
        }

        .header-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 1rem 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--primary-color);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .logo span {
            color: var(--accent-color);
        }

        .search-bar {
            flex: 1;
            max-width: 500px;
            margin: 0 2rem;
            position: relative;
        }

        .search-bar input {
            width: 100%;
            padding: 10px 15px;
            border: 1px solid var(--border-color);
            border-radius: 25px;
            outline: none;
            transition: var(--transition);
        }

        .search-bar input:focus {
            border-color: var(--accent-color);
            box-shadow: 0 0 5px rgba(192, 163, 43, 0.3);
        }

        .search-bar button {
            position: absolute;
            right: 5px;
            top: 50%;
            transform: translateY(-50%);
            background-color: var(--primary-color);
            color: var(--white);
            border: none;
            padding: 6px 15px;
            border-radius: 20px;
            cursor: pointer;
            transition: var(--transition);
        }

        .search-bar button:hover {
            background-color: var(--accent-color);
        }

        nav ul {
            display: flex;
            gap: 20px;
        }

        nav a {
            font-weight: 500;
            color: var(--primary-color);
            transition: var(--transition);
        }

        nav a:hover {
            color: var(--accent-color);
        }

        /* --- Hero Section --- */
        .hero {
            background: linear-gradient(rgba(26, 37, 47, 0.7), rgba(26, 37, 47, 0.7)), url('https://images.unsplash.com/photo-1600596542815-27b88e31e62e?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80');
            background-size: cover;
            background-position: center;
            height: 500px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: var(--white);
            padding: 0 20px;
        }

        .hero h1 {
            font-size: 3rem;
            margin-bottom: 1rem;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
        }

        .hero p {
            font-size: 1.2rem;
            margin-bottom: 2rem;
            max-width: 600px;
        }

        .hero-btn {
            background-color: var(--accent-color);
            color: var(--white);
            padding: 12px 30px;
            border-radius: 5px;
            font-weight: 600;
            transition: var(--transition);
        }

        .hero-btn:hover {
            background-color: #a38a22;
            transform: translateY(-2px);
        }

        /* --- Main Content Layout --- */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 4rem 2rem;
        }

        .section-title {
            text-align: center;
            margin-bottom: 3rem;
        }

        .section-title h2 {
            font-size: 2rem;
            color: var(--primary-color);
            margin-bottom: 0.5rem;
        }

        .section-title .divider {
            width: 60px;
            height: 3px;
            background-color: var(--accent-color);
            margin: 0 auto;
        }

        /* --- Featured Listings --- */
        .listings-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .property-card {
            background: var(--white);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: var(--transition);
        }

        .property-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 20px rgba(0,0,0,0.15);
        }

        .card-image {
            height: 200px;
            overflow: hidden;
            position: relative;
        }

        .card-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .property-card:hover .card-image img {
            transform: scale(1.1);
        }

        .badge {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: var(--accent-color);
            color: var(--white);
            padding: 4px 10px;
            font-size: 0.8rem;
            border-radius: 4px;
            font-weight: 600;
        }

        .card-details {
            padding: 1.5rem;
        }

        .price {
            color: var(--accent-color);
            font-size: 1.25rem;
            font-weight: 700;
            margin-bottom: 0.5rem;
        }

        .address {
            font-size: 1rem;
            color: var(--primary-color);
            font-weight: 600;
            margin-bottom: 0.5rem;
        }

        .location {
            color: #777;
            font-size: 0.9rem;
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .features {
            display: flex;
            justify-content: space-between;
            border-top: 1px solid var(--border-color);
            padding-top: 1rem;
            color: #555;
            font-size: 0.9rem;
        }

        .features span {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        /* --- Property Types --- */
        .types-section {
            background-color: var(--white);
        }

        .types-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 1.5rem;
        }

        .type-card {
            background-color: var(--light-bg);
            padding: 2rem;
            text-align: center;
            border-radius: 8px;
            transition: var(--transition);
            cursor: pointer;
            border: 1px solid transparent;
        }

        .type-card:hover {
            border-color: var(--accent-color);
            background-color: var(--white);
            box-shadow: var(--shadow);
        }

        .type-icon {
            font-size: 2.5rem;
            margin-bottom: 1rem;
            color: var(--primary-color);
        }

        .type-card h3 {
            color: var(--primary-color);
            margin-bottom: 0.5rem;
        }

        /* --- Neighborhoods --- */
        .neighborhoods-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 2rem;
        }

        .neighborhood-card {
            position: relative;
            height: 300px;
            border-radius: 8px;
            overflow: hidden;
            cursor: pointer;
        }

        .neighborhood-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .neighborhood-card:hover img {
            transform: scale(1.05);
        }

        .neighborhood-overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
            padding: 2rem;
            color: var(--white);
        }

        .neighborhood-overlay h3 {
            font-size: 1.5rem;
            margin-bottom: 0.5rem;
        }

        /* --- Footer --- */
        footer {
            background-color: var(--primary-color);
            color: #ccc;
            padding: 4rem 2rem 1rem;
        }

        .footer-grid {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 3rem;
            margin-bottom: 3rem;
        }

        .footer-col h4 {
            color: var(--white);
            font-size: 1.2rem;
            margin-bottom: 1.5rem;
            position: relative;
            padding-bottom: 10px;
        }

        .footer-col h4::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: 0;
            width: 40px;
            height: 2px;
            background-color: var(--accent-color);
        }

        .footer-col p {
            margin-bottom: 1rem;
            font-size: 0.95rem;
        }

        .footer-links li {
            margin-bottom: 0.8rem;
        }

        .footer-links a:hover {
            color: var(--accent-color);
            padding-left: 5px;
            transition: var(--transition);
        }

        .social-links {
            display: flex;
            gap: 15px;
            margin-top: 1rem;
        }

        .social-icon {
            width: 35px;
            height: 35px;
            background-color: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            transition: var(--transition);
        }

        .social-icon:hover {
            background-color: var(--accent-color);
            color: var(--white);
        }

        /* Footer Search Form */
        .footer-search-form {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .footer-search-form input, 
        .footer-search-form select {
            padding: 10px;
            border: none;
            border-radius: 4px;
            background-color: rgba(255,255,255,0.1);
            color: var(--white);
        }

        .footer-search-form input::placeholder {
            color: #aaa;
        }

        .footer-search-form button {
            padding: 10px;
            background-color: var(--accent-color);
            color: var(--white);
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: 600;
            transition: var(--transition);
        }

        .footer-search-form button:hover {
            background-color: #a38a22;
        }

        .copyright {
            text-align: center;
            padding-top: 2rem;
            border-top: 1px solid rgba(255,255,255,0.1);
            font-size: 0.9rem;
        }

        /* --- Responsive --- */
        @media (max-width: 768px) {
            .header-container {
                flex-direction: column;
                gap: 1rem;
            }

            .search-bar {
                margin: 0;
                width: 100%;
            }

            nav ul {
                gap: 15px;
                font-size: 0.9rem;
            }

            .hero h1 {
                font-size: 2rem;
            }

            .neighborhoods-grid {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
