            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: var(--white);
        }

        .hero h1 {
            font-size: 4rem;
            margin-bottom: 1rem;
            color: var(--white);
            text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
        }

        .hero p {
            font-size: 1.2rem;
            margin-bottom: 2rem;
            letter-spacing: 1px;
        }

        .btn {
            padding: 1rem 2.5rem;
            background-color: var(--white);
            color: var(--primary-color);
            text-transform: uppercase;
            font-weight: 700;
            letter-spacing: 1px;
            border: 1px solid var(--white);
            cursor: pointer;
            transition: var(--transition);
        }

        .btn:hover {
            background-color: transparent;
            color: var(--white);
        }

        /* --- MAIN LAYOUT (Sidebar + Grid) --- */
        .container {
            display: flex;
            padding: 4rem 5%;
            gap: 3rem;
        }

        /* --- SIDEBAR --- */
        .sidebar {
            width: 250px;
            flex-shrink: 0;
        }

