            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .product-card:hover .image-container img {
            transform: scale(1.05);
        }

        .overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 1rem;
            background: rgba(255,255,255,0.9);
            display: flex;
            justify-content: space-between;
            align-items: center;
            transform: translateY(100%);
            transition: transform 0.3s ease;
        }

        .product-card:hover .overlay {
            transform: translateY(0);
        }

        .add-btn {
            background: var(--primary-color);
            color: var(--white);
            border: none;
            padding: 0.5rem 1rem;
            cursor: pointer;
            text-transform: uppercase;
            font-size: 0.8rem;
        }

        .product-info {
            padding: 1rem 0;
            text-align: center;
        }

        .product-title {
            font-size: 1.1rem;
            margin-bottom: 0.3rem;
            font-weight: 700;
        }

        .product-price {
            color: var(--accent-color);
            font-weight: 700;
        }

        /* --- LATEST COLLECTIONS (Banner) --- */
        .collections-banner {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1rem;
            margin: 4rem 5%;
        }

        .banner-item {
            position: relative;
            height: 400px;
            overflow: hidden;
        }

        .banner-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: brightness(0.8);
            transition: var(--transition);
        }

        .banner-item:hover img {
            filter: brightness(1);
            transform: scale(1.02);
        }

        .banner-content {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
            color: var(--white);
        }

        .banner-content h3 {
            color: var(--white);
            font-size: 2.5rem;
            margin-bottom: 1rem;
        }

        .btn-outline {
            padding: 0.8rem 2rem;
            border: 1px solid var(--white);
            color: var(--white);
            text-transform: uppercase;
            font-weight: 700;
            display: inline-block;
        }

        .btn-outline:hover {
            background: var(--white);
            color: var(--primary-color);
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 4rem 5% 1rem;
        }

        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 3rem;
            margin-bottom: 3rem;
        }

        .footer-col h4 {
            color: var(--white);
            margin-bottom: 1.5rem;
            font-size: 1.2rem;
            letter-spacing: 1px;
        }

        .footer-col ul li {
            margin-bottom: 0.8rem;
        }

        .footer-col ul li a {
            color: #aaa;
            font-size: 0.9rem;
        }

        .footer-col ul li a:hover {
            color: var(--white);
        }

        .newsletter-form {
            display: flex;
            margin-top: 1rem;
        }

        .newsletter-form input {
            padding: 0.8rem;
            border: none;
            width: 100%;
            outline: none;
        }

        .newsletter-form button {
            padding: 0.8rem 1.5rem;
            background: var(--accent-color);
            border: none;
            color: var(--white);
            cursor: pointer;
            font-weight: 700;
        }

        .copyright {
            text-align: center;
            border-top: 1px solid #333;
            padding-top: 2rem;
            color: #777;
            font-size: 0.8rem;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 900px) {
            .container {
                flex-direction: column;
            }
            .sidebar {
                width: 100%;
                margin-bottom: 2rem;
            }
            .hero h1 {
                font-size: 2.5rem;
            }
            .collections-banner {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
