<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>LuxeLiving | Premium Real Estate</title>
    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --primary: #1a252f;
            --accent: #c0a062; /* Gold/Bronze */
            --text-dark: #333;
            --text-light: #f4f4f4;
            --white: #ffffff;
            --overlay: rgba(0, 0, 0, 0.4);
            --transition: all 0.3s ease;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            color: var(--text-dark);
            background-color: #f9f9f9;
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        /* --- NAVIGATION --- */
        .navbar {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            padding: 1.5rem 5%;
            display: flex;
            justify-content: space-between;
            align-items: center;
            z-index: 1000;
            background: linear-gradient(to bottom, rgba(0,0,0,0.7), transparent);
        }

        .logo {
            font-size: 1.8rem;
            font-weight: 700;
            color: var(--white);
            letter-spacing: 2px;
            text-transform: uppercase;
            border: 2px solid var(--white);
            padding: 5px 15px;
        }

        .nav-links {
            display: flex;
            gap: 2rem;
        }

        .nav-links a {
            color: var(--white);
            font-weight: 500;
            font-size: 0.95rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            transition: var(--transition);
            position: relative;
        }

        .nav-links a::after {
            content: '';
            position: absolute;
            width: 0;
            height: 2px;
            bottom: -5px;
            left: 0;
            background-color: var(--accent);
            transition: var(--transition);
        }

        .nav-links a:hover::after {
            width: 100%;
        }

        .nav-links a:hover {
            color: var(--accent);
        }

        /* --- HERO SECTION --- */
        .hero {
            height: 100vh;
            width: 100%;
            background-image: url('https://images.unsplash.com/photo-1600596542815-27b88e31e62e?ixlib=rb-4.0.3&auto=format&fit=crop&w=2000&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.3);
        }

        .hero-content {
            position: relative;
            z-index: 1;
            width: 100%;
            max-width: 1200px;
            padding: 0 20px;
        }

        .hero-logo-large {
            font-size: 4rem;
            color: var(--white);
            font-weight: 800;
            margin-bottom: 0.5rem;
            text-shadow: 2px 2px 10px rgba(0,0,0,0.5);
            letter-spacing: 5px;
        }

        .hero-subtitle {
            color: var(--accent);
            font-size: 1.2rem;
            text-transform: uppercase;
            letter-spacing: 3px;
            margin-bottom: 3rem;
            font-weight: 600;
        }

        /* --- SEARCH BAR --- */
        .search-container {
            background: var(--white);
            padding: 15px;
            border-radius: 4px;
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.2);
            max-width: 900px;
            margin: 0 auto;
        }

        .search-group {
            flex: 1;
            min-width: 150px;
            display: flex;
            flex-direction: column;
            padding: 0 10px;
            border-right: 1px solid #eee;
        }

        .search-group:last-of-type {
            border-right: none;
        }

        .search-group label {
            font-size: 0.75rem;
            font-weight: 700;
            color: #888;
            text-transform: uppercase;
            margin-bottom: 5px;
        }

        .search-group select, 
        .search-group input {
            border: none;
            outline: none;
            font-size: 1rem;
            color: var(--text-dark);
            width: 100%;
            background: transparent;
            font-family: inherit;
        }

        .search-btn {
            background-color: var(--primary);
            color: var(--white);
            border: none;
            padding: 10px 30px;
            border-radius: 2px;
            cursor: pointer;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            transition: var(--transition);
            align-self: flex-end;
            height: 45px;
        }

        .search-btn:hover {
            background-color: var(--accent);
        }

        /* --- POPULAR AREAS --- */
        .section {
            padding: 5rem 5%;
        }

        .section-header {
            text-align: center;
            margin-bottom: 3rem;
        }

        .section-header h2 {
            font-size: 2.5rem;
            color: var(--primary);
            margin-bottom: 10px;
        }

        .section-header .divider {
            width: 60px;
            height: 3px;
            background-color: var(--accent);
            margin: 0 auto;
        }

        .areas-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 20px;
        }

        .area-card {
            position: relative;
            height: 300px;
            overflow: hidden;
            border-radius: 4px;
            cursor: pointer;
        }

        .area-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .area-card:hover img {
            transform: scale(1.1);
        }

        .area-overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            padding: 20px;
            background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
            color: var(--white);
        }

        .area-overlay h3 {
            font-size: 1.5rem;
            margin-bottom: 5px;
        }

        .area-overlay span {
            font-size: 0.9rem;
            color: var(--accent);
        }

        /* --- FEATURED PROPERTIES --- */
        .properties-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 30px;
        }

        .property-card {
            background: var(--white);
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
            transition: var(--transition);
            overflow: hidden;
            border-radius: 4px;
        }

        .property-card:hover {
            transform: translateY(-10px);
            box-shadow: 0 15px 30px rgba(0,0,0,0.1);
        }

        .property-image {
            position: relative;
            height: 250px;
            overflow: hidden;
        }

        .property-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .property-card:hover .property-image img {
            transform: scale(1.05);
        }

        .badge {
            position: absolute;
            top: 15px;
            left: 15px;
            background-color: var(--accent);
            color: var(--white);
            padding: 5px 12px;
            font-size: 0.8rem;
            font-weight: 700;
            text-transform: uppercase;
            border-radius: 2px;
        }

        .price-tag {
            position: absolute;
            bottom: 15px;
            right: 15px;
            background-color: var(--primary);
            color: var(--white);
            padding: 8px 15px;
            font-weight: 700;
            font-size: 1.1rem;
        }

        .property-details {
            padding: 25px;
        }

        .property-details h3 {
            font-size: 1.4rem;
            margin-bottom: 5px;
            color: var(--primary);
        }

        .property-location {
            color: #777;
            font-size: 0.95rem;
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .property-specs {
            display: flex;
            justify-content: space-between;
            border-top: 1px solid #eee;
            padding-top: 15px;
            color: #555;
            font-size: 0.9rem;
        }

        .spec-item {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--primary);
            color: var(--white);
            padding: 4rem 5% 2rem;
        }

        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 3rem;
        }

        .footer-col h4 {
            font-size: 1.2rem;
            margin-bottom: 1.5rem;
            color: var(--accent);
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: #ccc;
            transition: var(--transition);
        }

        .footer-col ul li a:hover {
            color: var(--white);
            padding-left: 5px;
        }

        .copyright {
            text-align: center;
            padding-top: 2rem;
            border-top: 1px solid rgba(255,255,255,0.1);
            color: #888;
            font-size: 0.9rem;
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .navbar {
                flex-direction: column;
                padding: 1rem;
            }

            .nav-links {
                margin-top: 1rem;
                gap: 1rem;
            }

            .hero-logo-large {
                font-size: 2.5rem;
            }

            .search-container {
                flex-direction: column;
            }

            .search-group {
                border-right: none;
                border-bottom: 1px solid #eee;
                padding: 10px 0;
            }

            .search-btn {
                width: 100%;
                margin-top: 10px;
            }
        }
    </style>
</head>
