    <style>
        /* --- Reset & Variables --- */
        :root {
            --primary-color: #003366; /* Deep Navy */
            --secondary-color: #D4AF37; /* Gold */
            --accent-color: #f4f4f4; /* Light Grey */
            --text-dark: #333333;
            --text-light: #666666;
            --white: #ffffff;
            --max-width: 1200px;
