            color: var(--text-dark);
            font-size: 1rem;
        }

        .nav-links a:hover {
            color: var(--primary-color);
        }

        .nav-cta {
            background-color: var(--primary-color);
            color: var(--white) !important;
            padding: 8px 16px;
            border-radius: 4px;
        }

        .nav-cta:hover {
            background-color: #002244;
        }

        /* --- Hero Section --- */
        .hero {
            height: 600px;
            background: linear-gradient(rgba(0, 51, 102, 0.7), rgba(0, 51, 102, 0.7)), 
