            gap: 30px;
        }

        .program-card {
            background: var(--white);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 4px 15px rgba(0,0,0,0.05);
            transition: transform 0.3s ease;
        }

        .program-card:hover {
            transform: translateY(-5px);
        }

        .card-image {
            height: 200px;
            background-color: #ddd;
            background-size: cover;
            background-position: center;
        }

        .card-content {
            padding: 25px;
        }

        .card-content h3 {
            color: var(--primary-color);
            margin-bottom: 10px;
            font-size: 1.4rem;
        }

        .card-content p {
            color: var(--text-light);
            margin-bottom: 20px;
            font-size: 0.95rem;
        }

        .card-link {
            color: var(--primary-color);
            font-weight: 600;
            display: inline-flex;
            align-items: center;
        }

        .card-link::after {
            content: '→';
            margin-left: 5px;
            transition: margin-left 0.2s;
        }

        .card-link:hover::after {
            margin-left: 10px;
        }

        /* --- About Section --- */
        .about {
            padding: 80px 0;
        }

        .about-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 50px;
            align-items: center;
        }

        .about-image {
            width: 100%;
            height: 400px;
            background: url('https://images.unsplash.com/photo-1524178232363-1fb2b075b655?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80') center/cover;
            border-radius: 8px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.1);
        }

        .about-text h2 {
            font-size: 2.2rem;
            color: var(--primary-color);
            margin-bottom: 20px;
        }

        .about-text p {
            color: var(--text-light);
            margin-bottom: 20px;
        }

        /* --- Footer --- */
        footer {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 60px 0 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-col h4 {
            font-size: 1.2rem;
            margin-bottom: 20px;
            color: var(--secondary-color);
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: #ccc;
        }

        .footer-col ul li a:hover {
            color: var(--white);
        }

        .footer-bottom {
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 20px;
            text-align: center;
            font-size: 0.9rem;
            color: #aaa;
        }

        /* --- Responsive Design --- */
        @media (max-width: 768px) {
            .nav-links {
                display: none; /* In a real scenario, this would be a hamburger menu */
            }

            .hero-content h1 {
                font-size: 2.5rem;
            }

            .stats-grid {
                grid-template-columns: 1fr 1fr;
                gap: 30px;
            }

            .about-layout {
                grid-template-columns: 1fr;
            }

            .about-image {
                height: 300px;
            }
        }
    </style>
</head>
