        }

        a {
            text-decoration: none;
            color: inherit;
            transition: color 0.3s ease;
        }

        ul {
            list-style: none;
        }

        /* --- Header & Navigation --- */
        header {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
