        .logo span {
            color: #e6a15a; /* Accent color */
        }

        nav ul {
            display: flex;
            gap: 30px;
        }

        nav a {
            color: #fff;
            font-weight: 500;
            font-size: 1rem;
            text-shadow: 1px 1px 3px rgba(0,0,0,0.5);
        }

        nav a:hover {
            color: #e6a15a;
        }

        /* --- Hero Section --- */
        .hero {
            height: 85vh;
            width: 100%;
            /* Horizontal image of a delicious meal */
            background-image: linear-gradient(rgba(0, 0, 0, 0.4), rgba(0, 0, 0, 0.4)), url('https://images.unsplash.com/photo-1504674900247-0877df9cc836?q=80&w=2070&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
