            color: #fff;
        }

        .hero h1 {
            font-size: 4rem;
            margin-bottom: 10px;
            font-family: 'Georgia', serif;
            text-shadow: 2px 2px 8px rgba(0,0,0,0.6);
        }

        .hero p {
            font-size: 1.5rem;
            margin-bottom: 30px;
            font-weight: 300;
            text-shadow: 1px 1px 4px rgba(0,0,0,0.6);
        }

        .btn {
            padding: 12px 30px;
            background-color: #e6a15a;
            color: #fff;
            border: none;
            border-radius: 4px;
            font-size: 1rem;
            cursor: pointer;
            transition: background 0.3s;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .btn:hover {
            background-color: #c9823d;
        }

        /* --- Main Content Area --- */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 60px 20px;
        }

        .section-title {
            text-align: center;
            font-size: 2.5rem;
            color: #2c3e50;
            margin-bottom: 40px;
            font-family: 'Georgia', serif;
        }

        /* --- Footer Layout --- */
        footer {
            background-color: #222;
            color: #ddd;
            padding: 60px 20px 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 40px;
            max-width: 1200px;
            margin: 0 auto;
        }

        /* Footer Column: Map */
        .footer-map h3, .footer-contact h3, .footer-reservation h3 {
            color: #fff;
            margin-bottom: 20px;
            font-size: 1.4rem;
            border-bottom: 2px solid #e6a15a;
            display: inline-block;
            padding-bottom: 5px;
        }

        .map-container {
            width: 100%;
            height: 250px;
            background-color: #444;
            border-radius: 8px;
            overflow: hidden;
            position: relative;
        }

        /* Simulating a map with CSS/HTML since no external API keys */
        .map-placeholder {
            width: 100%;
            height: 100%;
            background-image: url('https://images.unsplash.com/photo-1524661135-423995f22d0b?q=80&w=1000&auto=format&fit=crop');
            background-size: cover;
            background-position: center;
            opacity: 0.7;
            transition: opacity 0.3s;
        }

        .map-placeholder:hover {
            opacity: 1;
        }

        .map-overlay {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0,0,0,0.7);
            color: #fff;
            padding: 10px 20px;
            border-radius: 4px;
            font-size: 0.9rem;
        }

        /* Footer Column: Contact */
        .contact-info p {
            margin-bottom: 15px;
            display: flex;
            align-items: center;
        }

        .contact-icon {
            margin-right: 10px;
            color: #e6a15a;
        }

        /* Footer Column: Reservation Form */
        .reservation-form {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .form-group input, 
        .form-group select, 
        .form-group textarea {
            width: 100%;
            padding: 12px;
            border: 1px solid #444;
            background-color: #333;
            color: #fff;
            border-radius: 4px;
            font-family: inherit;
        }

        .form-group input:focus, 
        .form-group select:focus, 
        .form-group textarea:focus {
            outline: none;
            border-color: #e6a15a;
        }

        .form-row {
            display: flex;
            gap: 10px;
        }

        .form-row .form-group {
            flex: 1;
        }

        .submit-btn {
            width: 100%;
            padding: 12px;
            background-color: #e6a15a;
            color: #fff;
            border: none;
            border-radius: 4px;
            font-weight: bold;
            cursor: pointer;
            transition: background 0.3s;
        }

        .submit-btn:hover {
            background-color: #c9823d;
        }

        /* Footer Bottom */
        .footer-bottom {
            text-align: center;
            margin-top: 50px;
            padding-top: 20px;
            border-top: 1px solid #444;
            font-size: 0.9rem;
            color: #888;
        }

        /* --- Responsive Design --- */
        @media (max-width: 900px) {
            .footer-grid {
                grid-template-columns: 1fr;
            }

            header {
                flex-direction: column;
                padding: 15px;
            }

            .logo {
                margin-right: 0;
                margin-bottom: 10px;
            }

            nav ul {
                gap: 15px;
            }
        }

        @media (max-width: 600px) {
            .hero h1 {
                font-size: 2.5rem;
            }

            .hero p {
                font-size: 1.1rem;
            }

            .form-row {
                flex-direction: column;
                gap: 15px;
            }
        }
    </style>
</head>
