            list-style: none;
        }

        /* NAVIGATION */
        nav {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            padding: 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            z-index: 1000;
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(5px);
        }

        .nav-logo {
            font-weight: 700;
            font-size: 1.2rem;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .menu-toggle {
            cursor: pointer;
            width: 30px;
            height: 20px;
            position: relative;
            z-index: 1002;
        }

        .menu-toggle span {
            display: block;
            width: 100%;
            height: 2px;
            background-color: #000;
            position: absolute;
            transition: all 0.3s ease;
        }

        .menu-toggle span:nth-child(1) { top: 0; }
        .menu-toggle span:nth-child(2) { top: 9px; }
        .menu-toggle span:nth-child(3) { top: 18px; }

        /* Hamburger Animation */
        .menu-toggle.active span:nth-child(1) {
            transform: rotate(45deg);
            top: 9px;
        }
        .menu-toggle.active span:nth-child(2) {
            opacity: 0;
        }
        .menu-toggle.active span:nth-child(3) {
            transform: rotate(-45deg);
            top: 9px;
        }

        /* Hidden Menu Overlay */
        .nav-menu {
            position: fixed;
            top: 0;
            right: -100%;
            width: 100%;
            height: 100vh;
            background-color: #000;
            color: #fff;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            transition: right 0.5s cubic-bezier(0.77, 0, 0.175, 1);
            z-index: 1001;
        }

        .nav-menu.open {
            right: 0;
        }

        .nav-menu li {
            margin: 1.5rem 0;
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.4s ease, transform 0.4s ease;
        }

        .nav-menu.open li {
            opacity: 1;
            transform: translateY(0);
        }

        /* Staggered animation for menu items */
        .nav-menu.open li:nth-child(1) { transition-delay: 0.1s; }
        .nav-menu.open li:nth-child(2) { transition-delay: 0.2s; }
        .nav-menu.open li:nth-child(3) { transition-delay: 0.3s; }
        .nav-menu.open li:nth-child(4) { transition-delay: 0.4s; }

