    <style>
        /* --- RESET & VARIABLES --- */
        :root {
            --primary: #008080; /* Teal */
            --secondary: #ff7f50; /* Coral */
            --accent: #ffd700; /* Gold */
            --dark: #2c3e50;
            --light: #f4f7f6;
            --white: #ffffff;
            --font-heading: 'Georgia', serif;
