            position: relative;
            border: 1px solid rgba(0,0,0,0.05);
        }

        .package-card.featured {
            background: var(--primary);
            color: var(--white);
            transform: scale(1.05);
            box-shadow: 0 20px 40px rgba(0, 128, 128, 0.2);
            z-index: 2;
        }

        .package-card.featured h3, 
        .package-card.featured .price, 
        .package-card.featured li {
            color: var(--white);
        }

        .package-card.featured .btn {
            background: var(--white);
            color: var(--primary);
        }

        .package-card h3 {
            font-family: var(--font-heading);
            font-size: 1.8rem;
            margin-bottom: 10px;
        }

        .package-price {
            font-size: 2.5rem;
            font-weight: bold;
            color: var(--dark);
            margin-bottom: 20px;
        }

        .package-price span {
            font-size: 1rem;
            font-weight: normal;
        }

        .package-features {
            list-style: none;
            margin-bottom: 30px;
        }

        .package-features li {
            margin-bottom: 10px;
            color: #555;
        }

        /* --- TESTIMONIALS --- */
        .testimonials {
            padding: 80px 0;
            background: linear-gradient(135deg, #fdfbfb 0%, #ebedee 100%);
        }

        .testimonial-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
            margin-top: 40px;
        }

        .testimonial-card {
            background: var(--white);
            padding: 30px;
            border-radius: 15px;
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
            position: relative;
        }

        .testimonial-card::before {
            content: '"';
            font-family: var(--font-heading);
            font-size: 5rem;
            color: var(--secondary);
            opacity: 0.2;
            position: absolute;
            top: -10px;
            left: 20px;
        }

        .testimonial-text {
            font-style: italic;
            margin-bottom: 20px;
            color: #555;
        }

        .user-info {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .user-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background-color: #ddd;
            object-fit: cover;
        }

        .user-details h4 {
            font-size: 1rem;
            color: var(--dark);
        }

        .user-details span {
            font-size: 0.85rem;
            color: #888;
        }

        /* --- CONTACT --- */
        .contact {
            padding: 80px 0;
            background-color: var(--white);
        }

        .contact-wrapper {
            display: flex;
            flex-wrap: wrap;
            gap: 50px;
            margin-top: 40px;
        }

        .contact-info {
            flex: 1;
            min-width: 300px;
        }

        .contact-item {
            display: flex;
            align-items: center;
            margin-bottom: 25px;
        }

        .icon-box {
            width: 50px;
            height: 50px;
            background-color: rgba(0, 128, 128, 0.1);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-right: 20px;
            color: var(--primary);
            font-size: 1.2rem;
        }

        .contact-form {
            flex: 1;
            min-width: 300px;
            background: var(--light);
            padding: 40px;
            border-radius: 20px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            margin-bottom: 8px;
            font-weight: 600;
            color: var(--dark);
        }

        .form-group input, 
        .form-group textarea {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            border-radius: 8px;
            font-family: inherit;
            transition: border-color 0.3s;
        }

        .form-group input:focus, 
        .form-group textarea:focus {
            outline: none;
            border-color: var(--primary);
        }

        /* --- FOOTER --- */
        footer {
            background-color: var(--dark);
            color: var(--white);
            padding: 50px 0 20px;
            text-align: center;
        }

        .footer-logo {
            font-family: var(--font-heading);
            font-size: 2rem;
            margin-bottom: 20px;
            display: inline-block;
        }

        .social-links {
            margin-bottom: 30px;
        }

        .social-links a {
            color: var(--white);
            margin: 0 10px;
            font-size: 1.2rem;
            text-decoration: none;
            transition: color 0.3s;
        }

        .social-links a:hover {
            color: var(--secondary);
        }

        .copyright {
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 20px;
            font-size: 0.9rem;
            color: #aaa;
        }

        /* --- ANIMATIONS --- */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 768px) {
            .hero-content h1 { font-size: 2.5rem; }
            .nav-links { display: none; } /* Simplified for single file demo */
            .logo { margin-left: 20px; }
            .package-card.featured { transform: scale(1); }
        }
    </style>
