            outline: none;
            border-color: var(--white);
        }

        .submit-btn {
            background-color: var(--white);
            color: #222;
            border: none;
            padding: 1rem;
            cursor: pointer;
            text-transform: uppercase;
            font-weight: bold;
            letter-spacing: 0.1em;
            transition: var(--transition);
        }

        .submit-btn:hover {
            background-color: var(--accent-color);
            color: var(--white);
        }

        .social-icons {
            display: flex;
            gap: 1.5rem;
            margin-top: 2rem;
