            font-size: 1.2rem;
            color: #ddd;
            margin-bottom: 30px;
            max-width: 700px;
            margin-left: auto;
            margin-right: auto;
        }

        /* --- FEATURES --- */
        .features {
            background-color: var(--dark-bg);
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
        }

        .feature-card {
            background-color: var(--card-bg);
            padding: 40px 30px;
            text-align: center;
            border-radius: 5px;
            transition: var(--transition);
        }

        .feature-card:hover {
            transform: translateY(-10px);
            background-color: #252525;
        }

        .feature-icon {
            font-size: 3rem;
            color: var(--primary);
            margin-bottom: 20px;
        }

        .feature-card h3 {
            margin-bottom: 15px;
            font-size: 1.2rem;
            text-transform: uppercase;
        }

        .feature-card p {
            color: var(--text-gray);
            font-size: 0.9rem;
        }

        /* --- CLASSES --- */
        .classes {
            background-color: #0a0a0a;
        }

        .class-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
