            font-size: 1.2rem;
        }

        .contact-form {
            background-color: var(--card-bg);
            padding: 40px;
            border-radius: 5px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group input,
        .form-group textarea {
            width: 100%;
            padding: 15px;
            background-color: #121212;
            border: 1px solid #333;
            color: var(--text-light);
            border-radius: 3px;
            font-family: inherit;
        }

        .form-group input:focus,
        .form-group textarea:focus {
            outline: none;
            border-color: var(--primary);
        }

        /* --- FOOTER --- */
        footer {
            background-color: #000;
            padding: 50px 0 20px;
            text-align: center;
            border-top: 1px solid #222;
        }

        .footer-logo {
            font-size: 1.5rem;
            font-weight: 800;
            margin-bottom: 20px;
