const Button = ({ 
  children, 
  variant = 'primary', 
  className = '', 
  onClick 
}: { 
  children: React.ReactNode; 
  variant?: 'primary' | 'secondary' | 'outline'; 
  className?: string;
  onClick?: () => void;
}) => {
  const baseStyles = "inline-flex items-center justify-center px-6 py-3 border text-base font-medium rounded-md transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-offset-2";

  const variants = {
    primary: "border-transparent text-white bg-stone-700 hover:bg-stone-800 focus:ring-stone-500 shadow-lg hover:shadow-xl",
    secondary: "border-transparent text-stone-900 bg-amber-600 hover:bg-amber-700 focus:ring-amber-500 shadow-md",
    outline: "border-stone-300 text-stone-700 bg-transparent hover:bg-stone-50 focus:ring-stone-500"
  };

  return (
    <button onClick={onClick} className={`${baseStyles} ${variants[variant]} ${className}`}>
      {children}
    </button>
  );
};

