            {[25, 50, 100].map((val) => (
              <button
                key={val}
                onClick={() => { setAmount(val); setCustomAmount(''); }}
                className={`py-3 rounded-md border font-medium transition-colors ${
                  amount === val && !customAmount 
                    ? 'bg-amber-600 text-white border-amber-600' 
                    : 'bg-white text-stone-700 border-stone-300 hover:border-amber-500'
                }`}
              >
                ${val}
              </button>
            ))}
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-stone-700 mb-2">Custom Amount</label>
            <div className="relative rounded-md shadow-sm">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <span className="text-stone-500 sm:text-sm">$</span>
              </div>
              <input
                type="number"
                className="focus:ring-amber-500 focus:border-amber-500 block w-full pl-7 sm:text-sm border-stone-300 rounded-md py-3"
                placeholder="0.00"
                value={customAmount}
                onChange={(e) => { setCustomAmount(e.target.value); setAmount(Number(e.target.value)); }}
              />
            </div>
          </div>

          <Button variant="primary" className="w-full" onClick={() => { alert('Thank you for your generosity!'); onClose(); }}>
            Donate Now
          </Button>
        </div>
      </div>
    </div>
  );
};

