const Gallery = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % ART_PIECES.length);
  };

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev - 1 + ART_PIECES.length) % ART_PIECES.length);
  };

  useEffect(() => {
    if (!isAutoPlaying) return;
    const timer = setInterval(nextSlide, 5000);
    return () => clearInterval(timer);
  }, [isAutoPlaying]);

  const currentArt = ART_PIECES[currentIndex];

  return (
    <section id="gallery" className="py-12 px-6 max-w-7xl mx-auto">
      <div className="flex flex-col lg:flex-row gap-12 items-center">

        {/* Main Image Area */}
        <div 
          className="relative w-full lg:w-2/3 aspect-[4/5] bg-gray-100 overflow-hidden shadow-2xl group"
          onMouseEnter={() => setIsAutoPlaying(false)}
          onMouseLeave={() => setIsAutoPlaying(true)}
        >
          <img 
            src={currentArt.imageUrl} 
            alt={currentArt.title}
            className="w-full h-full object-cover transition-transform duration-700 ease-in-out transform group-hover:scale-105"
          />

          {/* Overlay Controls */}
          <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-between px-4">
            <button 
              onClick={prevSlide}
              className="p-3 bg-white/20 backdrop-blur-sm rounded-full text-white hover:bg-white/40 transition-colors"
            >
              <ArrowLeftIcon />
            </button>
            <button 
              onClick={nextSlide}
              className="p-3 bg-white/20 backdrop-blur-sm rounded-full text-white hover:bg-white/40 transition-colors"
            >
              <ArrowRightIcon />
            </button>
          </div>

          {/* Slide Indicators */}
          <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 flex space-x-2">
            {ART_PIECES.map((_, idx) => (
              <button
                key={idx}
                onClick={() => setCurrentIndex(idx)}
                className={`h-1.5 rounded-full transition-all duration-300 ${
                  idx === currentIndex ? 'w-8 bg-white' : 'w-2 bg-white/50'
                }`}
              />
            ))}
          </div>
        </div>

        {/* Art Details */}
        <div className="w-full lg:w-1/3 flex flex-col justify-center h-full">
          <div className="mb-8">
            <span className="text-sm font-bold tracking-widest text-gray-400 uppercase mb-2 block">
              Featured Piece
            </span>
            <h2 className="text-4xl font-serif font-bold text-gray-900 mb-2">
              {currentArt.title}
            </h2>
            <p className="text-lg text-gray-600 italic mb-4">
              by {currentArt.artist} ({currentArt.year})
            </p>
            <p className="text-gray-600 leading-relaxed border-l-2 border-gray-200 pl-4">
              {currentArt.description}
            </p>
          </div>

          <button className="self-start flex items-center space-x-2 text-gray-900 font-medium hover:text-gray-600 transition-colors group">
            <span>View Full Collection</span>
            <span className="transform group-hover:translate-x-1 transition-transform">
              <ArrowRightIcon />
            </span>
          </button>
        </div>
      </div>
    </section>
  );
};

