    <script>
        const toggleButton = document.getElementById('theme-toggle');
        const sunIcon = document.getElementById('sun-icon');
        const moonIcon = document.getElementById('moon-icon');
        const body = document.body;
        const header = document.querySelector('header');
        const footer = document.querySelector('footer');
        const cards = document.querySelectorAll('.bg-white');
        const inputs = document.querySelectorAll('input');

        // Check local storage for theme preference
        if (localStorage.getItem('theme') === 'dark') {
            body.classList.add('bg-gray-900', 'text-white');
            body.classList.remove('bg-gray-100', 'text-gray-900');
            header.classList.add('bg-gray-800');
            header.classList.remove('bg-white');
            footer.classList.add('bg-gray-800');
            footer.classList.remove('bg-white');
            cards.forEach(card => {
                card.classList.add('bg-gray-800', 'text-white');
                card.classList.remove('bg-white');
            });
            inputs.forEach(input => {
                input.classList.add('bg-gray-700', 'text-white', 'border-gray-600');
                input.classList.remove('bg-gray-50', 'text-gray-900');
            });
            sunIcon.classList.remove('hidden');
            moonIcon.classList.add('hidden');
        }

        toggleButton.addEventListener('click', () => {
            const isDark = body.classList.contains('bg-gray-900');

            if (isDark) {
                // Switch to Light
                body.classList.remove('bg-gray-900', 'text-white');
                body.classList.add('bg-gray-100', 'text-gray-900');

                header.classList.remove('bg-gray-800');
                header.classList.add('bg-white');

                footer.classList.remove('bg-gray-800');
                footer.classList.add('bg-white');

                cards.forEach(card => {
                    card.classList.remove('bg-gray-800', 'text-white');
                    card.classList.add('bg-white');
                });

                inputs.forEach(input => {
                    input.classList.remove('bg-gray-700', 'text-white', 'border-gray-600');
                    input.classList.add('bg-gray-50', 'text-gray-900');
                });

                sunIcon.classList.add('hidden');
                moonIcon.classList.remove('hidden');
                localStorage.setItem('theme', 'light');
            } else {
                // Switch to Dark
                body.classList.remove('bg-gray-100', 'text-gray-900');
                body.classList.add('bg-gray-900', 'text-white');

                header.classList.remove('bg-white');
                header.classList.add('bg-gray-800');

                footer.classList.remove('bg-white');
                footer.classList.add('bg-gray-800');

                cards.forEach(card => {
                    card.classList.remove('bg-white');
                    card.classList.add('bg-gray-800', 'text-white');
                });

                inputs.forEach(input => {
                    input.classList.remove('bg-gray-50', 'text-gray-900');
                    input.classList.add('bg-gray-700', 'text-white', 'border-gray-600');
                });

                sunIcon.classList.remove('hidden');
                moonIcon.classList.add('hidden');
                localStorage.setItem('theme', 'dark');
            }
        });
    </script>
</body>
